  function syncStepSelect(el, khz) {
    if (!el) return;
    khz = Number(khz);
    if (!isFinite(khz) || khz <= 0) khz = 12.5;
    var opts = el.options;
    var i, found = false;
    for (i = 0; i < opts.length; i++) {
      if (Math.abs(Number(opts[i].value) - khz) < 0.0005) {
        el.selectedIndex = i;
        found = true;
        break;
      }
    }
    if (!found) {
      var o = document.createElement("option");
      o.value = String(khz);
      o.textContent = khz + " kHz";
      el.insertBefore(o, el.firstChild);
      el.selectedIndex = 0;
    }
  }

