  MORE_GROUPS.forEach(function (g) {
    MORE_GROUP_META[g.id] = g;
    (g.panes || []).forEach(function (p) {
      MORE_SUB_IDS.push(p.id);
      MORE_SUBS[p.id] = 1;
      MORE_SUB_LABELS[p.id] = p.lab;
      MORE_PANE_GROUP[p.id] = g.id;
    });
  });

