  var EXTRA_SUB_CORE = {
    log: { feed: 1, qso: 1, calls: 1, archive: 1 },
    watch: { list: 1, groups: 1, snooze: 1 },
    bookmarks: { list: 1, options: 1 },
    audio: { list: 1, record: 1, filters: 1 },
    skip: { lists: 1 },
    peaks: { main: 1 },
    range: { scan: 1 }
  };
  function extraSubKey(tab, id) { return tab + ":" + id; }
  function isExtraSubHidden(tab, id) {
    if (!id) return true;
    if (EXTRA_SUB_CORE[tab] && EXTRA_SUB_CORE[tab][id]) return false;
    var list = S.hiddenExtraSubs;
    return Array.isArray(list) && list.indexOf(extraSubKey(tab, id)) >= 0;
  }
  function extraSubDefsFor(tab) {
    return EXTRA_SUB_DEFS.filter(function (d) { return d.tab === tab; });
  }
  function firstVisibleExtraSub(tab, fallback) {
    var core = EXTRA_SUB_CORE[tab] || {};
    var ids = Object.keys(core);
    var i, d;
    for (i = 0; i < ids.length; i++) if (!isExtraSubHidden(tab, ids[i])) return ids[i];
    var extras = extraSubDefsFor(tab);
    for (i = 0; i < extras.length; i++) {
      d = extras[i];
      if (!isExtraSubHidden(tab, d.id)) return d.id;
    }
    return fallback;
  }


  function panelMainTabButtonsHtml() {
    return TAB_BAR_IDS.map(function (id, i) {
      var m = TAB_HEAD_META[id] || { lab: id, title: id };
      var on = i === 0 ? " bs-tab-on" : "";
      return (
        '<button type="button" class="bs-tab' + on + '" data-tab="' + id + '" role="tab" title="' + m.title + '">' +
        m.lab + "</button>"
      );
    }).join("");
  }

  function mainTabBarOrderOk() {
    var bar = $("bs-tabs");
    if (!bar) return true;
    var seen = [];
    Array.prototype.forEach.call(bar.querySelectorAll(".bs-tab[data-tab]"), function (btn) {
      var id = btn.getAttribute("data-tab");
      if (id) seen.push(id);
    });
    if (seen.length !== TAB_BAR_IDS.length) return false;
    for (var i = 0; i < TAB_BAR_IDS.length; i++) {
      if (seen[i] !== TAB_BAR_IDS[i]) return false;
    }
    return true;
  }

  function syncMainTabOrder() {
    var bar = $("bs-tabs");
    if (bar) {
      TAB_BAR_IDS.forEach(function (id) {
        var btn = bar.querySelector('.bs-tab[data-tab="' + id + '"]');
        if (btn) bar.appendChild(btn);
      });
    }
    var body = $("bs-body");
    if (body) {
      TAB_IDS.forEach(function (id) {
        var pane = document.getElementById("bs-tab-" + id);
        if (pane) body.appendChild(pane);
      });
    }
  }

