  function applyTabDensity() {
    var panel = $("bs-panel");
    if (!panel) return;
    if (S.uiDensity !== "minimal") S.uiDensity = "full";
    if (!S.tabDensity || typeof S.tabDensity !== "object") S.tabDensity = {};
    panel.setAttribute("data-bs-density", S.uiDensity);
    Array.prototype.forEach.call(panel.querySelectorAll(".bs-tab-pane[data-tab]"), function (pane) {
      var id = pane.getAttribute("data-tab");
      if (!id) return;
      var mode = tabViewDensity(id);
      pane.setAttribute("data-bs-tab-density", mode);
      if (mode === "minimal") {
        try {
          if (id === "bands" && typeof setBandsSubTab === "function") {
            var bdOn = pane.querySelector(".bs-bd-sub.bs-bd-sub-on");
            if (bdOn && bdOn.getAttribute("data-bd-sub") !== "list") setBandsSubTab("list", { skipSave: true });
          }
          if (id === "bookmarks" && typeof setBookmarkSubTab === "function") {
            var bmOn = pane.querySelector(".bs-bm-sub.bs-bm-sub-on");
            if (bmOn && bmOn.getAttribute("data-bm-sub") !== "list") setBookmarkSubTab("list", { skipSave: true });
          }
          if (id === "range" && typeof setRangeSubTab === "function") {
            setRangeSubTab("scan", { skipSave: true });
          }
          if (id === "audio" && typeof setAudioSubTab === "function") {
            var auOn = pane.querySelector(".bs-au-sub.bs-au-sub-on");
            if (auOn && auOn.getAttribute("data-au-sub") !== "list") setAudioSubTab("list", { skipSave: true });
          }
        } catch (eSub) {}
      }
    });
    var cur = currentPanelTab() || "explore";
    var headBtn = $("bs-density-tog");
    if (headBtn) {
      var headMode = tabViewDensity(cur);
      var headMin = headMode === "minimal";
      headBtn.classList.toggle("bs-on", headMin);
      headBtn.setAttribute("aria-pressed", headMin ? "true" : "false");
      headBtn.setAttribute("data-bs-density-tab", cur);
      headBtn.textContent = headMin ? "F" : "M";
      setHoverTip(headBtn, headMin
        ? ("Full view on " + cur + " — show all controls (Settings default is still “" +
          (S.uiDensity === "minimal" ? "Minimal" : "Full") + "”).")
        : ("Minimal on " + cur + " — only the most useful controls."));
    }
    Array.prototype.forEach.call(panel.querySelectorAll("[data-bs-density-tab]"), function (btn) {
      if (btn.id === "bs-density-tog") return;
      var id = btn.getAttribute("data-bs-density-tab");
      var mode = tabViewDensity(id);
      var minimal = mode === "minimal";
      btn.classList.toggle("bs-on", minimal);
      btn.setAttribute("aria-pressed", minimal ? "true" : "false");
      btn.textContent = minimal ? "Full view" : "Minimal";
      setHoverTip(btn, minimal
        ? "Show full controls on this tab (Settings default is still “" +
          (S.uiDensity === "minimal" ? "Minimal" : "Full") + "”)."
        : "Show only the most useful controls on this tab.");
    });
    if ($("bs-ui-density")) $("bs-ui-density").value = S.uiDensity === "minimal" ? "minimal" : "full";
  }

