    var minComfortW = Math.min(FLOAT_PANEL_W_DEFAULT, Math.max(720, Math.floor(vw * 0.58)));
    if (w < minComfortW) return true;
    if (vh >= FLOAT_PANEL_H_MIN + 8 && h > 40 && h < FLOAT_PANEL_H_MIN) return true;
    return false;
