    try {
      if (tune && tune.parentNode !== cons) {
        cons.insertBefore(tune, cons.firstChild);
        moved = true;
      }
      if (deck.parentNode !== cons) {
        cons.appendChild(deck);
        moved = true;
      }
      if (tune && tune.parentNode === cons && deck.parentNode === cons && tune.nextSibling !== deck) {
        cons.insertBefore(tune, deck);
        moved = true;
      }
    } catch (eMv) {}
    return moved;
