      if (order.indexOf(boxId) >= 0) return;
      if (boxId === "bs-ex-box-here" || boxId === "bs-ex-box-recent" || boxId === "bs-ex-box-listen" ||
          EX_LIGHT_BOX_IDS.indexOf(boxId) >= 0) {
        order.push(boxId);
        return;
      }
      var after = boxId === "bs-ex-box-gain" ? "bs-ex-box-radio" : "bs-ex-box-vfo";
      var ai = order.indexOf(after);
