  function applyHiddenExploreBoxes() {
    if (!Array.isArray(S.hiddenExploreBoxes)) S.hiddenExploreBoxes = [];
    S.hiddenExploreBoxes = S.hiddenExploreBoxes.filter(function (id) {
      return EX_BOX_VIS_DEFS.some(function (d0) { return d0.id === id; });
    });
    var root = $("bs-tab-explore");
    if (root) {
      EX_BOX_VIS_DEFS.forEach(function (d) {
        var el = $(d.id) || root.querySelector("." + d.id);
        if (!el) return;
        var hide = isExploreBoxHidden(d.id);
        el.hidden = hide;
        if (hide) {
          el.setAttribute("hidden", "");
          el.setAttribute("aria-hidden", "true");
        } else {
          el.removeAttribute("hidden");
          el.removeAttribute("aria-hidden");
        }
      });
    }
    fillExploreBoxesForm();
    try {
      if (currentPanelTab() === "explore") {
        requestAnimationFrame(function () {
          try { ensureExploreBoxesPacked(); } catch (ePk) {}
          try { scheduleExploreMasonryRepack(); } catch (eRp) {}
        });
      }
    } catch (eEx) {}
    try { exploreListenSync(); } catch (eLis) {}
    try {
      if (currentPanelTab() === "explore") exploreLightBoxesOnTab();
      else exploreLightBoxesStop();
    } catch (eLight) {}
  }

