    var box = $("bs-visible-more");
    if (!box) return;
    var hidden = [];
    eachMoreSubVisInput(function (inp) {
      var id = inp.getAttribute("data-more-sub");
      if (!id || !MORE_SUBS[id]) return;
      if (!inp.checked) hidden.push(id);
    });
    /* Keep at least one More section visible. */
    if (hidden.length >= MORE_SUB_IDS.length) {
      hidden = MORE_SUB_IDS.filter(function (id) { return id !== "dx"; });
      setStatus("Keep at least one More section on.");
    }
    S.hiddenMoreSubs = hidden;
