  function runUxTask(task) {
    if (!uxFeelOn("taskEntry")) return;
    if (task === "tune") {
      switchTab("explore", true);
      setStatus("Task: Tune around — Explore LCD / Go.");
    } else if (task === "scan") {
      switchTab("bands", true);
      setStatus("Task: Scan bands — tick bands, then Scan bands.");
    } else if (task === "peaks") {
      switchTab("peaks", true);
      setStatus("Task: Review peaks.");
    } else if (task === "bookmarks") {
      switchTab("bookmarks", true);
      setStatus("Task: Scan / manage bookmarks.");
    }
  }

  function removeTabContextMenuUi() {
    try {
      var menu = $("bs-tab-menu");
      if (menu && menu.parentNode) menu.parentNode.removeChild(menu);
    } catch (eRm) {}
  }

  function tryOpenTabContextMenu(ev) {
    return false;
  }

  function closeTabContextMenu() {
    removeTabContextMenuUi();
  }

  /** @deprecated alias — wiring lives in bindBtnShadePicker (boot + panel). */
  function bindTabContextMenu(panel) {
    removeTabContextMenuUi();
    bindBtnShadePicker(panel || $("bs-panel") || null);
  }

  function currentPanelTab() {
    var helpOn = panelQs("#bs-tab-help.bs-tab-on") || panelQs("#bs-help-tog.bs-on");
    if (helpOn) return "help";
    var on = panelQs("#bs-tabs .bs-tab.bs-tab-on");
    return (on && on.getAttribute("data-tab")) || "";
  }

  function setElHidden(el, hide) {
    if (!el) return;
    el.hidden = !!hide;
  }

  /** Keep scan status on the same row as the visible Stop button. */
  function syncStatusPlacement(showBm, showStatus) {
    var st = $("bs-status");
    var tb = $("bs-toolbar");
    var prog = $("bs-tb-progress");
    if (!st || !tb) return;
    if (!showStatus) return;
    var stopEl = null;
    if (showBm) {
      var bmStop = $("bs-stop-bm");
      if (bmStop && !bmStop.hidden) stopEl = bmStop;
    } else {
      var bandStop = $("bs-stop");
      if (bandStop && !bandStop.hidden) stopEl = bandStop;
    }
    if (stopEl) {
      if (stopEl.nextElementSibling !== st) stopEl.insertAdjacentElement("afterend", st);
      return;
    }
    if (prog && st.nextElementSibling !== prog) tb.insertBefore(st, prog);
    else if (st.parentNode !== tb) tb.appendChild(st);
  }

  function syncHideToolbarFromScanStripUi() {
    var show = $("bs-show-scan-strip");
    if (show) {
      S.hideToolbar = !show.checked;
      return;
    }
    var leg = $("bs-hide-toolbar");
    if (leg) S.hideToolbar = !!leg.checked;
  }

  function syncScanStripPrefUiFromS() {
    var hide = !!S.hideToolbar;
    var show = $("bs-show-scan-strip");
    if (show) show.checked = !hide;
    var leg = $("bs-hide-toolbar");
    if (leg) leg.checked = hide;
  }

  function migrateScanStripPrefUi() {
    var leg = $("bs-hide-toolbar");
    var show = $("bs-show-scan-strip");
    if (!leg || !show) return;
    show.checked = !leg.checked;
    S.hideToolbar = !show.checked;
    try {
      var lab = leg.closest("label");
      if (lab) lab.parentNode.removeChild(lab);
    } catch (eRm) {}
  }

  function wireScanStripPref() {
    migrateScanStripPrefUi();
    var el = $("bs-show-scan-strip");
    if (!el || el._bsScanStripWired) return;
    el._bsScanStripWired = true;
    el.addEventListener("change", function () {
      S.hideToolbar = !el.checked;
      try { saveSettings(); } catch (eSave) {}
      try { applyToolbarVisibility(); } catch (eVis) {}
      setStatus(el.checked
        ? "Scan strip on for Bands / Bookmarks."
        : "Scan strip hidden until a scan runs.");
    });
  }

  function applyToolbarVisibility() {
    var tb = $("bs-toolbar");
    var p = $("bs-panel");
    var hidePref = !!S.hideToolbar;
    var tab = currentPanelTab();
    var survey = !!(running || surveyRunning);
    var listen = !!listenScanRunning;
    var busy = survey || listen;
    /* While a scan is running, always show Stop + status — even if “Show scan
       strip” is off. Otherwise Stop vanishes and looks dead. */
    var hideChrome = hidePref && !busy;
    try { applyToolboxFindVisibility(); } catch (eFindVis) {}
    try { applyMinimalButtonVisibility(); } catch (eMinVis) {}
    if (p) p.classList.toggle("bs-hide-toolbar", hideChrome);

    var showBand = !hideChrome && tab === "bands";
    var showBm = !hideChrome && (tab === "bookmarks" || listen);
    var showBusyStop = !hideChrome && busy && !showBand && !showBm;
    var showStatus = !hideChrome && (showBand || showBm || showBusyStop || busy);
    var showAny = showBand || showBm || showBusyStop || showStatus;

    setElHidden($("bs-tb-bands-note"), !showBand);
    setElHidden($("bs-tb-bands-box"), !(showBand || showBusyStop));
    setElHidden($("bs-tb-band-row"), !(showBand || showBusyStop));
    setElHidden($("bs-bands-scan-opts"), !showBand);
    setElHidden($("bs-start"), !showBand);
    setElHidden($("bs-fresh"), !showBand);
    setElHidden($("bs-selcount"), !showBand);
    setElHidden($("bs-stop"), !(showBand || showBusyStop));
    setElHidden($("bs-tb-bm-row"), !showBm);
    setElHidden($("bs-status"), !showStatus);
    setElHidden($("bs-tb-progress"), !showStatus);
    if (tb) {
      tb.hidden = hideChrome || !showAny;
      tb.classList.toggle("bs-tb-bands-on", !!showBand);
      tb.classList.toggle("bs-tb-busy-on", !!showBusyStop && !showBand);
    }
    syncStatusPlacement(showBm, showStatus);
    syncScanStripPrefUiFromS();
  }

  /** Tell owrx_hush / owrx_quiet whether to mute when this tab is backgrounded. Default on. */
  function applyMuteOnTabHidePref() {
    var on = S.muteOnTabHide !== false;
    try { Plugins.toolbox.muteOnTabHide = on; } catch (eP) {}
    try {
      window.localStorage.setItem("owrx_toolbox_mute_on_tab_hide", on ? "1" : "0");
    } catch (eLs) {}
    if ($("bs-mute-on-tab")) $("bs-mute-on-tab").checked = on;
    try { window.postMessage({ type: "owrx-mute-on-tab-pref", enabled: on }, "*"); } catch (eMsg) {}
    if (!on) {
      try { window.postMessage({ type: "owrx-unmute" }, "*"); } catch (eU) {}
    }
  }

  function applyStockReceiverVisibility() {
    var hide = !!S.hideStockReceiver;
    try {
      document.documentElement.classList.toggle("bs-hide-stock-rx", hide);
      document.body.classList.toggle("bs-hide-stock-rx", hide);
    } catch (e) {}
    if ($("bs-hide-stock-rx")) $("bs-hide-stock-rx").checked = hide;
    var el = $("openwebrx-panel-receiver");
    if (hide) {
      /* CSS class hides the panel. Do NOT set display:none / rotateX inline —
         owrx_hush / owrx_quiet treat that as a folded panel and mute audio.
         Toolbox hide means “use Explore”, not “stop listening”. */
      try {
        if (el) {
          /* Clear older Toolbox inline collapse leftovers. */
          if (el.style.display === "none") el.style.display = "";
          var tr = (el.style.transform || "").toLowerCase();
          if (tr.indexOf("rotatex(90") !== -1 || tr.indexOf("rotatex(-90") !== -1) {
            el.style.transform = "";
          }
        }
      } catch (eClr) {}
    } else {
      /* Un-hiding: drop any leftover inline hide so native toggle can open it. */
      try {
        if (el) {
          if (el.style.display === "none") el.style.display = "";
          var tr2 = (el.style.transform || "").toLowerCase();
          if (tr2.indexOf("rotatex(90") !== -1 || tr2.indexOf("rotatex(-90") !== -1) {
            el.style.transform = "";
          }
        }
      } catch (eShow) {}
    }
    /* Always tell hush/quiet to keep audio when Toolbox is the UI (panel open or closed). */
    try { window.postMessage({ type: "owrx-unmute" }, "*"); } catch (eMsg) {}
    try {
      if (window.UI && typeof UI.setVolume === "function" &&
          typeof UI.volume === "number" && UI.volume >= 0 &&
          !(UI.volumeMuted >= 0)) {
        UI.setVolume(UI.volume);
      }
    } catch (eVol) {}
  }

  /** Native top-bar Receiver must always be able to open the stock panel.
      If Toolbox "Hide stock receiver" is on, clear it on Receiver click. */
  function bindStockReceiverOpenUnhide() {
    var btn = document.querySelector('[data-toggle-panel="openwebrx-panel-receiver"]');
    if (!btn || btn.getAttribute("data-bs-rx-unhide") === "1") return;
    btn.setAttribute("data-bs-rx-unhide", "1");
    btn.addEventListener("click", function () {
      var hidden = !!S.hideStockReceiver;
      try {
        hidden = hidden
          || document.body.classList.contains("bs-hide-stock-rx")
          || document.documentElement.classList.contains("bs-hide-stock-rx");
      } catch (eCls) {}
      if (!hidden) return;
      S.hideStockReceiver = false;
      applyStockReceiverVisibility();
      try { saveSettings(); } catch (eSave) {}
      try { setStatus("Stock receiver panel shown again (Hide stock receiver was on)."); } catch (eSt) {}
    }, true);
  }

  function normalizeMainTabScalePct(raw) {
    var n = Number(raw);
    if (!isFinite(n)) n = 100;
    n = Math.round(n);
    if (n < 70) n = 70;
    if (n > 130) n = 130;
    return n;
  }

  function snapMainTabScalePct(pct) {
    pct = normalizeMainTabScalePct(pct);
    var presets = MAIN_TAB_SCALE_PRESETS || [75, 85, 100, 115, 125];
    if (presets.indexOf(pct) >= 0) return pct;
    var best = presets[0];
    presets.forEach(function (v) {
      if (Math.abs(v - pct) < Math.abs(best - pct)) best = v;
    });
    return best;
  }

  function normalizeUiScalePct(raw) {
    var n = Number(raw);
    if (!isFinite(n)) n = 100;
    n = Math.round(n);
    if (n < 70) n = 70;
    if (n > 125) n = 125;
    return n;
  }

  function snapUiScaleToPreset(pct) {
    pct = normalizeUiScalePct(pct);
    var presets = UI_SCALE_PRESETS || [75, 90, 100, 110, 125];
    if (presets.indexOf(pct) >= 0) return pct;
    var best = presets[0];
    presets.forEach(function (v) {
      if (Math.abs(v - pct) < Math.abs(best - pct)) best = v;
    });
    return best;
  }

  function migrateUiScaleFromLegacyTextSize() {
    if (typeof S.uiScale === "number" && isFinite(S.uiScale) && S.uiScale >= 70) return;
    var map = { small: 90, default: 100, large: 110 };
    var leg = S.uiTextSize || "default";
    S.uiScale = map[leg] || UI_SCALE_PCT_DEFAULT;
  }

  function uiScaleFactor() {
    migrateUiScaleFromLegacyTextSize();
    return normalizeUiScalePct(S.uiScale) / 100;
  }

  function unwrapPanelScaleInner(panel) {
    panel = panel || $("bs-panel");
    if (!panel) return;
    var inners = panel.querySelectorAll(".bs-panel-scale-inner");
    Array.prototype.forEach.call(inners, function (inner) {
      var parent = inner.parentNode;
      if (!parent) return;
      while (inner.firstChild) {
        parent.insertBefore(inner.firstChild, inner);
      }
      parent.removeChild(inner);
    });
    var head = panel.querySelector(":scope > .bs-head, :scope > #bs-drag");
    if (!head) return;
    ["bs-ux-tasks", "bs-toolbar", "bs-body"].forEach(function (id) {
      var el = head.querySelector("#" + id);
      if (el && el.parentNode === head) {
        panel.insertBefore(el, head.nextSibling);
      }
    });
  }

  function panelDomStructureOk(panel) {
    if (!panel) return false;
    var head = panel.querySelector(":scope > .bs-head, :scope > #bs-drag");
    var body = panel.querySelector(":scope > .bs-body");
    var tabs = panel.querySelector("#bs-tabs");
    if (!head || !body || !tabs) return false;
    if (head.contains(body) || head.querySelector(".bs-toolbar, #bs-toolbar")) return false;
    if (panel.querySelector(":scope > .bs-panel-scale-inner")) return false;
    return true;
  }

  function toolboxPopupScaleNodes(doc) {
    if (!doc) doc = document;
    var out = [];
    try {
      doc.querySelectorAll(
        "#bs-find-prompt, #bs-find-results, #bs-box-help-pop, #bs-fallback, #bs-fallback-chip, .bs-bm-edit-pop"
      ).forEach(function (el) {
        out.push(el);
      });
    } catch (eQ) {}
    return out;
  }

  function applyUiScale() {
    migrateUiScaleFromLegacyTextSize();
    var pct = normalizeUiScalePct(S.uiScale);
    S.uiScale = pct;
    var factor = pct / 100;
    function applyDoc(doc) {
      if (!doc) return;
      var p = doc.getElementById("bs-panel");
      if (p) {
        try { unwrapPanelScaleInner(p); } catch (eUn) {}
        p.classList.remove("bs-text-sm", "bs-text-lg");
        p.style.removeProperty("zoom");
        p.classList.toggle("bs-ui-scaled", factor !== 1);
        if (factor === 1) {
          p.style.setProperty("--bs-ui-scale", "1");
          p.removeAttribute("data-bs-ui-scale");
        } else {
          p.style.setProperty("--bs-ui-scale", String(factor));
          p.setAttribute("data-bs-ui-scale", String(pct));
        }
        function clearBodyZoom(el) {
          if (!el) return;
          try {
            el.style.removeProperty("font-size");
            el.style.removeProperty("zoom");
          } catch (eZ0) {}
        }
        clearBodyZoom(p.querySelector(".bs-toolbar"));
        clearBodyZoom(p.querySelector(".bs-body"));
        Array.prototype.forEach.call(p.querySelectorAll(".bs-ux-strip"), clearBodyZoom);
        try { applyMainTabScaleToPanel(p); } catch (eTabSc) {}
        scheduleHeadTabStripFit();
      }
      toolboxPopupScaleNodes(doc).forEach(function (el) {
        try {
          el.style.removeProperty("zoom");
          el.style.removeProperty("transform");
          if (factor === 1) {
            el.style.removeProperty("font-size");
          } else {
            el.style.fontSize = Math.round(13 * factor * 10) / 10 + "px";
          }
        } catch (eZ) {}
      });
    }
    applyDoc(document);
    try {
      if (detachWin && !detachWin.closed && detachWin.document) applyDoc(detachWin.document);
    } catch (eDet) {}
    try { scheduleExploreMasonryRepack(); } catch (eM) {}
    var sel = $("bs-ui-scale-preset");
    if (sel) {
      var presetVal = String(snapUiScaleToPreset(pct));
      if (sel.value !== presetVal) sel.value = presetVal;
    }
    try { syncUiScaleCycleBtn(); } catch (eCyc) {}
  }

  function syncUiScaleCycleBtn() {
    var btn = $("bs-ui-scale-cycle");
    if (!btn) return;
    var p = snapUiScaleToPreset(S.uiScale);
    btn.textContent = String(p);
    btn.title =
      "Panel scale " + p + "% — click for next size (Explore, Bands, Settings, …; tab bar stays full size).";
    btn.classList.toggle("bs-on", p !== 100);
    try { btn.setAttribute("aria-label", "Panel scale " + p + " percent"); } catch (eA) {}
  }

  function cycleUiScaleStep() {
    var cur = snapUiScaleToPreset(S.uiScale);
    var idx = UI_SCALE_PRESETS.indexOf(cur);
    if (idx < 0) idx = UI_SCALE_PRESETS.indexOf(100);
    var next = UI_SCALE_PRESETS[(idx + 1) % UI_SCALE_PRESETS.length];
    S.uiScale = next;
    applyUiScale();
    try { saveSettings(); } catch (eSv) {}
    try {
      setStatus("Panel scale " + next + "% — all tab content (header tabs unchanged).");
    } catch (eSt) {}
  }

  function syncUiScaleCycleChrome() {
    var anchor = $("bs-side-pct-reset");
    if (!anchor || $("bs-ui-scale-cycle")) return;
    var btn = document.createElement("button");
    btn.type = "button";
    btn.className = "bs-x bs-ui-scale-cycle";
    btn.id = "bs-ui-scale-cycle";
    btn.textContent = "100";
    anchor.parentNode.insertBefore(btn, anchor);
    try { wireUiScaleCycleBtn(); } catch (eW) {}
    try { syncUiScaleCycleBtn(); } catch (eS) {}
  }

  function wireUiScaleCycleBtn() {
    var btn = $("bs-ui-scale-cycle");
    if (!btn) return;
    btn.onclick = function (ev) {
      ev.stopPropagation();
      cycleUiScaleStep();
    };
  }

  function applyUiTextSize() {
    applyUiScale();
  }

  function wireUiScaleControls() {
    var preset = $("bs-ui-scale-preset");
    if (!preset) return;
    preset.onchange = function () {
      S.uiScale = snapUiScaleToPreset(preset.value);
      applyUiScale();
      try { saveSettings(); } catch (eSv) {}
      try {
        setStatus("Panel scale " + S.uiScale + "% (tab bar stays full size).");
      } catch (eSt) {}
    };
  }

  function applyMainTabScaleToPanel(panel) {
    if (!panel) return;
    var pct = snapMainTabScalePct(S.mainTabScale);
    S.mainTabScale = pct;
    var factor = pct / 100;
    panel.style.setProperty("--bs-main-tab-scale", String(factor));
    panel.setAttribute("data-bs-main-tab-scale", String(pct));
  }

  function applyMainTabScale() {
    var pct = snapMainTabScalePct(S.mainTabScale);
    S.mainTabScale = pct;
    function applyDoc(doc) {
      if (!doc) return;
      var p = doc.getElementById("bs-panel");
      if (p) applyMainTabScaleToPanel(p);
    }
    applyDoc(document);
    try {
      if (detachWin && !detachWin.closed && detachWin.document) applyDoc(detachWin.document);
    } catch (eDet) {}
    var sel = $("bs-main-tab-scale");
    if (sel && sel.value !== String(pct)) sel.value = String(pct);
    scheduleHeadTabStripFit();
  }

  function wireMainTabScaleControls() {
    var sel = $("bs-main-tab-scale");
    if (!sel || sel._bsMainTabBound) return;
    sel._bsMainTabBound = true;
    sel.onchange = function () {
      S.mainTabScale = snapMainTabScalePct(sel.value);
      applyMainTabScale();
      try { saveSettings(); } catch (eSv) {}
      try {
        setStatus("Main tab size " + S.mainTabScale + "%.");
      } catch (eSt) {}
    };
  }

  /** Toolbox panel opacity only — stock OpenWebRX has its own receiver opacity slider. */
  var panelOpacityBump = false;
  var panelOpacityBeforeBump = null;
  var PANEL_OPACITY_TIP =
    "Opacity of the Toolbox panel only. The stock OpenWebRX receiver has its own opacity slider on .openwebrx-panel.";
  var PANEL_OPACITY_BUMP_TIP =
    "Temporary 100% Toolbox panel opacity (does not change the stock receiver).";

  function panelOpacitySideDocked() {
    var p = $("bs-panel");
    return !!(p && p.classList.contains("bs-side-docked"));
  }

  /** Opacity only applies when floating — hide controls while side-docked and force solid. */
  function syncPanelOpacityUi() {
    var side = panelOpacitySideDocked();
    var row = $("bs-ex-opacity-row");
    if (row) row.hidden = !!side;
    var op = $("bs-ex-opacity");
    var lab = op && op.closest ? op.closest("label") : null;
    if (lab) {
      lab.title = PANEL_OPACITY_TIP;
      lab.setAttribute("data-tip", PANEL_OPACITY_TIP);
    }
    var bump = $("bs-ex-opacity-bump");
    if (bump) {
      bump.title = PANEL_OPACITY_BUMP_TIP;
      bump.setAttribute("data-tip", PANEL_OPACITY_BUMP_TIP);
    }
    try { applyPanelOpacity(); } catch (eOp) {}
  }

  function syncPanelOpacityTip() {
    syncPanelOpacityUi();
  }

  function applyPanelOpacity() {
    var p = $("bs-panel");
    if (!p) return;
    S.panelOpacity = sanitizePanelOpacity(S.panelOpacity);
    /* Side dock is an opaque column — lower opacity just washes out; keep solid. */
    var pct = 100;
    if (!panelOpacitySideDocked()) {
      pct = panelOpacityBump ? 100 : S.panelOpacity;
    }
    p.style.opacity = String(pct / 100);
  }

  function setPanelOpacity(pct) {
    S.panelOpacity = sanitizePanelOpacity(pct);
    if (panelOpacityBump) {
      panelOpacityBump = false;
      panelOpacityBeforeBump = null;
    }
    applyPanelOpacity();
    saveSettings();
  }

  function togglePanelOpacityBump() {
    if (panelOpacityBump) {
      panelOpacityBump = false;
      if (panelOpacityBeforeBump != null) {
        S.panelOpacity = sanitizePanelOpacity(panelOpacityBeforeBump);
      }
      panelOpacityBeforeBump = null;
    } else {
      panelOpacityBeforeBump = sanitizePanelOpacity(S.panelOpacity);
      panelOpacityBump = true;
    }
    applyPanelOpacity();
  }

  /**
   * Stock UI.setOpacity only targets .openwebrx-panel (receiver chrome), not #bs-panel.
   * Re-apply Toolbox opacity after stock opacity changes so the two never fight.
   */
  function hookStockOpacityGuard() {
    if (!window.UI || UI._bs_opacity_guard) return;
    UI._bs_opacity_guard = true;
    function reapply() {
      try { applyPanelOpacity(); } catch (e) {}
    }
    if (typeof UI.setOpacity === "function") {
      var setOp = UI.setOpacity.bind(UI);
      UI.setOpacity = function (x) {
        var out = setOp(x);
        reapply();
        return out;
      };
    }
    if (typeof UI.toggleOpacity === "function") {
      var togOp = UI.toggleOpacity.bind(UI);
      UI.toggleOpacity = function (on) {
        var out = togOp(on);
        reapply();
        return out;
      };
    }
    if (typeof UI.bumpOpacity === "function") {
      var bumpOp = UI.bumpOpacity.bind(UI);
      UI.bumpOpacity = function () {
        var out = bumpOp();
        reapply();
        return out;
      };
    }
  }

  function parseHexColor(hex) {
    var h = String(hex || "").replace("#", "").trim();
    if (h.length === 3) h = h.charAt(0) + h.charAt(0) + h.charAt(1) + h.charAt(1) + h.charAt(2) + h.charAt(2);
    if (!/^[0-9a-fA-F]{6}$/.test(h)) return null;
    return {
      r: parseInt(h.slice(0, 2), 16),
      g: parseInt(h.slice(2, 4), 16),
      b: parseInt(h.slice(4, 6), 16)
    };
  }

  function toHexColor(r, g, b) {
    function byte(n) {
      n = Math.max(0, Math.min(255, Math.round(n)));
      return (n < 16 ? "0" : "") + n.toString(16);
    }
    return "#" + byte(r) + byte(g) + byte(b);
  }

  function mixHexColor(a, b, t) {
    var A = parseHexColor(a);
    var B = parseHexColor(b);
    if (!A || !B) return a || b || "#111111";
    t = Math.max(0, Math.min(1, Number(t) || 0));
    return toHexColor(A.r + (B.r - A.r) * t, A.g + (B.g - A.g) * t, A.b + (B.b - A.b) * t);
  }

  /** Dark / muted panel surfaces derived from a button shade (same family, quieter). */
  function panelSkinFromBtnShade(key) {
    var sh = BTN_SHADES[key];
    if (!sh) return null;
    var deep = "#05070c";
    var mid = "#0f172a";
    var accent = sh.border || sh.hover || sh.bg;
    return {
      bg: mixHexColor(sh.bg, deep, 0.82),
      head: mixHexColor(sh.bg, deep, 0.74),
      body: mixHexColor(sh.bg, deep, 0.86),
      boxTop: mixHexColor(sh.bg, mid, 0.58),
      boxBot: mixHexColor(sh.bg, deep, 0.76),
      boxHead: mixHexColor(sh.bg, deep, 0.68),
      border: mixHexColor(accent, mid, 0.42),
      borderSoft: mixHexColor(accent, mid, 0.62),
      accent: accent,
      fg: "#f1f5f9",
      muted: mixHexColor(accent, "#94a3b8", 0.4)
    };
  }

  function applyPanelShade() {
    var key = sanitizePanelShade(S.panelShade);
    S.panelShade = key;
    var panel = $("bs-panel");
    if (panel) {
      if (key === "classic") panel.removeAttribute("data-bs-shade");
      else panel.setAttribute("data-bs-shade", key);
    }
    var style = $("bs-panel-shade-style");
    if (!style) {
      style = document.createElement("style");
      style.id = "bs-panel-shade-style";
      document.head.appendChild(style);
    }
    if (key === "classic") {
      if (style.textContent) style.textContent = "";
      return;
    }
    var skin = panelSkinFromBtnShade(key);
    if (!skin) {
      style.textContent = "";
      return;
    }
    var css =
      "#bs-panel{" +
      "background:" + skin.bg + " !important;" +
      "color:" + skin.fg + " !important;" +
      "border-color:" + skin.border + " !important;" +
      "}" +
      "#bs-panel .bs-head{" +
      "background:" + skin.head + " !important;" +
      "border-bottom-color:" + skin.borderSoft + " !important;" +
      "}" +
      "#bs-panel .bs-body," +
      "#bs-panel .bs-tab-pane," +
      "#bs-panel .bs-help-pane{" +
      "background:" + skin.body + " !important;" +
      "}" +
      "#bs-panel .bs-ex-box," +
      "#bs-panel .bs-set-box," +
      "#bs-panel .bs-box{" +
      "background:linear-gradient(180deg," + skin.boxTop + "," + skin.boxBot + ") !important;" +
      "border-color:" + skin.borderSoft + " !important;" +
      "}" +
      "#bs-panel .bs-ex-box-h," +
      "#bs-panel .bs-set-box-h{" +
      "background:" + skin.boxHead + " !important;" +
      "border-bottom-color:" + skin.borderSoft + " !important;" +
      "color:" + skin.accent + " !important;" +
      "}" +
      "#bs-panel .bs-opt-group{" +
      "background:rgba(0,0,0,0.18) !important;" +
      "border-color:" + skin.borderSoft + " !important;" +
      "}" +
      "#bs-panel .bs-status," +
      "#bs-panel .bs-note," +
      "#bs-panel .bs-hint," +
      "#bs-panel .bs-ex-tip{" +
      "color:" + skin.muted + " !important;" +
      "}";
    if (applyPanelShade._css === css && style.textContent === css) return;
    applyPanelShade._css = css;
    style.textContent = css;
  }

  function setPanelShade(key) {
    S.panelShade = sanitizePanelShade(key);
    applyPanelShade();
    saveSettings();
    fillPanelShadeSelect();
  }

  function panelShadeLabel(key) {
    if (key === "classic") return "Classic (default)";
    if (!key) return "Classic (default)";
    return key.charAt(0).toUpperCase() + key.slice(1);
  }

  function fillPanelShadeSelect() {
    var sel = $("bs-ex-panel-shade");
    if (!sel) return;
    var cur = sanitizePanelShade(S.panelShade);
    var keys = ["classic"].concat(Object.keys(BTN_SHADES));
    var sig = keys.join(",");
    if (sel.getAttribute("data-sig") !== sig) {
      sel.setAttribute("data-sig", sig);
      sel.innerHTML = keys.map(function (k) {
        return '<option value="' + escapeHtml(k) + '">' + escapeHtml(panelShadeLabel(k)) + "</option>";
      }).join("");
    }
    if (document.activeElement !== sel) sel.value = cur;
  }

  function bindPanelShadeSelect() {
    var sel = $("bs-ex-panel-shade");
    if (!sel || sel._bs_bound) return;
    sel._bs_bound = true;
    sel.onchange = function () {
      setPanelShade(this.value);
    };
  }

  function normalizeChkStyle(v) {
    if (v === "switch") return v;
    return "tick";
  }

  function applyChkStyle() {
    var style = normalizeChkStyle(S.chkStyle);
    S.chkStyle = style;
    try {
      document.documentElement.setAttribute("data-bs-chk-style", style);
    } catch (eHtml) {}
    try {
      if (document.body) document.body.setAttribute("data-bs-chk-style", style);
    } catch (eBody) {}
    var p = $("bs-panel");
    if (p) p.setAttribute("data-bs-chk-style", style);
    if ($("bs-chk-style")) $("bs-chk-style").value = style;
  }

  function resetPanelLayoutDefaults() {
    if (restorePanelLayoutSnapshot()) {
      saveSettings();
      setStatus("Panel layout restored from last save.");
      return;
    }
    S.panelW = 0;
    S.panelH = 0;
    S.panelLeft = null;
    S.panelTop = null;
    panelLayoutUserSet = false;
    saveSettings();
    applyPanelLayout();
    setStatus("No saved layout — using waterfall default.");
  }

  function writePanelLayoutSnapshot() {
    try {
      var payload = {
        panelW: Math.round(Number(S.panelW) || 0),
        panelH: Math.round(Number(S.panelH) || 0),
        panelLeft: typeof S.panelLeft === "number" ? Math.round(S.panelLeft) : null,
        panelTop: typeof S.panelTop === "number" ? Math.round(S.panelTop) : null,
        panelSideDock: !!S.panelSideDock,
        panelSideDockSide: sideDockSide(),
        panelSidePct: sideDockPct()
      };
      window.localStorage.setItem(LS_PANEL_LAYOUT, JSON.stringify(payload));
    } catch (e) {}
  }

  function readPanelLayoutSnapshot() {
    try {
      var raw = window.localStorage.getItem(LS_PANEL_LAYOUT);
      if (!raw) return null;
      var o = JSON.parse(raw);
      if (!o) return null;
      if (typeof o.panelSideDock === "boolean") return o;
      if (!(Number(o.panelW) > 40) || !(Number(o.panelH) > 40)) return null;
      return o;
    } catch (e) {
      return null;
    }
  }

  function restorePanelLayoutSnapshot() {
    var o = readPanelLayoutSnapshot();
    if (!o) return false;
    if (typeof o.panelSideDock === "boolean") S.panelSideDock = !!o.panelSideDock;
    if (o.panelSideDockSide === "right" || o.panelSideDockSide === "left") {
      S.panelSideDockSide = o.panelSideDockSide;
    }
    /* Do not clobber a newer in-memory side % from the live slider. */
    if (isFinite(Number(o.panelSidePct)) && !window._bs_side_pct_live) {
      S.panelSidePct = normalizePreferredSidePct(o.panelSidePct);
    }
    if (Number(o.panelW) > 40 && Number(o.panelH) > 40) {
      var vwSnap = viewportWidth();
      var vhSnap = window.innerHeight || 768;
      var crushedFloat = !o.panelSideDock &&
        floatPanelSizeLooksDockCrushed(o.panelW, vwSnap, o.panelH, vhSnap);
      if (!crushedFloat) {
        S.panelW = Number(o.panelW);
        S.panelH = Number(o.panelH);
        S.panelLeft = typeof o.panelLeft === "number" && isFinite(o.panelLeft) ? o.panelLeft : null;
        S.panelTop = typeof o.panelTop === "number" && isFinite(o.panelTop) ? o.panelTop : null;
        panelLayoutUserSet = true;
      }
    }
    applyPanelLayout();
    return true;
  }

  /** Re-apply last placement (side dock or float) after load / OWRX redraw. */
  function restoreSavedPanelPlacement(opts) {
    opts = opts || {};
    try { restorePanelLayoutSnapshot(); } catch (e0) {}
    if (!S.panelSideDock) {
      applySideDockChrome(false);
      if (!isPanelDetached()) restoreFloatPanelSizeForSession();
      applyPanelLayout();
      scheduleExploreFreeReflowAfterPanelLayout();
      return;
    }
    makePanel();
    var p = $("bs-panel");
    if (!p) return;
    if (window._bs_user_closed_panel) {
      applySideDockChrome(false);
      syncSideDockLayout();
      applyPanelLayout();
      return;
    }
    /* Do not force-open just because side dock is on — honor "Open panel on startup". */
    var wantVisible = !!opts.forceOpen || !p.hidden || !!window._bs_startup_open_done;
    if (!wantVisible) {
      applySideDockChrome(false);
      syncSideDockLayout();
      applyPanelLayout();
      return;
    }
    if (isPanelDetached()) dockPanel({ keepHidden: false });
    p.hidden = false;
    setPanelMinimized(false);
    syncSideDockLayout();
    applyPanelLayout();
    if (!opts.noRetry) {
      setTimeout(function () { restoreSavedPanelPlacement({ noRetry: true, forceOpen: true }); }, 200);
      setTimeout(function () { restoreSavedPanelPlacement({ noRetry: true, forceOpen: true }); }, 800);
    }
  }

  function savePanelLayoutManual() {
    if (!requirePublicFeature("changeLayout", "Save panel layout")) return;
    savePanelLayout();
    writePanelLayoutSnapshot();
    setStatus("Panel layout saved — factory reset will restore this size and position.");
  }

  function applyWaterfallPanelDefault() {
    if (!requirePublicFeature("changeLayout", "Reset panel layout")) return;
    S.panelW = 0;
    S.panelH = 0;
    S.panelLeft = null;
    S.panelTop = null;
    panelLayoutUserSet = false;
    saveSettings();
    applyPanelLayout();
    setStatus("Panel layout set to waterfall default.");
  }

