  function importSettingsMerge(obj) {
    if (!requirePublicFeature("importExport", "Import settings")) return;
    if (!obj || typeof obj !== "object") return false;
    var d = settingsDefaults();
    Object.keys(d).forEach(function (k) {
      if (typeof obj[k] === "undefined") return;
      if (k === "ignoredFreqs") {
        S.ignoredFreqs = Array.isArray(obj[k]) ? obj[k].slice() : S.ignoredFreqs;
      } else if (k === "hiddenTabs") {
        S.hiddenTabs = Array.isArray(obj[k]) ? obj[k].slice() : S.hiddenTabs;
      } else if (k === "hiddenMoreSubs") {
        S.hiddenMoreSubs = Array.isArray(obj[k]) ? obj[k].slice() : S.hiddenMoreSubs;
      } else if (k === "hiddenExtraSubs") {
        S.hiddenExtraSubs = Array.isArray(obj[k]) ? obj[k].slice() : S.hiddenExtraSubs;
      } else if (k === "hiddenExploreBoxes") {
        S.hiddenExploreBoxes = Array.isArray(obj[k]) ? obj[k].slice() : S.hiddenExploreBoxes;
      } else if (k === "hiddenLightFeats") {
        S.hiddenLightFeats = Array.isArray(obj[k]) ? obj[k].slice() : S.hiddenLightFeats;
      } else if (k === "logPins") {
        S.logPins = Array.isArray(obj[k]) ? obj[k].slice() : S.logPins;
      } else if (k === "recentProfiles") {
        S.recentProfiles = Array.isArray(obj[k]) ? obj[k].slice() : S.recentProfiles;
      } else if (k === "extras") {
        S.extras = sanitizeExtras(obj[k]);
      } else {
        S[k] = obj[k];
      }
    });
    S = sanitizeLayoutSettings(S);
    try { applyPublicLocksLive(); } catch (eImpLock) {}
    saveSettings();
    fillSettingsForm();
    applyHiddenTabs();
    try { applyHiddenExploreBoxes(); } catch (eExVis) {}
    applyToolbarVisibility();
    applyStockReceiverVisibility();
    applySchedule();
    renderBookmarkPane();
    updateTabLabels();
    return true;
  }

  function resetSettingsToDefaults() {
    if (!window.confirm(
      loadUserDefaultsOverlay()
        ? "Reset all Toolbox settings to your personal defaults? Peak list and bookmarks are kept."
        : "Reset all Toolbox settings to defaults? Peak list and bookmarks are kept."
    )) return;
    withSettingsScrollPreserved(function () {
      var keepSelected = S.selected;
      applyEffectiveDefaultsToS({ keepIgnored: true });
      if (keepSelected) S.selected = keepSelected;
      saveSettings();
      fillSettingsForm();
      if ($("bs-passes")) $("bs-passes").value = S.passes;
      if ($("bs-range-passes")) $("bs-range-passes").value = S.passes;
      if ($("bs-dwell")) $("bs-dwell").value = S.dwell;
      if ($("bs-minhits")) $("bs-minhits").value = S.minHits;
      if ($("bs-thresh")) $("bs-thresh").value = S.threshDb;
      syncRangeScanOptsUi();
      applySchedule();
      applyPanelLayout();
      applyHiddenTabs();
      try { applyHiddenExploreBoxes(); } catch (eExRsVis) {}
      try { applyHiddenMoreSubs(); } catch (eMoreRs) {}
      try { applyExtraSubsVisibility(); } catch (eExSubRs) {}
      try { applyLightFeatsVisibility(); } catch (eLfRs) {}
      applyToolbarVisibility();
      applyStockReceiverVisibility();
      applyBtnShades();
      try { applyBuiltinExploreLayout(true); } catch (eExRs) {}
      try { applyHiddenExploreBoxes(); } catch (eExRsVis2) {}
      setStatus(loadUserDefaultsOverlay()
        ? "Settings reset to your personal defaults (including Explore layout if saved)."
        : "Settings reset to defaults (including Explore box layout).");
    });
  }

