  function placeAudioSttBox() {
    var box = $("bs-audio-stt-box");
    var tab = $("bs-tab-audio");
    if (!box || !tab || !tab.contains(box)) return;
    var stack = tab.querySelector(".bs-tab-stack");
    if (!stack) return;
    if (box.parentNode !== stack) stack.appendChild(box);
  }

  function setAudioSubTab(name, opts) {
    opts = opts || {};
    /* v321: Recording options folded into Record — only list | record. */
    if (name === "decode" || name === "options") name = "record";
    var allowed = { list: 1, record: 1, filters: 1, meter: 1, tags: 1 };
    if (!allowed[name] || isExtraSubHidden("audio", name)) name = firstVisibleExtraSub("audio", "list");
    var root = $("bs-tab-audio");
    if (!root) return;
    try { audioMeterStop(); } catch (eM0) {}
    Array.prototype.forEach.call(root.querySelectorAll(".bs-au-sub"), function (btn) {
      var id = btn.getAttribute("data-au-sub");
      var hide = isExtraSubHidden("audio", id);
      btn.hidden = hide;
      if (hide) btn.setAttribute("hidden", ""); else btn.removeAttribute("hidden");
      var on = !hide && id === name;
      btn.classList.toggle("bs-au-sub-on", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    Array.prototype.forEach.call(root.querySelectorAll(".bs-au-subpane"), function (pane) {
      var id = pane.getAttribute("data-au-sub");
      var on = !isExtraSubHidden("audio", id) && id === name;
      pane.classList.toggle("bs-au-sub-on", on);
      if (on) pane.removeAttribute("hidden");
      else pane.setAttribute("hidden", "");
    });
    try { placeAudioSttBox(); } catch (eStt) {}
    if (name === "filters") {
      try { audioFiltSyncUi(); } catch (eAf) {}
      try { audioFiltApply(); } catch (eAp) {}
    }
    if (name === "meter") { try { audioMeterOnTab(); } catch (eM) {} }
    if (name === "tags") { try { audioTagsOnTab(); } catch (eT) {} }
    if (!opts.skipSave) {
      try { if (extraOn("rememberSubs")) window.localStorage.setItem("owrx_toolbox_au_sub_v1", name); } catch (e) {}
    }
    try { injectBoxHelpButtons(root); } catch (eH) {}
  }

  function restoreAudioSubTab() {
    var name = firstVisibleExtraSub("audio", "list");
    try {
      var raw = extraOn("rememberSubs") ? window.localStorage.getItem("owrx_toolbox_au_sub_v1") : null;
      if (raw === "decode" || raw === "options") raw = "record";
      if (raw && { list: 1, record: 1, filters: 1, meter: 1, tags: 1 }[raw] && !isExtraSubHidden("audio", raw)) name = raw;
    } catch (e) {}
    setAudioSubTab(name, { skipSave: true });
  }

  var audioMeterTimer = 0;
  function audioMeterStop() {
    if (audioMeterTimer) { clearInterval(audioMeterTimer); audioMeterTimer = 0; }
  }
  function audioMeterOnTab() {
    var canvas = $("bs-aud-meter");
    var meta = $("bs-aud-meter-meta");
    if (!canvas || !canvas.getContext) return;
    var ctx = canvas.getContext("2d");
    var analyser = null;
    try {
      var ac = window.audioContext || window.audio_context || (window.AudioEngine && AudioEngine.audioContext);
      if (ac && typeof ac.createAnalyser === "function") {
        analyser = ac.createAnalyser();
        analyser.fftSize = 256;
        /* Best-effort: may not connect without a known source — paint idle bar. */
      }
    } catch (e) {}
    function paint(level) {
      var w = canvas.width, h = canvas.height;
      ctx.fillStyle = "#0b1220";
      ctx.fillRect(0, 0, w, h);
      ctx.fillStyle = level > 0.7 ? "#f87171" : "#86efac";
      ctx.fillRect(4, 8, Math.max(2, (w - 8) * Math.max(0, Math.min(1, level))), h - 16);
    }
    paint(0.05);
    if (meta) meta.textContent = analyser ? "Sampling…" : "No analyser hook — bar shows activity proxy when open.";
    audioMeterStop();
    audioMeterTimer = setInterval(function () {
      var pane = $("bs-tab-audio");
      var sub = document.querySelector('#bs-tab-audio .bs-au-subpane[data-au-sub="meter"]');
      if (!pane || !pane.classList.contains("bs-tab-on") || !sub || !sub.classList.contains("bs-au-sub-on")) return;
      var lvl = 0.08;
      try {
        /* Proxy: use last waterfall max if present */
        var data = typeof wf === "function" ? wf() : null;
        if (data && data.length) {
          var m = -120;
          for (var i = 0; i < data.length; i++) if (data[i] > m) m = data[i];
          lvl = Math.max(0, Math.min(1, (m + 100) / 60));
        }
      } catch (e2) {}
      paint(lvl);
    }, 200);
  }

  var audioTagFilter = "all";
  function audioTagsMap() {
    try {
      return JSON.parse(window.localStorage.getItem("owrx_toolbox_aud_tags_v1") || "{}") || {};
    } catch (e) { return {}; }
  }
  function audioTagsSave(map) {
    try { window.localStorage.setItem("owrx_toolbox_aud_tags_v1", JSON.stringify(map)); } catch (e) {}
  }
  function audioTagsOnTab() {
    var host = $("bs-aud-tag-list");
    if (!host) return;
    bindLightIoPair("bs-aud-tags-export", "bs-aud-tags-import", "bs-aud-tags-file",
      function () { return { kind: "owrx_toolbox_aud_tags", when: Date.now(), tags: audioTagsMap() }; },
      function (text) {
        var o = JSON.parse(String(text || "").trim());
        var incoming = (o && o.tags && typeof o.tags === "object") ? o.tags : (o && typeof o === "object" && !Array.isArray(o) ? o : null);
        if (!incoming) throw new Error("No tags map in that file");
        var map = audioTagsMap();
        Object.keys(incoming).forEach(function (k) {
          if (incoming[k]) map[k] = String(incoming[k]).slice(0, 16);
        });
        audioTagsSave(map);
        audioTagsOnTab();
        setStatus("Imported clip tags.");
      },
      "toolbox-aud-tags.json", "application/json", "Import tags");
    Array.prototype.forEach.call(document.querySelectorAll("#bs-aud-tag-chips [data-aud-tag]"), function (btn) {
      btn.classList.toggle("bs-on", btn.getAttribute("data-aud-tag") === audioTagFilter);
    });
    var map = audioTagsMap();
    var clips = (audioClips || []).slice().reverse();
    var rows = clips.filter(function (c) {
      if (audioTagFilter === "all") return true;
      return (map[c.id] || "") === audioTagFilter;
    }).slice(0, 60);
    if (!rows.length) {
      host.innerHTML = '<p class="bs-empty">No clips for this filter.</p>';
    } else {
      host.innerHTML = rows.map(function (c) {
        var tag = map[c.id] || "";
        return '<article class="bs-more-row" data-aud-id="' + escapeHtml(c.id) + '">' +
          '<span class="bs-more-name">' + escapeHtml(c.name || c.file || c.id) + "</span>" +
          '<span class="bs-more-status">' + escapeHtml(tag || "—") + "</span>" +
          '<button type="button" class="bs-tiny" data-tag-set="qso">QSO</button>' +
          '<button type="button" class="bs-tiny" data-tag-set="noise">Noise</button>' +
          '<button type="button" class="bs-tiny" data-tag-set="id">ID</button>' +
          "</article>";
      }).join("");
    }
    if (!host._bsTagWired) {
      host._bsTagWired = true;
      var chips = $("bs-aud-tag-chips");
      if (chips) chips.addEventListener("click", function (ev) {
        var b = ev.target && ev.target.closest && ev.target.closest("[data-aud-tag]");
        if (!b) return;
        audioTagFilter = b.getAttribute("data-aud-tag") || "all";
        audioTagsOnTab();
      });
      host.addEventListener("click", function (ev) {
        var b = ev.target && ev.target.closest && ev.target.closest("[data-tag-set]");
        if (!b) return;
        var row = b.closest("[data-aud-id]");
        if (!row) return;
        var id = row.getAttribute("data-aud-id");
        var map2 = audioTagsMap();
        map2[id] = b.getAttribute("data-tag-set");
        audioTagsSave(map2);
        audioTagsOnTab();
      });
    }
  }

  function scanTricksBoxHtml(id) {
    return tabBoxHtml("Scan skips",
      '<div class="bs-scan-tricks">' +
      '<label class="bs-chk" title="Scan bookmarks skips FT8, WSPR, RTTY, DMR and other digital entries."><input type="checkbox" class="bs-skip-digi"> Skip digital bookmarks</label>' +
      '<label title="Edges in MHz. The stretch is skipped by Range scans and bookmark scans, and shaded on the waterfall.">Block <input type="number" class="bs-block-lo" step="0.001" min="0" style="width:5.5em"> – <input type="number" class="bs-block-hi" step="0.001" min="0" style="width:5.5em"> MHz</label>' +
      '<button type="button" class="bs-tiny bs-btn-util bs-block-add">Add</button>' +
      '<div class="bs-block-list"></div>' +
      "</div>",
      { wide: true, id: id, cls: "bs-scan-tricks-box bs-tab-box-full",
        help: "Skip digital bookmarks during Scan bookmarks. Blocked MHz stretches are skipped by Range scans and bookmark scans, and shaded on the waterfall. Same controls on Skip and Range (not on Bands list)." });
  }

  function syncScanTricksUi() {
    Array.prototype.forEach.call(document.querySelectorAll(".bs-skip-digi"), function (inp) {
      inp.checked = !!S.skipDigitalBm;
    });
    var html = (S.blockedRanges || []).map(function (r, i) {
      return '<span class="bs-block-chip"><span>' + escapeHtml(fmtMhz(r.lo)) + " – " + escapeHtml(fmtMhz(r.hi)) +
        '</span> <button type="button" class="bs-tiny bs-btn-clear" data-block-i="' + i + '">×</button></span>';
    }).join("") || '<span class="bs-empty">No blocked stretches.</span>';
    Array.prototype.forEach.call(document.querySelectorAll(".bs-block-list"), function (host) {
      host.innerHTML = html;
    });
    try { paintBlockOverlay(true); } catch (eOv) {}
  }

  function scanBlockAdd(btn) {
    var box = btn.closest && btn.closest(".bs-scan-tricks");
    if (!box) return;
    var loEl = box.querySelector(".bs-block-lo");
    var hiEl = box.querySelector(".bs-block-hi");
    var lo = Number(loEl && loEl.value) * 1e6;
    var hi = Number(hiEl && hiEl.value) * 1e6;
    if (!(lo > 0 && hi > lo)) {
      setStatus("Block needs a low MHz and a higher MHz.");
      return;
    }
    S.blockedRanges = sanitizeBlockedRanges((S.blockedRanges || []).concat([{ lo: lo, hi: hi }]));
    saveSettings();
    if (loEl) loEl.value = "";
    if (hiEl) hiEl.value = "";
    syncScanTricksUi();
    setStatus("Blocked " + fmtMhz(lo) + " – " + fmtMhz(hi) + ".");
  }

  function bindScanTricks(root) {
    if (!root || root._bsScanTricks) return;
    root._bsScanTricks = true;
    root.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      var add = t.closest(".bs-block-add");
      if (add && root.contains(add)) {
        scanBlockAdd(add);
        return;
      }
      var del = t.closest("[data-block-i]");
      if (!del || !root.contains(del)) return;
      var i = Number(del.getAttribute("data-block-i"));
      if (!isFinite(i)) return;
      S.blockedRanges = (S.blockedRanges || []).filter(function (_r, n) { return n !== i; });
      saveSettings();
      syncScanTricksUi();
    });
    root.addEventListener("change", function (ev) {
      var t = ev.target;
      if (!t || !t.classList || !t.classList.contains("bs-skip-digi")) return;
      S.skipDigitalBm = !!t.checked;
      saveSettings();
      syncScanTricksUi();
    });
  }

  var _blockOverlayKey = "";

  function ensureBlockOverlayTimer() {
    if (window._bs_block_overlay_timer) return;
    window._bs_block_overlay_timer = setInterval(function () {
      if (!(S.blockedRanges || []).length) return;
      try { paintBlockOverlay(false); } catch (eOv) {}
    }, 1500);
  }

  function paintBlockOverlay(force) {
    var box = document.getElementById("webrx-canvas-container") || window.canvas_container;
    if (!box) return;
    var ranges = S.blockedRanges || [];
    var ov = document.getElementById("bs-block-overlay");
    if (!ranges.length) {
      if (ov) {
        ov.innerHTML = "";
        ov.hidden = true;
        ov._bsHtml = "";
      }
      _blockOverlayKey = "";
      return;
    }
    ensureBlockOverlayTimer();
    if (window.getComputedStyle(box).position === "static") box.style.position = "relative";
    if (!ov) {
      ov = document.createElement("div");
      ov.id = "bs-block-overlay";
      box.appendChild(ov);
    }
    ov.hidden = false;
    var center = Number(window.center_freq) || 0;
    var bw = Number(window.bandwidth) || 0;
    var boxW = Math.round(box.clientWidth || 0);
    var key = center + "|" + bw + "|" + boxW + "|" + ranges.map(function (r) {
      return (r && r.lo) + "-" + (r && r.hi);
    }).join(",");
    /* Empty _bsHtml must not count as a hit — a failed first paint used to stick forever. */
    if (!force && key === _blockOverlayKey && ov._bsHtml) return;
    if (!(center > 0 && bw > 0 && boxW > 0)) {
      /* Do not cache this key — retry when the waterfall has a real width. */
      ov.innerHTML = "";
      ov._bsHtml = "";
      _blockOverlayKey = "";
      return;
    }
    var lo = center - bw / 2;
    var hi = center + bw / 2;
    var html = "";
    ranges.forEach(function (r) {
      if (!r || !(r.hi > r.lo)) return;
      if (r.hi < lo || r.lo > hi) return;
      var x1 = (Math.max(r.lo, lo) - lo) / bw * 100;
      var x2 = (Math.min(r.hi, hi) - lo) / bw * 100;
      if (!(x2 > x1)) return;
      var w = Math.max(0.35, x2 - x1);
      var title = fmtMhz(r.lo) + " – " + fmtMhz(r.hi) + " blocked";
      html += '<div class="bs-block-shade" title="' + escapeHtml(title) +
        '" style="left:' + x1.toFixed(2) + "%;width:" + w.toFixed(2) + '%"></div>';
    });
    _blockOverlayKey = key;
    if (ov._bsHtml !== html || ov.innerHTML !== html) {
      ov._bsHtml = html;
      ov.innerHTML = html;
    }
  }

  function waterfallScreenshot() {
    var box = document.getElementById("webrx-canvas-container");
    var canvases = box ? box.querySelectorAll("canvas") : [];
    if (!box || !canvases.length) {
      setStatus("No waterfall to capture.");
      return;
    }
    var w = Math.max(1, Math.round(box.clientWidth));
    var h = Math.max(1, Math.round(box.clientHeight));
    var out = document.createElement("canvas");
    out.width = w;
    out.height = h;
    var ctx = out.getContext("2d");
    var br = box.getBoundingClientRect();
    Array.prototype.forEach.call(canvases, function (c) {
      try {
        var r = c.getBoundingClientRect();
        ctx.drawImage(c, r.left - br.left, r.top - br.top, r.width, r.height);
      } catch (eDraw) {}
    });
    var url = "";
    try { url = out.toDataURL("image/png"); } catch (eUrl) { url = ""; }
    if (!url) {
      setStatus("Waterfall screenshot was blocked.");
      return;
    }
    var a = document.createElement("a");
    var stamp = new Date().toISOString().replace(/[:.]/g, "-");
    a.href = url;
    a.download = "waterfall-" + stamp + ".png";
    a.click();
    setStatus("Waterfall screenshot saved.");
  }

  var solarFetchedAt = 0;
  var solarError = "";
  var solarInfo = null;
  var solarFetchGen = 0;
  var solarBusy = false;

  function solarXrayClass(flux) {
    flux = Number(flux);
    if (!(flux > 0)) return "—";
    var bands = [["X", 1e-4], ["M", 1e-5], ["C", 1e-6], ["B", 1e-7], ["A", 1e-8]];
    for (var i = 0; i < bands.length; i++) {
      if (flux >= bands[i][1]) return bands[i][0] + (flux / bands[i][1]).toFixed(1);
    }
    return "A0.0";
  }

  function solarFetchJson(url) {
    return fetch(url, { cache: "no-store" }).then(function (r) {
      if (!r || !r.ok) throw new Error("bad");
      return r.json();
    }).catch(function () {
      return null;
    });
  }

  /** Latest SWPC monthly sunspot index from observed-solar-cycle-indices.json. */
  function solarLatestSunspot(indices) {
    if (!Array.isArray(indices)) return { ssn: "—", month: "" };
    var i, row, v;
    for (i = indices.length - 1; i >= 0; i--) {
      row = indices[i];
      if (!row) continue;
      v = Number(row.observed_swpc_ssn);
      if (isFinite(v) && v >= 0) {
        return { ssn: Math.round(v * 10) / 10, month: String(row["time-tag"] || "").trim() };
      }
    }
    for (i = indices.length - 1; i >= 0; i--) {
      row = indices[i];
      if (!row) continue;
      v = Number(row.ssn);
      if (isFinite(v) && v >= 0) {
        return { ssn: Math.round(v * 10) / 10, month: String(row["time-tag"] || "").trim() };
      }
    }
    return { ssn: "—", month: "" };
  }

  /** Count distinct active sunspot regions on the latest NOAA report date. */
  function solarActiveRegions(regions) {
    if (!Array.isArray(regions) || !regions.length) return { count: "—", date: "" };
    var latest = "";
    var i, r;
    for (i = 0; i < regions.length; i++) {
      r = regions[i];
      if (r && r.observed_date && (!latest || r.observed_date > latest)) latest = r.observed_date;
    }
    if (!latest) return { count: "—", date: "" };
    var set = {};
    for (i = 0; i < regions.length; i++) {
      r = regions[i];
      if (r && r.observed_date === latest && r.region != null) set[String(r.region)] = true;
    }
    return { count: Object.keys(set).length, date: latest };
  }

  function solarMetricsGridHtml(info) {
    if (!info) return "";
    var ssnLab = "Sunspot #";
    if (info.ssnMonth) ssnLab = "SSN (" + info.ssnMonth + ")";
    var regLab = "Active regions";
    if (info.regionsDate) regLab = "Regions " + info.regionsDate;
    return (
      '<div class="bs-solar-grid">' +
      "<div><span>" + escapeHtml(ssnLab) + "</span><b>" + escapeHtml(String(info.ssn != null ? info.ssn : "—")) + "</b></div>" +
      "<div><span>" + escapeHtml(regLab) + "</span><b>" + escapeHtml(String(info.regions != null ? info.regions : "—")) + "</b></div>" +
      "<div><span>SFI</span><b>" + escapeHtml(String(info.sfi)) + "</b></div>" +
      "<div><span>K</span><b>" + escapeHtml(String(info.k)) + "</b></div>" +
      "<div><span>A</span><b>" + escapeHtml(String(info.a)) + "</b></div>" +
      "<div><span>X-ray</span><b>" + escapeHtml(info.xray) + "</b></div>" +
      "</div>"
    );
  }

  function solarPaint(info) {
    var host = $("bs-solar-host");
    var when = $("bs-solar-when");
    var btn = $("bs-solar-refresh");
    if (btn) {
      btn.disabled = !!solarBusy;
      btn.textContent = solarBusy ? "Refreshing…" : "Refresh";
    }
    if (!host) return;
    if (!info) {
      if (solarError) {
        host.innerHTML = '<p class="bs-empty">' + escapeHtml(solarError) + "</p>";
      } else {
        host.innerHTML = '<p class="bs-empty">Loading solar weather…</p>';
      }
      if (when) when.textContent = solarBusy ? "refreshing…" : "";
      return;
    }
    if (when) {
      when.textContent = solarBusy
        ? ("updated " + trafficLogAgo(solarFetchedAt) + " · refreshing…")
        : (solarFetchedAt ? ("updated " + trafficLogAgo(solarFetchedAt)) : "");
    }
    host.innerHTML =
      solarMetricsGridHtml(info) +
      '<p class="bs-solar-note">' + escapeHtml(info.note) + "</p>";
  }

  function solarEnsure(force) {
    if (!moreNetworkAllowed("solar")) {
      solarError = "Network budget blocked More fetches.";
      solarPaint(solarInfo);
      return;
    }
    if (!force && solarInfo) {
      solarPaint(solarInfo);
      if (solarFetchedAt && Date.now() - solarFetchedAt < 10 * 60 * 1000) return;
    } else if (!force && solarFetchedAt && Date.now() - solarFetchedAt < 10 * 60 * 1000) {
      solarPaint(solarInfo);
      return;
    }
    if (solarBusy && !force) return;
    var gen = ++solarFetchGen;
    solarBusy = true;
    solarError = "";
    if (solarInfo) solarPaint(solarInfo);
    else solarPaint(null);
    var fluxP = solarFetchJson("https://services.swpc.noaa.gov/products/summary/10cm-flux.json");
    var kP = solarFetchJson("https://services.swpc.noaa.gov/products/noaa-planetary-k-index.json");
    var xP = solarFetchJson("https://services.swpc.noaa.gov/json/goes/primary/xrays-6-hour.json");
    var ssnP = solarFetchJson("https://services.swpc.noaa.gov/json/solar-cycle/observed-solar-cycle-indices.json");
    var regP = solarFetchJson("https://services.swpc.noaa.gov/json/solar_regions.json");
    Promise.all([fluxP, kP, xP, ssnP, regP]).then(function (parts) {
      if (gen !== solarFetchGen) return;
      var flux = parts[0];
      var ks = parts[1];
      var xr = parts[2];
      var ssnPack = solarLatestSunspot(parts[3]);
      var regPack = solarActiveRegions(parts[4]);
      var sfi = "—";
      if (Array.isArray(flux) && flux.length) sfi = flux[flux.length - 1].flux;
      var k = "—";
      var a = "—";
      if (Array.isArray(ks) && ks.length) {
        var last = ks[ks.length - 1];
        if (last && last.Kp != null) k = last.Kp;
        if (last && last.a_running != null) a = last.a_running;
      }
      var xray = "—";
      if (Array.isArray(xr)) {
        for (var i = xr.length - 1; i >= 0; i--) {
          if (xr[i] && xr[i].energy === "0.1-0.8nm" && xr[i].flux > 0) {
            xray = solarXrayClass(xr[i].flux);
            break;
          }
        }
      }
      var kNum = Number(k);
      var sfiNum = Number(sfi);
      var ssnNum = Number(ssnPack.ssn);
      var note = "HF conditions look ordinary.";
      if (kNum >= 5) note = "K is high. HF may be disturbed.";
      else if (kNum >= 4) note = "K is unsettled.";
      else if (ssnNum >= 120) note = "Sunspot number is high — good for HF and 10 m openings.";
      else if (sfiNum >= 150) note = "SFI is strong. Higher bands should be better.";
      else if (sfiNum >= 100) note = "SFI is fair for HF.";
      else if (sfiNum > 0) note = "SFI is low. Lower bands are the safer bet.";
      solarFetchedAt = Date.now();
      solarError = "";
      solarBusy = false;
      solarInfo = {
        sfi: sfi,
        k: k,
        a: a,
        xray: xray,
        ssn: ssnPack.ssn,
        ssnMonth: ssnPack.month,
        regions: regPack.count,
        regionsDate: regPack.date,
        note: note
      };
      solarPaint(solarInfo);
      try { propPaint(); } catch (ePr) {}
      try { mufPaint(); } catch (eMu) {}
    }).catch(function () {
      if (gen !== solarFetchGen) return;
      solarBusy = false;
      solarError = "Solar weather did not answer.";
      solarPaint(solarInfo);
      if (!solarInfo) solarPaint(null);
    });
    if (!window._bs_solar_timer) {
      window._bs_solar_timer = setInterval(function () {
        var propPane = $("bs-more-prop");
        if (!propPane || propPane.hidden) return;
        if (solarFetchedAt && Date.now() - solarFetchedAt < 9 * 60 * 1000) {
          if (solarInfo) solarPaint(solarInfo);
          return;
        }
        solarEnsure(true);
      }, 60000);
    }
  }

  function audioFiltWanted() {
    var f = S.audioFilt || {};
    return !!(f.nb || f.notch || Number(f.eqBass) || Number(f.eqMid) || Number(f.eqTreble));
  }

  function audioFiltRead() {
    var f = S.audioFilt || {};
    if ($("bs-af-nb")) f.nb = !!$("bs-af-nb").checked;
    if ($("bs-af-nb-thr")) f.nbThr = Math.max(0.05, Math.min(0.95, Number($("bs-af-nb-thr").value) || 0.35));
    if ($("bs-af-notch")) f.notch = !!$("bs-af-notch").checked;
    if ($("bs-af-notch-hz")) f.notchHz = Math.max(80, Math.min(5000, Number($("bs-af-notch-hz").value) || 1000));
    if ($("bs-af-bass")) f.eqBass = Math.max(-12, Math.min(12, Number($("bs-af-bass").value) || 0));
    if ($("bs-af-mid")) f.eqMid = Math.max(-12, Math.min(12, Number($("bs-af-mid").value) || 0));
    if ($("bs-af-treble")) f.eqTreble = Math.max(-12, Math.min(12, Number($("bs-af-treble").value) || 0));
    S.audioFilt = f;
    return f;
  }

  function audioFiltSyncUi() {
    var f = S.audioFilt || {};
    if ($("bs-af-nb")) $("bs-af-nb").checked = !!f.nb;
    if ($("bs-af-nb-thr")) $("bs-af-nb-thr").value = f.nbThr != null ? f.nbThr : 0.35;
    if ($("bs-af-notch")) $("bs-af-notch").checked = !!f.notch;
    if ($("bs-af-notch-hz")) $("bs-af-notch-hz").value = f.notchHz || 1000;
    if ($("bs-af-bass")) $("bs-af-bass").value = f.eqBass || 0;
    if ($("bs-af-mid")) $("bs-af-mid").value = f.eqMid || 0;
    if ($("bs-af-treble")) $("bs-af-treble").value = f.eqTreble || 0;
  }

  function audioFiltNodes(eng) {
    if (eng._bs_filt) return eng._bs_filt;
    var ctx = eng.audioContext;
    var nb = ctx.createScriptProcessor(256, 1, 1);
    nb.onaudioprocess = function (e) {
      var input = e.inputBuffer.getChannelData(0);
      var output = e.outputBuffer.getChannelData(0);
      var on = !!(eng._bs_filt && eng._bs_filt.nbOn);
      var thr = (eng._bs_filt && eng._bs_filt.nbThr) || 0.35;
      for (var i = 0; i < input.length; i++) {
        var s = input[i];
        output[i] = (on && Math.abs(s) >= thr) ? 0 : s;
      }
    };
    var notch = ctx.createBiquadFilter();
    notch.type = "notch";
    var bass = ctx.createBiquadFilter();
    bass.type = "lowshelf";
    bass.frequency.value = 180;
    var mid = ctx.createBiquadFilter();
    mid.type = "peaking";
    mid.frequency.value = 1000;
    mid.Q.value = 0.8;
    var treble = ctx.createBiquadFilter();
    treble.type = "highshelf";
    treble.frequency.value = 3200;
    nb.connect(notch);
    notch.connect(bass);
    bass.connect(mid);
    mid.connect(treble);
    eng._bs_filt = { inn: nb, notch: notch, bass: bass, mid: mid, treble: treble, out: treble, inserted: false, nbOn: false, nbThr: 0.35 };
    return eng._bs_filt;
  }

  function audioFiltApply() {
    var eng = window.audioEngine;
    if (!eng || !eng.audioContext || !eng.audioNode || !eng.gainNode) return;
    var f = audioFiltRead();
    var chain = audioFiltNodes(eng);
    chain.nbOn = !!f.nb;
    chain.nbThr = f.nbThr;
    try {
      chain.notch.frequency.value = f.notchHz || 1000;
      chain.notch.Q.value = f.notch ? 8 : 0.0001;
      chain.bass.gain.value = Number(f.eqBass) || 0;
      chain.mid.gain.value = Number(f.eqMid) || 0;
      chain.treble.gain.value = Number(f.eqTreble) || 0;
    } catch (eSet) {}
    var want = audioFiltWanted();
    if (want && !chain.inserted) {
      try { eng.audioNode.disconnect(eng.gainNode); } catch (eDisc) {}
      try { eng.audioNode.connect(chain.inn); } catch (eIn) {}
      try { chain.out.connect(eng.gainNode); } catch (eOut) {}
      chain.inserted = true;
    } else if (!want && chain.inserted) {
      try { eng.audioNode.disconnect(chain.inn); } catch (eD1) {}
      try { chain.out.disconnect(eng.gainNode); } catch (eD2) {}
      try { eng.audioNode.connect(eng.gainNode); } catch (eBack) {}
      chain.inserted = false;
    }
  }

  function bindAudioFilters() {
    var root = $("bs-af-box");
    if (!root || root._bsAfWired) return;
    root._bsAfWired = true;
    audioFiltSyncUi();
    root.addEventListener("input", function () {
      audioFiltRead();
      saveSettings();
      audioFiltApply();
    });
    root.addEventListener("change", function () {
      audioFiltRead();
      saveSettings();
      audioFiltApply();
    });
  }

  function setRangeSubTab(name, opts) {
    opts = opts || {};
    if (name === "spectrum") name = "scan";
    var allowed = { scan: 1, presets: 1, last: 1 };
    if (!allowed[name] || isExtraSubHidden("range", name)) name = firstVisibleExtraSub("range", "scan");
    var root = $("bs-tab-range");
    if (!root) return;
    Array.prototype.forEach.call(root.querySelectorAll(".bs-rg-sub"), function (btn) {
      var id = btn.getAttribute("data-rg-sub");
      var hide = isExtraSubHidden("range", id);
      btn.hidden = hide;
      if (hide) btn.setAttribute("hidden", ""); else btn.removeAttribute("hidden");
      var on = !hide && id === name;
      btn.classList.toggle("bs-rg-sub-on", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    Array.prototype.forEach.call(root.querySelectorAll(".bs-rg-subpane"), function (pane) {
      var id = pane.getAttribute("data-rg-sub");
      var on = !isExtraSubHidden("range", id) && id === name;
      pane.classList.toggle("bs-rg-sub-on", on);
      if (on) pane.removeAttribute("hidden");
      else pane.setAttribute("hidden", "");
    });
    if (name === "scan") { try { ensureRangeSdrShowUi(); } catch (eRgSdr) {} }
    if (name === "presets") { try { rangePresetsOnTab(); } catch (eP) {} }
    if (name === "last") { try { rangeLastOnTab(); } catch (eL) {} }
    if (!opts.skipSave) {
      try { if (extraOn("rememberSubs")) window.localStorage.setItem("owrx_toolbox_rg_sub_v1", name); } catch (e) {}
    }
    try { injectBoxHelpButtons(root); } catch (eH) {}
  }

  function restoreRangeSubTab() {
    var name = firstVisibleExtraSub("range", "scan");
    try {
      var raw = extraOn("rememberSubs") ? window.localStorage.getItem("owrx_toolbox_rg_sub_v1") : null;
      if (raw === "spectrum") raw = "scan";
      if (raw && { scan: 1, presets: 1, last: 1 }[raw] && !isExtraSubHidden("range", raw)) name = raw;
    } catch (e) {}
    setRangeSubTab(name, { skipSave: true });
  }

  var RANGE_RECIPES = [
    { name: "Airband", start: 118, end: 137, note: "Civil VHF" },
    { name: "Marine", start: 156, end: 163, note: "VHF marine" },
    { name: "2 m FM", start: 144, end: 148, note: "Ham" },
    { name: "70 cm", start: 430, end: 440, note: "Ham" },
    { name: "PMR446", start: 446, end: 446.2, note: "EU PMR" },
    { name: "FM broadcast", start: 88, end: 108, note: "WFM" },
    { name: "CB", start: 26.9, end: 27.5, note: "HF CB" },
    { name: "20 m", start: 14, end: 14.35, note: "HF" }
  ];

  function rangeApplySpan(start, end) {
    if ($("bs-range-start")) $("bs-range-start").value = String(start);
    if ($("bs-range-end")) $("bs-range-end").value = String(end);
    try { setRangeSubTab("scan"); } catch (e) {}
    setStatus("Range " + start + "–" + end + " MHz.");
  }

  function rangePresetsOnTab() {
    var host = $("bs-rg-presets");
    if (!host) return;
    bindLightIoPair("bs-rg-presets-export", "bs-rg-presets-import", "bs-rg-presets-file",
      function () {
        return {
          kind: "owrx_toolbox_range_presets",
          when: Date.now(),
          recipes: RANGE_RECIPES,
          saved: Array.isArray(S.rangePresetsList) ? S.rangePresetsList : []
        };
      },
      function (text) {
        var o = JSON.parse(String(text || "").trim());
        var list = (o && o.saved) || (Array.isArray(o) ? o : []);
        if (!Array.isArray(S.rangePresetsList)) S.rangePresetsList = [];
        var n = 0;
        list.forEach(function (p) {
          if (!p || p.start == null || p.end == null) return;
          S.rangePresetsList.push(p);
          n++;
        });
        if (S.rangePresetsList.length > 40) S.rangePresetsList = S.rangePresetsList.slice(-40);
        try { saveSettings(); } catch (e) {}
        try { if (typeof fillRangePresetsSelect === "function") fillRangePresetsSelect(); } catch (e2) {}
        setStatus(n ? ("Imported " + n + " saved preset(s).") : "No saved presets in that file.");
      },
      "toolbox-range-presets.json", "application/json", "Import presets");
    host.innerHTML = RANGE_RECIPES.map(function (r) {
      return '<article class="bs-more-row" data-rg-start="' + r.start + '" data-rg-end="' + r.end + '">' +
        '<span class="bs-more-name">' + escapeHtml(r.name) + "</span>" +
        '<span class="bs-more-mhz">' + r.start + "–" + r.end + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(r.note) + "</span></article>";
    }).join("");
    if (!host._bsWired) {
      host._bsWired = true;
      host.addEventListener("click", function (ev) {
        var row = ev.target && ev.target.closest && ev.target.closest("[data-rg-start]");
        if (!row) return;
        rangeApplySpan(row.getAttribute("data-rg-start"), row.getAttribute("data-rg-end"));
      });
    }
  }

  function rangeLastLoad() {
    try {
      var o = JSON.parse(window.localStorage.getItem("owrx_toolbox_range_last_v1") || "[]");
      return Array.isArray(o) ? o.slice(0, 5) : [];
    } catch (e) { return []; }
  }
  function rangeLastPush(start, end) {
    start = Number(start); end = Number(end);
    if (!(end > start)) return;
    var list = rangeLastLoad().filter(function (x) {
      return !(Math.abs(x.start - start) < 0.001 && Math.abs(x.end - end) < 0.001);
    });
    list.unshift({ start: start, end: end, at: Date.now() });
    try { window.localStorage.setItem("owrx_toolbox_range_last_v1", JSON.stringify(list.slice(0, 5))); } catch (e) {}
  }
  function rangeLastOnTab() {
    var host = $("bs-rg-last");
    if (!host) return;
    bindLightIoPair("bs-rg-last-export", "bs-rg-last-import", "bs-rg-last-file",
      function () {
        return { kind: "owrx_toolbox_range_last", when: Date.now(), last: rangeLastLoad() };
      },
      function (text) {
        var o = JSON.parse(String(text || "").trim());
        var list = (o && o.last) || (Array.isArray(o) ? o : []);
        list = list.filter(function (x) {
          return x && isFinite(x.start) && isFinite(x.end) && Number(x.end) > Number(x.start);
        }).slice(0, 5);
        try { window.localStorage.setItem("owrx_toolbox_range_last_v1", JSON.stringify(list)); } catch (e) {}
        rangeLastOnTab();
        setStatus("Imported " + list.length + " recent range(s).");
      },
      "toolbox-range-last.json", "application/json", "Import last ranges");
    var list = rangeLastLoad();
    if (!list.length) {
      host.innerHTML = '<p class="bs-empty">No recent ranges yet.</p>';
      return;
    }
    host.innerHTML = list.map(function (r) {
      return '<article class="bs-more-row" data-rg-start="' + r.start + '" data-rg-end="' + r.end + '">' +
        '<span class="bs-more-name">' + r.start + "–" + r.end + " MHz</span>" +
        '<span class="bs-more-status">' + escapeHtml(r.at ? trafficLogAgo(r.at) : "") + "</span></article>";
    }).join("");
    if (!host._bsWired) {
      host._bsWired = true;
      host.addEventListener("click", function (ev) {
        var row = ev.target && ev.target.closest && ev.target.closest("[data-rg-start]");
        if (!row) return;
        rangeApplySpan(row.getAttribute("data-rg-start"), row.getAttribute("data-rg-end"));
      });
    }
  }

  function setSkipSubTab(name, opts) {
    opts = opts || {};
    var allowed = { lists: 1, map: 1, import: 1 };
    if (!allowed[name] || isExtraSubHidden("skip", name)) name = firstVisibleExtraSub("skip", "lists");
    var root = $("bs-tab-skip");
    if (!root) return;
    Array.prototype.forEach.call(root.querySelectorAll(".bs-sk-sub"), function (btn) {
      var id = btn.getAttribute("data-sk-sub");
      var hide = isExtraSubHidden("skip", id);
      btn.hidden = hide;
      if (hide) btn.setAttribute("hidden", ""); else btn.removeAttribute("hidden");
      var on = !hide && id === name;
      btn.classList.toggle("bs-sk-sub-on", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    Array.prototype.forEach.call(root.querySelectorAll(".bs-sk-subpane"), function (pane) {
      var id = pane.getAttribute("data-sk-sub");
      var on = !isExtraSubHidden("skip", id) && id === name;
      pane.classList.toggle("bs-sk-sub-on", on);
      if (on) pane.removeAttribute("hidden");
      else pane.setAttribute("hidden", "");
    });
    if (name === "map") { try { skipMapOnTab(); } catch (e) {} }
    if (name === "import") { try { skipImportOnTab(); } catch (e2) {} }
    if (!opts.skipSave) {
      try { if (extraOn("rememberSubs")) window.localStorage.setItem("owrx_toolbox_sk_sub_v1", name); } catch (e) {}
    }
    try { injectBoxHelpButtons(root); } catch (eH) {}
  }
  function restoreSkipSubTab() {
    var name = firstVisibleExtraSub("skip", "lists");
    try {
      var raw = extraOn("rememberSubs") ? window.localStorage.getItem("owrx_toolbox_sk_sub_v1") : null;
      if (raw && { lists: 1, map: 1, import: 1 }[raw] && !isExtraSubHidden("skip", raw)) name = raw;
    } catch (e) {}
    setSkipSubTab(name, { skipSave: true });
  }
  function skipMhzListText() {
    return (S.ignoredFreqs || []).map(function (hz) {
      return (Number(hz) / 1e6).toFixed(4);
    }).join("\n");
  }
  function skipMergeMhzText(raw) {
    var n = 0;
    String(raw || "").split(/[\n,;\s]+/).forEach(function (tok) {
      var mhz = parseFloat(tok);
      if (!(mhz > 0)) return;
      var hz = Math.round(mhz * 1e6);
      if (!S.ignoredFreqs) S.ignoredFreqs = [];
      if (S.ignoredFreqs.indexOf(hz) >= 0) return;
      S.ignoredFreqs.push(hz);
      n++;
    });
    try { saveSettings(); } catch (e) {}
    try { if (typeof renderSkipLists === "function") renderSkipLists(); } catch (e2) {}
    try { if (typeof updateSkiplist === "function") updateSkiplist(); } catch (e3) {}
    try { skipMapOnTab(); } catch (e4) {}
    return n;
  }
  function skipMapOnTab() {
    var host = $("bs-skip-map");
    if (!host) return;
    bindLightIoPair("bs-skip-map-export", "bs-skip-map-import", "bs-skip-map-file",
      function () { return skipMhzListText(); },
      function (text) {
        var n = skipMergeMhzText(text);
        setStatus(n ? ("Imported " + n + " always-skip.") : "Nothing new.");
      },
      "toolbox-always-skip.txt", "text/plain", "Import skip");
    var rows = [];
    (S.ignoredFreqs || []).forEach(function (hz) {
      rows.push({ hz: Number(hz), kind: "always-skip" });
    });
    try {
      var locks = (typeof getLockouts === "function") ? getLockouts() : (window.lockouts || []);
      (locks || []).forEach(function (L) {
        var hz = Number(L.freq || L.hz || L);
        if (hz > 0) rows.push({ hz: hz, kind: "lockout" });
      });
    } catch (e) {}
    rows.sort(function (a, b) { return a.hz - b.hz; });
    if (!rows.length) {
      host.innerHTML = '<p class="bs-empty">No skips or lockouts.</p>';
      return;
    }
    host.innerHTML = rows.map(function (r) {
      return '<article class="bs-more-row" data-sk-hz="' + r.hz + '">' +
        '<span class="bs-more-mhz">' + escapeHtml(fmtMhz(r.hz)) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(r.kind) + "</span></article>";
    }).join("");
    if (!host._bsWired) {
      host._bsWired = true;
      host.addEventListener("click", function (ev) {
        var row = ev.target && ev.target.closest && ev.target.closest("[data-sk-hz]");
        if (!row) return;
        var hz = Number(row.getAttribute("data-sk-hz"));
        if (hz > 0) try { pluginSetFrequency(hz); } catch (e) {}
      });
    }
  }
  function skipImportOnTab() {
    if ($("bs-skip-import-go") && !$("bs-skip-import-go")._bsWired) {
      $("bs-skip-import-go")._bsWired = true;
      $("bs-skip-import-go").onclick = function () {
        var n = skipMergeMhzText(($("bs-skip-import") || {}).value || "");
        setStatus(n ? ("Added " + n + " always-skip.") : "Nothing new.");
      };
    }
    bindLightIoPair("bs-skip-io-export", "bs-skip-io-import", "bs-skip-io-file",
      function () { return skipMhzListText(); },
      function (text) {
        var n = skipMergeMhzText(text);
        if ($("bs-skip-import")) $("bs-skip-import").value = String(text || "");
        setStatus(n ? ("Imported " + n + " always-skip.") : "Nothing new.");
      },
      "toolbox-always-skip.txt", "text/plain", "Import skip");
  }

  function setPeaksSubTab(name, opts) {
    opts = opts || {};
    var allowed = { main: 1, summary: 1, birdies: 1 };
    if (!allowed[name] || isExtraSubHidden("peaks", name)) name = firstVisibleExtraSub("peaks", "main");
    var root = $("bs-tab-peaks");
    if (!root) return;
    Array.prototype.forEach.call(root.querySelectorAll(".bs-pk-sub"), function (btn) {
      var id = btn.getAttribute("data-pk-sub");
      var hide = isExtraSubHidden("peaks", id);
      btn.hidden = hide;
      if (hide) btn.setAttribute("hidden", ""); else btn.removeAttribute("hidden");
      var on = !hide && id === name;
      btn.classList.toggle("bs-pk-sub-on", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    Array.prototype.forEach.call(root.querySelectorAll(".bs-pk-subpane"), function (pane) {
      var id = pane.getAttribute("data-pk-sub");
      var on = !isExtraSubHidden("peaks", id) && id === name;
      pane.classList.toggle("bs-pk-sub-on", on);
      if (on) pane.removeAttribute("hidden");
      else pane.setAttribute("hidden", "");
    });
    if (name === "summary") { try { peaksSummaryOnTab(); } catch (e) {} }
    if (name === "birdies") { try { peaksBirdiesOnTab(); } catch (e2) {} }
    if (!opts.skipSave) {
      try { if (extraOn("rememberSubs")) window.localStorage.setItem("owrx_toolbox_pk_sub_v1", name); } catch (e) {}
    }
    try { injectBoxHelpButtons(root); } catch (eH) {}
  }
  function restorePeaksSubTab() {
    var name = firstVisibleExtraSub("peaks", "main");
    try {
      var raw = extraOn("rememberSubs") ? window.localStorage.getItem("owrx_toolbox_pk_sub_v1") : null;
      if (raw && { main: 1, summary: 1, birdies: 1 }[raw] && !isExtraSubHidden("peaks", raw)) name = raw;
    } catch (e) {}
    setPeaksSubTab(name, { skipSave: true });
  }
  function peaksSummaryOnTab() {
    var host = $("bs-pk-summary");
    if (!host) return;
    var list = (hits || []).slice().sort(function (a, b) { return (b.seen || 0) - (a.seen || 0); });
    var top = list.slice(0, 10);
    var bands = {};
    list.forEach(function (h) {
      var b = "?";
      try { b = activityBandName(h.freq) || "?"; } catch (e) {}
      bands[b] = (bands[b] || 0) + 1;
    });
    bindLightIoPair("bs-pk-summary-export", "bs-pk-summary-import", "bs-pk-summary-file",
      function () {
        return {
          kind: "owrx-toolbox",
          when: Date.now(),
          hits: top.map(hitForExport),
          bands: bands
        };
      },
      function (text, src) { runImportText("json", text, src || "summary-import"); },
      "toolbox-pk-summary.json", "application/json", "Import peaks");
    var html = "<p><b>Top 10 by Seen</b></p>";
    if (!top.length) html += '<p class="bs-empty">No peaks yet.</p>';
    else html += top.map(function (h) {
      return '<article class="bs-more-row" data-pk-hz="' + h.freq + '">' +
        '<span class="bs-more-mhz">' + escapeHtml(fmtMhz(h.freq)) + "</span>" +
        '<span class="bs-more-status">seen ' + (h.seen || 0) + (h.db != null ? (" · " + Math.round(h.db) + " dB") : "") + "</span></article>";
    }).join("");
    html += "<p style=\"margin-top:8px\"><b>By band</b></p>";
    Object.keys(bands).sort(function (a, b) { return bands[b] - bands[a]; }).slice(0, 12).forEach(function (b) {
      html += '<article class="bs-more-row"><span class="bs-more-name">' + escapeHtml(b) + '</span><span class="bs-more-status">' + bands[b] + "</span></article>";
    });
    host.innerHTML = html;
    if (!host._bsWired) {
      host._bsWired = true;
      host.addEventListener("click", function (ev) {
        var row = ev.target && ev.target.closest && ev.target.closest("[data-pk-hz]");
        if (!row) return;
        var hz = Number(row.getAttribute("data-pk-hz"));
        if (hz > 0) try { pluginSetFrequency(hz); } catch (e) {}
      });
    }
  }
  function peaksBirdiesOnTab() {
    var host = $("bs-pk-birdies");
    if (!host) return;
    var ign = {};
    (S.ignoredFreqs || []).forEach(function (hz) { ign[Math.round(hz / 1000)] = 1; });
    var rows = (hits || []).filter(function (h) {
      if (!h) return false;
      if ((h.seen || 0) >= 8) return true;
      return !!ign[Math.round(h.freq / 1000)];
    }).sort(function (a, b) { return (b.seen || 0) - (a.seen || 0); }).slice(0, 60);
    bindLightIoPair("bs-pk-birdies-export", "bs-pk-birdies-import", "bs-pk-birdies-file",
      function () {
        return {
          kind: "owrx-toolbox",
          when: Date.now(),
          hits: rows.map(hitForExport)
        };
      },
      function (text, src) { runImportText("json", text, src || "birdies-import"); },
      "toolbox-pk-birdies.json", "application/json", "Import peaks");
    if (!rows.length) {
      host.innerHTML = '<p class="bs-empty">No birdie-like peaks yet.</p>';
      return;
    }
    host.innerHTML = rows.map(function (h) {
      var skipped = !!ign[Math.round(h.freq / 1000)];
      return '<article class="bs-more-row" data-pk-hz="' + h.freq + '">' +
        '<span class="bs-more-mhz">' + escapeHtml(fmtMhz(h.freq)) + "</span>" +
        '<span class="bs-more-status">seen ' + (h.seen || 0) + (skipped ? " · always-skip" : "") + "</span></article>";
    }).join("");
    if (!host._bsWired) {
      host._bsWired = true;
      host.addEventListener("click", function (ev) {
        var row = ev.target && ev.target.closest && ev.target.closest("[data-pk-hz]");
        if (!row) return;
        var hz = Number(row.getAttribute("data-pk-hz"));
        if (hz > 0) try { pluginSetFrequency(hz); } catch (e) {}
      });
    }
  }

  function fillBookmarkEditor(kind, freq) {
    kind = kind === "loaded" ? "loaded" : "local";
    freq = Number(freq);
    if (!isFinite(freq) || freq <= 0) {
      clearBookmarkEditor();
      return;
    }
    var name = "";
    var mode = "nfm";
    var found = false;
    if (kind === "loaded") {
      (loadedBookmarks || []).forEach(function (b) {
        if (Math.abs(b.frequency - freq) < 2500) {
          name = b.name || "";
          mode = b.modulation || b.mode || "nfm";
          freq = b.frequency;
          found = true;
        }
      });
    } else {
      (localBookmarkList() || []).forEach(function (b) {
        if (Math.abs(b.frequency - freq) < 2500) {
          name = bookmarkDisplayName(b) || b.name || "";
          mode = b.modulation || "nfm";
          freq = b.frequency;
          found = true;
        }
      });
    }
    if (!found) {
      name = existingName(freq) || fmtMhz(freq);
      mode = currentDemodMode();
    }
    if ($("bs-bm-edit-kind")) $("bs-bm-edit-kind").value = kind;
    if ($("bs-bm-edit-orig")) $("bs-bm-edit-orig").value = String(freq);
    if ($("bs-bm-edit-name")) $("bs-bm-edit-name").value = name;
    if ($("bs-bm-edit-mhz")) $("bs-bm-edit-mhz").value = fmtMhzNum(freq);
    ensureBookmarkModeOptions(mode);
    setBookmarkEditorStatus((kind === "loaded" ? "Loaded" : "Local") + " · " + fmtMhz(freq));
    highlightBookmarkEditorRow(kind, freq);
    try {
      openBookmarkEditPopup("Edit bookmark");
      if ($("bs-bm-edit-name")) $("bs-bm-edit-name").focus();
    } catch (eF) {}
  }

  function highlightBookmarkEditorRow(kind, freq) {
    var host = $("bs-bmlist");
    if (!host) return;
    Array.prototype.forEach.call(host.querySelectorAll(".bs-bm-row"), function (row) {
      row.classList.remove("bs-bm-editing");
    });
    if (!freq) return;
    var attr = kind === "loaded" ? "data-loaded-tune" : "data-bm-tune";
    Array.prototype.forEach.call(host.querySelectorAll(".bs-bm-row[" + attr + "]"), function (row) {
      if (Math.abs(Number(row.getAttribute(attr)) - freq) < 2500) {
        row.classList.add("bs-bm-editing");
      }
    });
  }

  function writeLocalBookmarkStore(list) {
    if (typeof BookmarkLocalStorage !== "function") {
      setStatus("Cannot save blue bookmarks here (BookmarkLocalStorage missing).");
      return false;
    }
    var store = (window.bookmarks && bookmarks.localBookmarks) || new BookmarkLocalStorage();
    store.setBookmarks(list);
    if (window.bookmarks && typeof bookmarks.loadLocalBookmarks === "function") {
      try { bookmarks.loadLocalBookmarks(); } catch (e) {}
    }
    return true;
  }

  function saveBookmarkFromEditor() {
    var kind = ($("bs-bm-edit-kind") && $("bs-bm-edit-kind").value) || "local";
    if (kind !== "loaded") kind = "local";
    var name = $("bs-bm-edit-name") ? String($("bs-bm-edit-name").value || "").trim() : "";
    var freq = parseBookmarkMhzInput($("bs-bm-edit-mhz") && $("bs-bm-edit-mhz").value);
    var mode = $("bs-bm-edit-mode") ? String($("bs-bm-edit-mode").value || "nfm").trim() : "nfm";
    var orig = Number($("bs-bm-edit-orig") && $("bs-bm-edit-orig").value);
    if (!freq) {
      setBookmarkEditorStatus("Enter a valid MHz.");
      setStatus("Bookmark edit needs a frequency.");
      return;
    }
    if (!name) name = fmtMhz(freq);
    if (!mode) mode = "nfm";

    if (kind === "loaded") {
      var foundL = false;
      var matchOrig = isFinite(orig) && orig > 0;
      (loadedBookmarks || []).forEach(function (b) {
        var hit = matchOrig
          ? Math.abs(b.frequency - orig) < 2500
          : Math.abs(b.frequency - freq) < 2500;
        if (hit) {
          b.frequency = freq;
          b.name = name;
          b.modulation = mode;
          foundL = true;
        }
      });
      if (!foundL) {
        loadedBookmarks.push({
          name: name,
          frequency: freq,
          modulation: mode,
          pid: guessPidForFreq(freq) || ""
        });
      }
      saveLoadedBookmarks();
      if ($("bs-bm-edit-orig")) $("bs-bm-edit-orig").value = String(freq);
      renderBookmarkPane();
      renderHits();
      setBookmarkEditorStatus("Saved loaded · " + fmtMhz(freq));
      setStatus("Saved loaded bookmark “" + name + "”.");
      highlightBookmarkEditorRow("loaded", freq);
      return;
    }

    if (typeof BookmarkLocalStorage !== "function") {
      setBookmarkEditorStatus("Local bookmarks API missing.");
      return;
    }
    backupLocalBookmarks("before-edit-save");
    var list = localBookmarkList() || [];
    var found = false;
    var matchO = isFinite(orig) && orig > 0;
    list.forEach(function (b) {
      var hit = matchO
        ? Math.abs(b.frequency - orig) < 2500
        : Math.abs(b.frequency - freq) < 2500;
      if (hit) {
        b.frequency = freq;
        b.name = name;
        b.modulation = mode;
        if (b.auto && !/^\[auto\]/i.test(name)) b.auto = false;
        found = true;
      }
    });
    if (!found) {
      var id = 1;
      if (list.length) {
        id = 1 + Math.max.apply(Math, list.map(function (b) { return b.id || 0; }));
      }
      list.push({
        id: id,
        name: name,
        frequency: freq,
        modulation: mode,
        underlying: "",
        description: "Edited in Toolbox",
        scannable: true,
        auto: /^\[auto\]/i.test(name)
      });
    }
    if (!writeLocalBookmarkStore(list)) return;
    hits.forEach(function (h) {
      if (Math.abs(h.freq - (matchO ? orig : freq)) < 2500 || Math.abs(h.freq - freq) < 2500) {
        h.name = name;
        h.mode = mode;
        h.freq = freq;
      }
    });
    saveHits();
    if ($("bs-bm-edit-orig")) $("bs-bm-edit-orig").value = String(freq);
    if ($("bs-bm-edit-kind")) $("bs-bm-edit-kind").value = "local";
    refreshBookmarks();
    renderHits();
    setBookmarkEditorStatus("Saved local · " + fmtMhz(freq));
    setStatus("Saved bookmark “" + name + "”.");
    highlightBookmarkEditorRow("local", freq);
  }

  function deleteBookmarkFromEditor() {
    if (typeof publicAllowsFeature === "function" && !publicAllowsFeature("clearData")) {
      setStatus("Delete bookmark is not allowed for visitors.");
      return;
    }
    var kind = ($("bs-bm-edit-kind") && $("bs-bm-edit-kind").value) || "local";
    var orig = Number($("bs-bm-edit-orig") && $("bs-bm-edit-orig").value);
    var freq = parseBookmarkMhzInput($("bs-bm-edit-mhz") && $("bs-bm-edit-mhz").value) || orig;
    if (!isFinite(freq) || freq <= 0) {
      setBookmarkEditorStatus("Nothing selected to delete.");
      return;
    }
    if (!window.confirm("Delete bookmark at " + fmtMhz(freq) + "?")) return;

    if (kind === "loaded") {
      var before = loadedBookmarks.length;
      loadedBookmarks = (loadedBookmarks || []).filter(function (b) {
        return Math.abs(b.frequency - freq) >= 2500 &&
          (!isFinite(orig) || Math.abs(b.frequency - orig) >= 2500);
      });
      if (loadedBookmarks.length === before) {
        setBookmarkEditorStatus("Loaded bookmark not found.");
        return;
      }
      saveLoadedBookmarks();
      clearBookmarkEditor({ close: true });
      renderBookmarkPane();
      setStatus("Deleted loaded bookmark " + fmtMhz(freq) + ".");
      return;
    }

    if (typeof BookmarkLocalStorage !== "function") {
      setBookmarkEditorStatus("Local bookmarks API missing.");
      return;
    }
    backupLocalBookmarks("before-edit-delete");
    var list = localBookmarkList() || [];
    var next = list.filter(function (b) {
      return Math.abs(b.frequency - freq) >= 2500 &&
        (!isFinite(orig) || Math.abs(b.frequency - orig) >= 2500);
    });
    if (next.length === list.length) {
      setBookmarkEditorStatus("Local bookmark not found.");
      return;
    }
    if (!writeLocalBookmarkStore(next)) return;
    clearBookmarkEditor({ close: true });
    refreshBookmarks();
    setStatus("Deleted local bookmark " + fmtMhz(freq) + ".");
  }

  function newBookmarkFromTune() {
    var freq = Number(window.center_freq);
    if (!isFinite(freq) || freq <= 0) {
      setBookmarkEditorStatus("No current tune frequency.");
      setStatus("Tune the receiver first, then New from tune.");
      openBookmarkEditPopup("New bookmark");
      return;
    }
    if ($("bs-bm-edit-kind")) $("bs-bm-edit-kind").value = "local";
    if ($("bs-bm-edit-orig")) $("bs-bm-edit-orig").value = "";
    if ($("bs-bm-edit-name")) {
      $("bs-bm-edit-name").value = existingName(freq) || fmtMhz(freq);
    }
    if ($("bs-bm-edit-mhz")) $("bs-bm-edit-mhz").value = fmtMhzNum(freq);
    ensureBookmarkModeOptions(currentDemodMode());
    setBookmarkEditorStatus("New from tune · " + fmtMhz(freq) + " — edit name then Save.");
    highlightBookmarkEditorRow();
    try {
      openBookmarkEditPopup("New bookmark");
      if ($("bs-bm-edit-name")) {
        $("bs-bm-edit-name").focus();
        $("bs-bm-edit-name").select();
      }
    } catch (eN) {}
  }

  function levelAt(freq) {
    var data = wf();
    var center = window.center_freq;
    var bw = window.bandwidth;
    if (!data || !data.length || !bw) return -999;
    var i = Math.floor((freq - (center - bw / 2)) / bw * data.length);
    if (i < 0 || i >= data.length) return -999;
    return data[i];
  }

  var smeterTrack = [];

  function smeterLin() {
    var v = window.smeter_level;
    return (typeof v === "number" && isFinite(v) && v > 0) ? v : null;
  }

  /** Raw OpenWebRX relative S-meter (no Toolbox calibration offset). */
  function smeterDbRaw() {
    var lin = smeterLin();
    if (lin == null) return null;
    var db;
    try {
      if (typeof window.getLogSmeterValue === "function") db = window.getLogSmeterValue(lin);
      else db = 10 * Math.log10(lin);
    } catch (eDb) {
      return null;
    }
    db = Number(db);
    /* getLogSmeterValue can return NaN briefly — never surface that as “NaN dB”. */
    return isFinite(db) ? db : null;
  }

  /** Offset for a given MHz on the *active* SDR: interpolate points, else flat bucket offset. */
  function smeterCalOffsetForMhz(mhz) {
    var pts = getSmeterCalPoints();
    if (!pts.length) {
      var o0 = Number(smeterCalBucket().offsetDb);
      return isFinite(o0) ? o0 : 0;
    }
    mhz = Number(mhz);
    if (!isFinite(mhz) || mhz <= 0) {
      if (pts.length === 1) return pts[0].offsetDb;
      var sum = 0;
      pts.forEach(function (p) { sum += p.offsetDb; });
      return sum / pts.length;
    }
    if (pts.length === 1) return pts[0].offsetDb;
    if (mhz <= pts[0].mhz) return pts[0].offsetDb;
    if (mhz >= pts[pts.length - 1].mhz) return pts[pts.length - 1].offsetDb;
    var i, a, b, t;
    for (i = 0; i < pts.length - 1; i++) {
      a = pts[i];
      b = pts[i + 1];
      if (mhz >= a.mhz && mhz <= b.mhz) {
        t = (b.mhz - a.mhz) < 1e-9 ? 0 : (mhz - a.mhz) / (b.mhz - a.mhz);
        return a.offsetDb + t * (b.offsetDb - a.offsetDb);
      }
    }
    return pts[pts.length - 1].offsetDb;
  }

  function smeterCalOffset() {
    return smeterCalOffsetForMhz(smeterTuneMhz());
  }

  /**
   * Toolbox display S-meter only (Explore / Identify / cal dialog).
   * Never writes smeter_level, never wraps getLogSmeterValue, never paints OpenWebRX’s meter.
   * Anything that must match stock OWRX (squelch open, auto-SQL) must use smeterDbRaw().
   */
  function smeterDb() {
    var db = smeterDbRaw();
    if (db == null) return null;
    var o = smeterCalOffset();
    if (o) db += o;
    return isFinite(db) ? db : null;
  }

  function smeterDbLabel(db) {
    if (db == null || !isFinite(Number(db))) return "—";
    var n = Math.round(Number(db) * 10) / 10;
    if (!isFinite(n)) return "—";
    return n + " dB";
  }

  /** Tune strip must never keep a literal NaN from a bad sample or a stray node. */
  function exploreScrubNanText(root) {
    root = root || $("bs-ex-box-tune");
    if (!root || !root.querySelectorAll) return;
    var nodes = root.querySelectorAll("b, span, button, p, label, div");
    var i, j, node, s;
    for (i = 0; i < nodes.length; i++) {
      node = nodes[i];
      if (!node || !node.childNodes) continue;
      for (j = 0; j < node.childNodes.length; j++) {
        if (node.childNodes[j].nodeType !== 3) continue;
        s = node.childNodes[j].nodeValue;
        if (!s || s.indexOf("NaN") < 0) continue;
        node.childNodes[j].nodeValue = s.replace(/NaN/g, "—");
      }
    }
  }

  function squelchSliderDb() {
    try {
      if (window.UI && typeof UI.getDemodulatorPanel === "function") {
        var panel = UI.getDemodulatorPanel();
        if (panel && panel.el) {
          var raw = panel.el.find(".openwebrx-squelch-slider").val();
          var n = parseFloat(raw);
          if (isFinite(n)) return n;
        }
      }
      if (window.UI && typeof UI.getDemodulator === "function") {
        var demod = UI.getDemodulator();
        if (demod && typeof demod.getSquelch === "function") {
          var sq = demod.getSquelch();
          if (isFinite(sq)) return sq;
        }
      }
    } catch (e) {}
    return null;
  }

  /** Compare against OpenWebRX SQL slider using the stock (uncalibrated) meter scale. */
  function squelchOpen() {
    var db = smeterDbRaw();
    var thr = squelchSliderDb();
    if (db == null || thr == null) return null;
    return db >= thr;
  }

  function trackSmeterSample() {
    /* Raw samples — modulation / voice gates must not shift with Toolbox display cal. */
    var db = smeterDbRaw();
    if (db == null) return;
    smeterTrack.push(db);
    if (smeterTrack.length > SMETER_TRACK_N) smeterTrack.shift();
  }

  function smeterModulation() {
    return stddev(smeterTrack);
  }

  function isAirbandPid(pid, mode) {
    var m = mode || guessMode(pid);
    return /^air_|^vor/.test(pid || "") || m === "am";
  }

  function levelAtWindow(freq, halfBins) {
    halfBins = halfBins || 1;
    var data = wf();
    var center = window.center_freq;
    var bw = window.bandwidth;
    if (!data || !data.length || !bw) return -999;
    var i = Math.floor((freq - (center - bw / 2)) / bw * data.length);
    var best = -999;
    var lo = Math.max(0, i - halfBins);
    var hi = Math.min(data.length - 1, i + halfBins);
    for (var j = lo; j <= hi; j++) {
      if (data[j] > best) best = data[j];
    }
    return best;
  }

  function localNoiseNear(freq, halfBins) {
    halfBins = halfBins || 6;
    var data = wf();
    var center = window.center_freq;
    var bw = window.bandwidth;
    if (!data || !data.length || !bw) return noiseFloor(data);
    var i = Math.floor((freq - (center - bw / 2)) / bw * data.length);
    var samples = [];
    var lo = Math.max(0, i - halfBins);
    var hi = Math.min(data.length - 1, i + halfBins);
    for (var j = lo; j <= hi; j++) {
      if (Math.abs(j - i) <= 1) continue;
      samples.push(data[j]);
    }
    if (samples.length < 4) return noiseFloor(data);
    samples.sort(function (a, b) { return a - b; });
    return samples[Math.floor(samples.length * 0.35)];
  }

  function listenRecordThreshold(floor, pid, mode) {
    var t = Number(S.threshDb) || 7;
    if (isAirbandPid(pid, mode)) return floor + Math.max(t, 9);
    if (/^fm_/.test(pid || "")) return floor + Math.max(t - 1, 5);
    return floor + Math.max(t, 6);
  }

  function normalizeRecMode(mode) {
    mode = String(mode || "").toLowerCase();
    if (mode === REC_MODE_AUTO) return REC_MODE_AUTO;
    if (REC_MODES.indexOf(mode) >= 0) return mode;
    if (mode === "simple") return REC_MODE_ORIGINAL;
    return REC_MODE_BALANCED;
  }

  /** Pick Record mode gates for a MHz / profile when Record mode is Auto. */
  function recModeForFreq(freq, pid, demodMode) {
    freq = Number(freq) || 0;
    pid = String(pid || "");
    demodMode = String(demodMode || guessMode(pid)).toLowerCase();
    if (isAirbandPid(pid, demodMode)) return REC_MODE_AIRBAND;
    var info = modeForBandFreq(freq);
    var why = info && info.why ? String(info.why).toLowerCase() : "";
    var bandMod = info && info.mode ? String(info.mode).toLowerCase() : demodMode;
    if (bandMod === "am" && freq >= 108e6 && freq < 137e6) return REC_MODE_AIRBAND;
    if (bandMod === "am" && (/broadcast|mw|lw|cb/.test(why) || freq < 30e6)) return REC_MODE_AIRBAND;
    if (bandMod === "wfm" || bandMod === "fm" || bandMod === "dab") return REC_MODE_STRICT;
    if (bandMod === "nfm" || demodMode === "nfm") {
      if (/2 m|70 cm|10 m fm|6 m fm|4 m|pmr|marine|vhf|uhf|ais/.test(why)) return REC_MODE_HAM;
      if (freq >= 144e6 && freq <= 470e6) return REC_MODE_HAM;
      if (freq >= 28e6 && freq < 30e6) return REC_MODE_HAM;
    }
    if (bandMod === "usb" || bandMod === "lsb" || bandMod === "cw") return REC_MODE_BALANCED;
    return REC_MODE_BALANCED;
  }

  function effectiveRecMode(freq, pid, demodMode) {
    var stored = normalizeRecMode(S.recMode);
    if (stored === REC_MODE_AUTO) {
      freq = Number(freq) || 0;
      if (!freq) return REC_MODE_BALANCED;
      return recModeForFreq(freq, pid, demodMode);
    }
    return stored;
  }

  function recModeLabel(mode) {
    var m = normalizeRecMode(mode);
    var labels = {
      auto: "Auto",
      original: "Original",
      sensitive: "Sensitive",
      balanced: "Balanced",
      airband: "Airband",
      ham: "Ham NFM",
      strict: "Strict voice",
      continuous: "Continuous"
    };
    return labels[m] || m;
  }

  /** Built-in timing/gates for one Record mode (no user overrides). */
  function recGatePresetParams(mode) {
    mode = normalizeRecMode(mode);
    var p = {
      mode: mode,
      debounceMs: 250,
      quietMs: 700,
      minActiveMs: 450,
      minActiveRatio: 0.1,
      minSnr: 4,
      airMinSnr: 5,
      wfMinSnr: 5,
      airWfMinSnr: 6,
      squelchHeadroom: 1.5,
      airSquelchHeadroom: 2,
      modMin: 0.5,
      airModMin: 0.7,
      pauseOnQuiet: false,
      discardWeak: true,
      squelchOnly: S.recSquelchOnly !== false,
      alwaysOn: false
    };
    if (mode === REC_MODE_ORIGINAL) {
      p.debounceMs = 0;
      p.quietMs = 999999;
      p.minActiveMs = 0;
      p.minActiveRatio = 0;
      p.pauseOnQuiet = false;
      p.discardWeak = false;
      p.squelchOnly = false;
    } else if (mode === REC_MODE_SENSITIVE) {
      p.debounceMs = 50;
      p.quietMs = 1200;
      p.minActiveMs = 200;
      p.minActiveRatio = 0.03;
      p.minSnr = 1;
      p.airMinSnr = 1.5;
      p.wfMinSnr = 2;
      p.airWfMinSnr = 2.5;
      p.squelchHeadroom = 0.25;
      p.airSquelchHeadroom = 0.35;
      p.modMin = 0.25;
      p.airModMin = 0.3;
      p.pauseOnQuiet = false;
      p.discardWeak = false;
      p.squelchOnly = S.recSquelchOnly !== false;
    } else if (mode === REC_MODE_AIRBAND) {
      p.debounceMs = 80;
      p.quietMs = 900;
      p.minActiveMs = 300;
      p.minActiveRatio = 0.04;
      p.minSnr = 1;
      p.airMinSnr = 1;
      p.wfMinSnr = 2;
      p.airWfMinSnr = 2;
      p.squelchHeadroom = 0.4;
      p.airSquelchHeadroom = 0.4;
      p.modMin = 0.3;
      p.airModMin = 0.35;
      p.pauseOnQuiet = false;
      p.discardWeak = false;
      p.squelchOnly = true;
    } else if (mode === REC_MODE_HAM) {
      p.debounceMs = 150;
      p.quietMs = 650;
      p.minActiveMs = 350;
      p.minActiveRatio = 0.08;
      p.minSnr = 3;
      p.airMinSnr = 4;
      p.wfMinSnr = 3.5;
      p.airWfMinSnr = 5;
      p.squelchHeadroom = 1;
      p.airSquelchHeadroom = 1.5;
      p.modMin = 0.55;
      p.airModMin = 0.7;
      p.pauseOnQuiet = false;
      p.discardWeak = true;
      p.squelchOnly = S.recSquelchOnly !== false;
    } else if (mode === REC_MODE_STRICT) {
      p.debounceMs = REC_SIGNAL_DEBOUNCE_MS;
      p.quietMs = REC_SIGNAL_QUIET_MS;
      p.minActiveMs = MIN_CLIP_ACTIVE_MS;
      p.minActiveRatio = MIN_CLIP_ACTIVE_RATIO;
      p.minSnr = 6;
      p.airMinSnr = 7;
      p.wfMinSnr = 6;
      p.airWfMinSnr = 9;
      p.squelchHeadroom = 2;
      p.airSquelchHeadroom = 4;
      p.modMin = 0.9;
      p.airModMin = 1.2;
      p.pauseOnQuiet = true;
      p.discardWeak = true;
      p.squelchOnly = S.recSquelchOnly !== false;
    } else if (mode === REC_MODE_CONTINUOUS) {
      p.debounceMs = 0;
      p.quietMs = 999999;
      p.minActiveMs = 0;
      p.minActiveRatio = 0;
      p.pauseOnQuiet = false;
      p.discardWeak = false;
      p.squelchOnly = false;
      p.alwaysOn = true;
    }
    return p;
  }

  function recGatePresetTargetMode(mode) {
    mode = normalizeRecMode(mode != null ? mode : S.recMode);
    if (mode !== REC_MODE_AUTO) return mode;
    var f = 0;
    try { f = currentTuneHz(); } catch (eF) {}
    if (f > 0) {
      try {
        return recModeForFreq(f, currentProfileId(), exploreCurrentMod());
      } catch (eBand) {}
    }
    return REC_MODE_BALANCED;
  }

  function recGatePresetUiValues(mode) {
    var p = recGatePresetParams(recGatePresetTargetMode(mode));
    var quiet = p.pauseOnQuiet ? p.quietMs : 0;
    if (p.quietMs >= 100000) quiet = 0;
    return {
      debounceMs: p.debounceMs,
      quietMs: quiet,
      minSnrDb: p.minSnr,
      headroomDb: p.squelchHeadroom,
      minRatioPct: Math.round((p.minActiveRatio || 0) * 100)
    };
  }

  function applyRecGatePresetToSettings(mode) {
    var ui = recGatePresetUiValues(mode);
    S.recDebounceMs = ui.debounceMs;
    S.recQuietMs = ui.quietMs;
    S.recMinSnrDb = ui.minSnrDb;
    S.recSquelchHeadroomDb = ui.headroomDb;
    S.recMinClipRatioPct = ui.minRatioPct;
  }

  function syncRecGateUi() {
    var custom = !!S.recCustomGates;
    var chk = $("bs-rec-custom-gates");
    if (chk && document.activeElement !== chk) chk.checked = custom;
    var timing = $("bs-rec-timing-group");
    var gates = $("bs-rec-gates-group");
    if (timing) timing.hidden = !custom;
    if (gates) gates.hidden = !custom;
    var hint = $("bs-rec-preset-hint");
    if (hint) {
      if (custom) {
        hint.textContent = "Custom timing & gates — changing Record mode refills these fields from that preset (edit as needed).";
      } else {
        var stored = normalizeRecMode(S.recMode);
        if (stored === REC_MODE_AUTO) {
          hint.textContent = "Built-in gates per bookmark band on Scan bookmarks (Balanced for Record now). Tick Custom timing & gates only to tweak debounce / SNR / voice % yourself.";
        } else {
          hint.textContent = "Using built-in " + recModeLabel(stored) + " timing & gates. Tick Custom timing & gates only if you want your own numbers.";
        }
      }
    }
    if (custom) {
      if ($("bs-recdebounce") && document.activeElement !== $("bs-recdebounce")) {
        $("bs-recdebounce").value = S.recDebounceMs || 0;
      }
      if ($("bs-recquiet") && document.activeElement !== $("bs-recquiet")) {
        $("bs-recquiet").value = S.recQuietMs || 0;
      }
      if ($("bs-recminsnr") && document.activeElement !== $("bs-recminsnr")) {
        $("bs-recminsnr").value = S.recMinSnrDb || 0;
      }
      if ($("bs-recheadroom") && document.activeElement !== $("bs-recheadroom")) {
        $("bs-recheadroom").value = S.recSquelchHeadroomDb || 0;
      }
      if ($("bs-recminratio") && document.activeElement !== $("bs-recminratio")) {
        $("bs-recminratio").value = S.recMinClipRatioPct || 0;
      }
    }
  }

  function bindRecGateControls() {
    var modeEl = $("bs-recmode");
    if (!modeEl || modeEl._bsRecGateBound) return;
    modeEl._bsRecGateBound = true;
    modeEl.onchange = function () {
      readRecSettings();
      if (S.recCustomGates) applyRecGatePresetToSettings(S.recMode);
      saveSettings();
      syncRecGateUi();
    };
    var customEl = $("bs-rec-custom-gates");
    if (customEl && !customEl._bsRecGateBound) {
      customEl._bsRecGateBound = true;
      customEl.onchange = function () {
        readRecSettings();
        if (S.recCustomGates) applyRecGatePresetToSettings(S.recMode);
        saveSettings();
        syncRecGateUi();
        setStatus(S.recCustomGates
          ? "Custom recording gates on — edit Timing & Gates, or change mode to refill from a preset."
          : "Using Record mode presets only.");
      };
    }
    ["bs-recsquelch", "bs-recdebounce", "bs-recquiet", "bs-recminsnr", "bs-recheadroom", "bs-recminratio"].forEach(function (id) {
      var el = $(id);
      if (!el || el._bsRecGateBound) return;
      el._bsRecGateBound = true;
      el.onchange = readForm;
    });
  }

  function recGateParams(ctx) {
    ctx = ctx || {};
    var mode = effectiveRecMode(ctx.freq, ctx.pid, ctx.mode);
    var p = recGatePresetParams(mode);
    p.mode = mode;
    if (!S.recCustomGates) return p;
    var snr = Number(S.recMinSnrDb);
    if (isFinite(snr)) {
      p.minSnr = snr;
      p.airMinSnr = snr + 1;
      p.wfMinSnr = snr;
      p.airWfMinSnr = snr + 2;
    }
    var hd = Number(S.recSquelchHeadroomDb);
    if (isFinite(hd)) {
      p.squelchHeadroom = hd;
      p.airSquelchHeadroom = hd + 0.5;
    }
    var ratioPct = Number(S.recMinClipRatioPct);
    if (isFinite(ratioPct)) {
      p.minActiveRatio = Math.min(0.95, Math.max(0, ratioPct) / 100);
    }
    var deb = Number(S.recDebounceMs);
    if (isFinite(deb)) p.debounceMs = Math.max(0, Math.min(3000, deb));
    var q = Number(S.recQuietMs);
    if (isFinite(q) && q > 0) p.quietMs = Math.max(100, Math.min(5000, q));
    return p;
  }

  function voiceSignalMetrics(freq, pid, mode) {
    var air = isAirbandPid(pid, mode);
    var lvl = levelAtWindow(freq, air ? 4 : 2);
    var floor = localNoiseNear(freq, air ? 10 : 6);
    var snr = lvl - floor;
    var thr = listenRecordThreshold(floor, pid, mode);
    trackSmeterSample();
    var sql = squelchOpen();
    /* Raw vs OWRX SQL threshold — not Toolbox display calibration. */
    var sdb = smeterDbRaw();
    var sqlThr = squelchSliderDb();
    var smeterSnr = (sdb != null && sqlThr != null) ? sdb - sqlThr : null;
    return {
      lvl: lvl, floor: floor, snr: snr, thr: thr, sql: sql,
      sdb: sdb, smeterSnr: smeterSnr, mod: smeterModulation(), air: air
    };
  }

  function isRecordableVoice(freq, pid, mode, gate) {
    gate = gate || recGateParams();
    if (gate.alwaysOn || gate.mode === REC_MODE_CONTINUOUS) return true;
    var m = voiceSignalMetrics(freq, pid, mode);
    if (gate.squelchOnly && m.sql === false) return false;
    if (gate.mode === REC_MODE_ORIGINAL) return true;
    var wfStrong = m.lvl >= m.thr && m.snr >= (m.air ? gate.airWfMinSnr : gate.wfMinSnr);
    var headroom = m.air ? gate.airSquelchHeadroom : gate.squelchHeadroom;
    var minSnr = m.air ? gate.airMinSnr : gate.minSnr;
    if (m.sql === true) {
      if (m.smeterSnr != null && m.smeterSnr >= headroom) return true;
      if (m.mod >= (m.air ? gate.airModMin : gate.modMin) &&
          m.smeterSnr != null && m.smeterSnr >= Math.max(0.5, headroom - 1.5)) return true;
      if (gate.mode === REC_MODE_STRICT) return false;
      if (gate.mode === REC_MODE_SENSITIVE || gate.mode === REC_MODE_AIRBAND) {
        return m.smeterSnr == null || m.smeterSnr >= 0;
      }
      return m.smeterSnr != null && m.smeterSnr >= 0.5 && m.mod >= (m.air ? gate.airModMin * 0.7 : gate.modMin * 0.7);
    }
    if (m.sql === false) return false;
    /* No S-meter yet (receiver audio not started) or squelch readout missing — use waterfall. */
    if (m.sql == null) {
      if (wfStrong) return true;
      if (m.air && m.lvl >= m.thr) return true;
      return false;
    }
    if (gate.squelchOnly) return false;
    return wfStrong && m.snr >= minSnr;
  }

  function shouldStartRecording(freq, pid, mode, isBusy, gate) {
    gate = gate || recGateParams();
    if (gate.alwaysOn || gate.mode === REC_MODE_CONTINUOUS) return true;
    if (gate.mode === REC_MODE_ORIGINAL) return !!isBusy;
    if (isRecordableVoice(freq, pid, mode, gate)) return true;
    /* Last resort when SQL state is unknown: same busy cue as the scan hold logic. */
    if (isBusy && squelchOpen() == null && isAirbandPid(pid, mode)) return true;
    return false;
  }

  function listenActivityBusy(recGate, isBusy, recordable) {
    if (recGate.alwaysOn || recGate.mode === REC_MODE_CONTINUOUS) return true;
    return recGate.mode === REC_MODE_ORIGINAL ? !!isBusy : !!recordable;
  }

  function listenActivityLabel(recGate, isBusy, recordable) {
    if (recGate.alwaysOn || recGate.mode === REC_MODE_CONTINUOUS) return " · rec";
    if (recGate.mode === REC_MODE_ORIGINAL) return isBusy ? " · busy" : " · quiet";
    return recordable ? " · voice" : (isBusy ? " · busy" : " · quiet");
  }

  function profileValueForPid(pid) {
    var list = profiles();
    for (var i = 0; i < list.length; i++) {
      if (list[i].id === pid) return list[i].value;
    }
    return null;
  }

  function consumeListenAbort(freq, name) {
    if (listenCmd === "always") {
      ignoreFreq(freq);
      listenCmd = "";
      setStatus("Always skip " + (name || fmtMhz(freq)) + " — will not land here again");
      return true;
    }
    if (listenCmd === "lock") {
      lockout(freq);
      listenCmd = "";
      setStatus("Locked out " + (name || fmtMhz(freq)) + " for " + (S.lockoutMin || 30) + " min");
      return true;
    }
    if (listenCmd === "skip" || listenCmd === "continue") {
      listenCmd = "";
      return true;
    }
    if (listenCmd === "prev") {
      /* leave channel; for-loop handles stepping back */
      return true;
    }
    return shouldSkipTune(freq);
  }

  function listenPassLabel(passNum, maxPasses) {
    if (!(passNum > 0)) return "";
    if (maxPasses == null) maxPasses = listenScanMaxPasses;
    maxPasses = Math.max(0, Number(maxPasses) || 0);
    if (maxPasses > 0) return "Pass " + passNum + "/" + maxPasses + " · ";
    return "Pass " + passNum + " · ";
  }

  function listenBusyThreshold(floor) {
    return floor + Math.max(3, (Number(S.threshDb) || 7) - 3);
  }

  function readListenSettings() {
    if ($("bs-listensec")) S.listenSec = Math.max(1, Math.min(20, Number($("bs-listensec").value) || 4));
    if ($("bs-listen-passes")) S.listenPasses = Math.max(0, Math.min(999, Number($("bs-listen-passes").value) || 0));
    if ($("bs-listen-ask-passes")) S.listenAskPasses = !!$("bs-listen-ask-passes").checked;
    if ($("bs-holdbusy")) S.holdBusy = $("bs-holdbusy").checked;
    if ($("bs-continuousbm")) S.continuousBmScan = $("bs-continuousbm").checked;
    if ($("bs-record")) S.recordBusy = $("bs-record").checked;
    else if ($("bs-record-list")) S.recordBusy = $("bs-record-list").checked;
    readRecSettings();
  }

  function readRecSettings() {
    if ($("bs-recmode")) {
      var m = String($("bs-recmode").value || "").toLowerCase();
      S.recMode = (m === REC_MODE_AUTO || REC_MODES.indexOf(m) >= 0) ? m : normalizeRecMode(m);
    }
    if ($("bs-rec-custom-gates")) S.recCustomGates = !!$("bs-rec-custom-gates").checked;
    if ($("bs-recsquelch")) S.recSquelchOnly = $("bs-recsquelch").checked;
    if ($("bs-recminsnr")) S.recMinSnrDb = Math.max(0, Number($("bs-recminsnr").value) || 0);
    if ($("bs-recheadroom")) S.recSquelchHeadroomDb = Math.max(0, Number($("bs-recheadroom").value) || 0);
    if ($("bs-recminratio")) S.recMinClipRatioPct = Math.max(0, Math.min(95, Number($("bs-recminratio").value) || 0));
    if ($("bs-recdebounce")) S.recDebounceMs = Math.max(0, Number($("bs-recdebounce").value) || 0);
    if ($("bs-recquiet")) S.recQuietMs = Math.max(0, Number($("bs-recquiet").value) || 0);
  }

  async function listenBookmarks(items, passNum, loopMode, maxPasses) {
    passNum = passNum || 0;
    loopMode = !!loopMode;
    if (maxPasses == null) maxPasses = listenScanMaxPasses;
    var passLab = listenPassLabel(passNum, maxPasses);
    try {
    if (!items || !items.length) {
      setStatus(passLab + "Nothing to listen to yet.");
      return 0;
    }
    if (courtesyBlocked("listening / retuning")) return 0;
    readListenSettings();
    items = sortListenItemsExtra(items.filter(function (row) {
      var it = row.hit || row;
      var f = it.freq || it.frequency;
      if (shouldSkipTune(f)) return false;
      if (S.skipDigitalBm && bookmarkIsDigital(row)) return false;
      if (extraOn("bmScannableOnly") && S.bmScannableOnly && it.scannable === false) return false;
      return true;
    }));
    if (!items.length) {
      setStatus(passLab + "Nothing left to scan (skipped, blocked, or digital).");
      return 0;
    }
    if (window.fs_scanner_state && fs_scanner_state.running && typeof fs_stop_scanner === "function") {
      try { fs_stop_scanner(); } catch (e) {}
    }
    if (window.UI && typeof UI.toggleScanner === "function") {
      try { UI.toggleScanner(false); } catch (e2) {}
    }
    if (extraOn("muteWhileScan")) muteOn();
    else muteOff();
    listenCmd = "";
    setListenPaused(false);
    var heard = 0;
    setListenProgress(0, items.length, passNum || 1, maxPasses);
    for (var i = 0; i < items.length && !stopFlag; i++) {
      if (listenCmd === "prev") {
        listenCmd = "";
        if (i > 0) i = Math.max(-1, i - 2);
        continue;
      }
      var it = items[i].hit || items[i];
      var freq = it.freq || it.frequency;
      var pid = it.pid;
      var name = it.name || existingName(freq) || icao833(freq) || fmtMhz(freq);
      listenFreq = freq;
      if (shouldSkipTune(freq)) continue;
      setListenProgress(i, items.length, passNum || 1, maxPasses);
      var value = profileValueForPid(pid);
      var prof = profileForFreq(freq);
      if (!prof && value) prof = profileByValue(value);
      if (!prof && value) prof = { id: pid || value, value: value, label: pid || value };
      if (consumeListenAbort(freq, name)) continue;
      if (prof) {
        if (!(await tuneToCenter(freq, prof, passLab + "Listen " + (i + 1) + "/" + items.length + " · " + name))) {
          if (stopFlag) break;
          continue;
        }
      } else {
        pluginSetFrequency(freq);
        var settled = Date.now() + getHopSettleMs();
        var abortHop = false;
        while (Date.now() < settled && !stopFlag) {
          if (consumeListenAbort(freq, name)) { abortHop = true; break; }
          await sleep(Math.min(LISTEN_SAMPLE_MS, Math.max(50, settled - Date.now())));
        }
        if (abortHop || stopFlag) continue;
      }
      if (consumeListenAbort(freq, name)) continue;
      if (it.mode && window.UI && typeof UI.setModulation === "function") {
        try { UI.setModulation(it.mode, ""); } catch (e3) {}
      }
      setStatus(passLab + "Listen " + (i + 1) + "/" + items.length + " · " + name + " · " + fmtMhz(freq) + "  [Hold / Skip / Always skip / Stop]");
      setListenProgress(i + 1, items.length, passNum || 1, maxPasses);
      var holdBusy = loopMode ? false : (S.holdBusy !== false);
      var listenMs = Math.max(1000, (Number(S.listenSec) || 4) * 1000);
      var listenStart = Date.now();
      var minUntil = listenStart + listenMs;
      var busySeen = listenCmd === "hold";
      var recOn = false;
      var recPaused = false;
      var recStartedAt = 0;
      var recActiveMs = 0;
      var signalSince = 0;
      var recQuietSince = 0;
      var lastSampleAt = Date.now();
      var modeStr = it.mode || guessMode(pid);
      smeterTrack = [];
      var recGate = recGateParams({ freq: freq, pid: pid, mode: modeStr });
      var quietSince = 0;
      var floor = noiseFloor(wf());
      var busyThr = listenBusyThreshold(floor);
      while (!stopFlag) {
        if (consumeListenAbort(freq, name)) break;
        floor = noiseFloor(wf());
        busyThr = listenBusyThreshold(floor);
        var lvl = levelAt(freq);
        var isBusy = lvl >= busyThr || listenCmd === "hold";
        var recordable = shouldStartRecording(freq, pid, modeStr, isBusy, recGate);
        var recordingActive = listenActivityBusy(recGate, isBusy, recordable);
        var now = Date.now();
        var dt = Math.min(LISTEN_SAMPLE_MS, Math.max(20, now - lastSampleAt));
        lastSampleAt = now;
        if (isBusy) {
          busySeen = true;
          quietSince = 0;
        } else if (busySeen && holdBusy) {
          if (!quietSince) quietSince = now;
        }
        if (recordingActive) {
          if (!signalSince) signalSince = now;
          recQuietSince = 0;
        } else if (recOn) {
          if (!recQuietSince) recQuietSince = now;
        } else {
          signalSince = 0;
        }
        if (S.recordBusy) {
          var debounceMs = recGate.debounceMs;
          if (!recOn && recordingActive && signalSince && (debounceMs <= 0 || (now - signalSince >= debounceMs))) {
            setRecording(true, {
              freq: freq,
              name: name,
              pid: pid,
              mode: currentDemodMode(),
              source: "busy",
              activeMs: 0
            });
            recOn = true;
            recPaused = false;
            recStartedAt = now;
            recActiveMs = 0;
          } else if (recOn) {
            if (recordingActive) {
              if (recPaused) {
                resumeBusyCapture();
                recPaused = false;
              }
              if (recCap.rec && recCap.rec.state === "recording") recActiveMs += dt;
            } else if (recGate.pauseOnQuiet && recQuietSince && (now - recQuietSince >= recGate.quietMs)) {
              pauseBusyCapture();
              recPaused = true;
            } else if (!recGate.pauseOnQuiet && recCap.rec && recCap.rec.state === "recording") {
              recActiveMs += dt;
            }
            if (recCap.meta) recCap.meta.activeMs = recActiveMs;
          }
        }
        var canLeave = false;
        if (listenCmd === "hold") {
          canLeave = false;
        } else if (loopMode) {
          canLeave = now >= minUntil;
        } else if (!holdBusy) {
          canLeave = now >= minUntil;
        } else if (!busySeen) {
          canLeave = now >= minUntil;
        } else {
          canLeave = now >= minUntil && quietSince && (now - quietSince >= QUIET_HOLD_MS);
        }
        if (busySeen && !loopMode) {
          setListenPaused(true);
          var busyExtra = listenCmd === "hold" ? " · HOLD" : listenActivityLabel(recGate, isBusy, recordable);
          setStatus(passLab + "ACTIVE · " + (i + 1) + "/" + items.length + " · " + name + " · " + Math.round(lvl) + " dB" + busyExtra + " — Continue scan bookmarks");
        } else if (busySeen) {
          var busyExtraLoop = listenCmd === "hold" ? " · HOLD" : listenActivityLabel(recGate, isBusy, recordable);
          setStatus(passLab + "ACTIVE · " + (i + 1) + "/" + items.length + " · " + name + " · " + Math.round(lvl) + " dB" + busyExtraLoop);
        } else {
          if (!loopMode) setListenPaused(false);
          setStatus(passLab + "Listen " + (i + 1) + "/" + items.length + " · " + name + " · " + Math.round(lvl) + " dB · listening");
        }
        if (extraOn("recCaps") && recOn && recStartedAt &&
            (now - recStartedAt) >= Math.max(5000, (Number(S.maxClipSec) || 60) * 1000)) {
          canLeave = true;
        }
        if (canLeave) break;
        await sleep(LISTEN_SAMPLE_MS);
      }
      if (!loopMode) setListenPaused(false);
      if (busySeen) heard++;
      if (extraOn("sessionLog")) {
        pushSessionLog({
          at: Date.now(),
          freq: freq,
          name: name,
          busy: !!busySeen,
          clip: !!recOn,
          db: typeof lvl === "number" ? lvl : null
        });
      }
      if (recOn) {
        var recLeft = MIN_RECORD_MS - (Date.now() - recStartedAt);
        if (recLeft > 0) await sleep(recLeft);
        if (recCap.meta) {
          recCap.meta.activeMs = recActiveMs;
          recCap.meta.durationMs = Date.now() - recStartedAt;
        }
        setRecording(false);
      }
      if (listenCmd === "prev") {
        listenCmd = "";
        if (i > 0) i = Math.max(-1, i - 2);
      }
    }
      listenCmd = "";
      listenFreq = 0;
      if (!loopMode) setListenPaused(false);
      setRecording(false);
    if ($("bs-hold")) $("bs-hold").classList.remove("bs-on");
    if (loopMode) return heard;
    if (stopFlag) setStatus(passLab + "Listen stopped after " + heard + " busy bookmarks.");
    else setStatus(passLab + "Listen done. " + heard + " busy / " + items.length + " bookmarks.");
    return heard;
    } catch (err) {
      listenFreq = 0;
      setRecording(false);
      setListenPaused(false);
      setStatus(friendlyError(err, "Listen"));
      toast(friendlyError(err, "Listen"));
      renderHealth();
      return 0;
    }
  }

  async function runListenScanLoop() {
    var pass = 0;
    var totalHeard = 0;
    var maxPasses = Math.max(0, Math.min(999, Number(S.listenPasses) || 0));
    listenScanMaxPasses = maxPasses;
    listenScanPass = 0;
    setProgress(0);
    try {
      while (!stopFlag) {
        var list = scanTargetItems(pass > 0);
        if (!list.length) {
          setStatus((pass ? (listenPassLabel(pass, maxPasses)) : "") +
            "No bookmarks to scan — retrying in 3s… (Stop to exit)");
          var waitUntil = Date.now() + 3000;
          while (Date.now() < waitUntil && !stopFlag) await sleep(200);
          continue;
        }
        pass++;
        listenScanPass = pass;
        setListenScanRunning(true);
        setListenProgress(0, list.length, pass, maxPasses);
        if (pass === 1) {
          setStatus(maxPasses > 0
            ? ("Scan bookmarks — " + list.length + " target(s) · pass 1/" + maxPasses)
            : ("Scan bookmarks — looping " + list.length + " target(s) until Stop · pass 1"));
        }
        var heard = await listenBookmarks(list, pass, continuousBmScanOn(), maxPasses);
        totalHeard += heard || 0;
        if (stopFlag) break;
        if (maxPasses > 0 && pass >= maxPasses) {
          setProgress(1);
          setStatus("Bookmark scan finished · pass " + pass + "/" + maxPasses + " · " + totalHeard + " busy total.");
          break;
        }
        setStatus(listenPassLabel(pass, maxPasses) + "done · " + (heard || 0) + " busy — restarting bookmark scan…");
        await sleep(600);
      }
      listenCmd = "";
      listenFreq = 0;
      setListenScanRunning(false);
      setListenPaused(false);
      setRecording(false);
      if ($("bs-hold")) $("bs-hold").classList.remove("bs-on");
      if (stopFlag) {
        setStatus("Bookmark scan stopped · " +
          (maxPasses > 0 ? ("pass " + pass + "/" + maxPasses) : (pass + " pass(es)")) +
          " · " + totalHeard + " busy total.");
      } else if (maxPasses > 0 && pass >= maxPasses) {
        /* status already set above */
      } else if (!stopFlag) {
        setProgress(0);
      }

      if (!stopFlag && listenBmPeaksMovedHint.wasBookmarksEmpty && S.autoBm) {
        var created = autoBookmarkQualified();
        var added = (created || []).filter(function (r) { return !r.already; }).length;
        if (added > 0) {
          try {
            var elHint = $("bs-peaks-bm-moved-hint");
            if (elHint) {
              elHint.textContent = "Bookmark scan moved " + added + " qualified peak(s) into Bookmarks (only because Bookmarks were empty).";
              elHint.hidden = false;
            }
          } catch (eHint) {}
          try { refreshBookmarks(); } catch (eRef) { updateTabLabels(); }
          setStatus("Moved " + added + " qualified peak(s) into Bookmarks.");
        } else {
          try {
            var elHint2 = $("bs-peaks-bm-moved-hint");
            if (elHint2) elHint2.hidden = true;
          } catch (eHint2) {}
        }
      }
      listenBmPeaksMovedHint.wasBookmarksEmpty = false;
    } catch (err) {
      listenFreq = 0;
      setRecording(false);
      setListenScanRunning(false);
      setListenPaused(false);
      setProgress(0);
      setStatus(friendlyError(err, "Listen"));
      toast(friendlyError(err, "Listen"));
      renderHealth();
    }
  }

  function clearAutoBookmarks() {
    if (typeof BookmarkLocalStorage !== "function") {
      setStatus("No local bookmark store on this page. Nothing to clear. See Help.");
      return 0;
    }
    backupLocalBookmarks("before-clear-auto");
    var store = (window.bookmarks && bookmarks.localBookmarks) || new BookmarkLocalStorage();
    var list = store.getBookmarks() || [];
    var keep = list.filter(function (b) { return !isAuto(b); });
    var n = list.length - keep.length;
    store.setBookmarks(keep);
    if (window.bookmarks && typeof bookmarks.loadLocalBookmarks === "function") {
      bookmarks.loadLocalBookmarks();
    }
    try { refreshBookmarks(); } catch (eRef) { updateTabLabels(); }
    return n;
  }

  function hookHide() {
    if (!window.BookmarkBar || BookmarkBar.prototype._bs_hide_hooked) return;
    BookmarkBar.prototype._bs_hide_hooked = true;
    var orig = BookmarkBar.prototype.render;
    BookmarkBar.prototype.render = function () {
      if (!S.hideAuto || !this.bookmarks) {
        return orig.call(this);
      }
      var saved = {};
      var src;
      for (src in this.bookmarks) {
        if (!Object.prototype.hasOwnProperty.call(this.bookmarks, src)) continue;
        saved[src] = this.bookmarks[src];
        this.bookmarks[src] = (this.bookmarks[src] || []).filter(function (b) {
          return !isAuto(b);
        });
      }
      orig.call(this);
      for (src in saved) {
        if (!Object.prototype.hasOwnProperty.call(saved, src)) continue;
        this.bookmarks[src] = saved[src];
      }
    };
  }

  function refreshBookmarks() {
    if (window.bookmarks && typeof bookmarks.render === "function") {
      bookmarks.render();
    } else if (window.bookmarks && typeof bookmarks.loadLocalBookmarks === "function") {
      bookmarks.loadLocalBookmarks();
    }
    renderBookmarkPane();
  }

  function clamp(n, lo, hi) {
    return Math.max(lo, Math.min(hi, n));
  }

