    text = String(text || "").trim();
    if (!text) return "";
    if (S.btnColoursOff || S.btnShadeHoverHint === false) return text;
    if (/right-click.*colou?r/i.test(text)) return text;
    var btn = null;
    if (host && host.closest) btn = host.closest("button");
    if (!btn && root && root.closest) btn = root.tagName === "BUTTON" ? root : root.closest("button");
    if (!btn || isMainTabBtn(btn) || !btnRoleFromEl(btn)) return text;
    return text + "\n" + BTN_SHADE_HOVER_HINT;
