  function jumpLoudest() {
    if (!requirePublicFeature("exploreTune", "Jump loudest")) return;
    try {
    hookWaterfall();
    if (jumpLoudestUnsupported()) {
      jumpSetStatus("Jump loudest is not supported on FM broadcast (wideband). Use narrow bands — airband, marine, NFM, SSB — or tune manually.");
      try { toast("Jump loudest · not on FM broadcast"); } catch (eT) {}
      return;
    }
    if (exCtl && exCtl.lockTune) {
      jumpSetStatus("Tune is locked — turn off Lock tune (Explore → VFO), then try Jump loudest.");
      try { toast("Tune locked — unlock first."); } catch (eT) {}
      return;
    }
    var pid = jumpCurrentPid();
    var data = wf();
    if (!data || !data.length) {
      jumpSetStatus("No waterfall data yet — wait a moment after connect, then try Jump loudest again.");
      renderHealth();
      return;
    }
    if (!window.UI || typeof UI.setFrequency !== "function") {
      jumpSetStatus("Tune API is missing (UI.setFrequency). Update OpenWebRX+ or open the full receiver UI.");
      renderHealth();
      return;
    }

    var def = applyJumpBandDefaults(false);
    var peaks = jumpGatherPeaks(pid, data);
    var center = Number(window.center_freq) || 0;
    var bw = Number(window.bandwidth) || 0;
    peaks.sort(function (a, b) {
      return (Number(b.db) || 0) - (Number(a.db) || 0);
    });

    if (!peaks.length) {
      var blocked = blockingIssue();
      jumpSetStatus(blocked
        ? blocked.title + " — " + blocked.fix
        : "No peak on this tile — wait for waterfall data, or lower " +
          (extraOn("jumpTuning") ? "Jump dB" : "Min dB (Bands/Range scan options)") + ".");
      renderHealth();
      return;
    }

    var curTune = 0;
    try { curTune = Math.round(Number(currentTuneHz()) || 0); } catch (eCur) { curTune = 0; }
    if (!(curTune > 0)) curTune = Math.round(center);
    if (def.key === "fm_bc" && curTune > 0) {
      curTune = fmJumpCurGridHz(curTune, pid);
    }

    var pick = (def.key === "fm_bc")
      ? jumpPickLoudestPeak(peaks, curTune, def)
      : jumpPickCyclePeak(peaks, curTune, pid);
    if (!pick || !pick.peak) {
      jumpSetStatus(peaks.length === 1
        ? "Only one station on this waterfall tile — nothing else to hop to."
        : "Already on the loudest station — press again for the next one, or lower Jump dB.");
      renderHealth();
      return;
    }
    var p = pick.peak;

    var tuneHz = jumpPeakTuneHz(p, def);
    jumpApplyTuneVisible(tuneHz);
    var bandNote = def && def.label ? (" · " + def.label) : "";
    var centerNote = jumpApplyTuneVisible._lastRecenter ? " · centered"
      : (jumpCenterScreenEnabled() ? " · on tile" : " · dial only");
    var rankNote = pick.total > 1 ? (" · " + pick.rank + "/" + pick.total + " by signal") : "";
    jumpSetStatus("Jumped to " + (icao833(tuneHz) || fmtMhz(tuneHz)) + " (" + Math.round(p.db) + " dB)" +
      rankNote + bandNote + centerNote + " — press again for next station on this tile.");
    } catch (err) {
      jumpSetStatus(friendlyError(err, "Jump loudest"));
      toast(friendlyError(err, "Jump loudest"));
      renderHealth();
    }
  }

