  function startListenScan() {
    var jobGen = claimRadioJob("bookmarks");
    if (jobGen == null) return;
    function abortBmJob() { releaseRadioJob("bookmarks", jobGen); }
    if (running && radioJob !== "bookmarks") { abortBmJob(); return; }
    if (!publicAllowsFeature("scanBookmarks")) {
      abortBmJob();
      setStatus("Scan bookmarks is not allowed for visitors on this public receiver.");
      return;
    }
    try { ensurePreferredSdrForJob("listen"); } catch (ePrefL) {}
    readListenSettings();
    try {
      var elHint = $("bs-peaks-bm-moved-hint");
      if (elHint) elHint.hidden = true;
    } catch (eHint) {}
    // If Bookmarks were empty, Scan bookmarks falls back to Peaks as scan targets.
    // After scan completion we can (optionally) convert those Peaks into Bookmarks.
    try {
      var localCnt = (localBookmarkList && localBookmarkList()) ? localBookmarkList().length : 0;
      var loadedCnt = (loadedBookmarks || []).length;
      listenBmPeaksMovedHint.wasBookmarksEmpty = (!localCnt && !loadedCnt && !lastCreated.length);
    } catch (eEmpty) {
      listenBmPeaksMovedHint.wasBookmarksEmpty = false;
    }
    if (extraOn("askPasses") && S.listenAskPasses) {
      var def = String(Math.max(0, Number(S.listenPasses) || 0));
      var ans = window.prompt(
        "How many times to scan bookmarks?\n0 = keep going until you press Stop.",
        def
      );
      if (ans === null) {
        abortBmJob();
        setStatus("Scan bookmarks cancelled.");
        return;
      }
      var n = parseInt(String(ans).trim(), 10);
      if (!isFinite(n) || n < 0) n = 0;
      S.listenPasses = Math.max(0, Math.min(999, n));
      if ($("bs-listen-passes")) $("bs-listen-passes").value = String(S.listenPasses);
    }
    saveSettings();
    if (!scanTargetItems().length && !scanTargetItems(true).length) {
      abortBmJob();
      setStatus("No bookmarks or qualified peaks to scan.");
      return;
    }
    stopFlag = false;
    running = true;
    setProgress(0);
    setListenScanRunning(true);
    var btn = $("bs-toggle-btn");
    if (btn) btn.classList.add("bs-running");
    runListenScanLoop().then(function () {
      if (jobGen === radioJobGen) {
        running = false;
        setListenScanRunning(false);
        if (btn) btn.classList.remove("bs-running");
        releaseRadioJob("bookmarks", jobGen);
      }
      renderHits();
    }).catch(function (err) {
      if (jobGen === radioJobGen) {
        running = false;
        setListenScanRunning(false);
        if (btn) btn.classList.remove("bs-running");
        releaseRadioJob("bookmarks", jobGen);
      }
      setStatus(friendlyError(err, "Listen"));
    });
  }

