  var NCDXF_CALLS = [
    "4U1UN", "VE8AT", "W6WX", "KH6RS", "ZL6B", "VK6RBP",
    "JA2IGY", "RR9O", "VR2B", "4S7B", "ZS6DN", "5Z4B",
    "4X6TU", "OH2B", "CS3B", "LU4AA", "OA4B", "YV5B"
  ];
  var NCDXF_BANDS = [
    { key: "20", label: "20 m", hz: 14100000, slot: 0 },
    { key: "17", label: "17 m", hz: 18110000, slot: 1 },
    { key: "15", label: "15 m", hz: 21150000, slot: 2 },
    { key: "12", label: "12 m", hz: 24930000, slot: 3 },
    { key: "10", label: "10 m", hz: 28200000, slot: 4 }
  ];

  /** Who is on each NCDXF band at this UTC instant. slot 0=20 m … 4=10 m. */
  function ncdxfLive(nowMs) {
    var d = new Date(nowMs || Date.now());
    var t = ((d.getUTCMinutes() % 3) * 60) + d.getUTCSeconds() + (d.getUTCMilliseconds() / 1000);
    return NCDXF_BANDS.map(function (b) {
      var ago = (t - b.slot * 10 + 1800) % 180;
      var index = Math.floor(ago / 10) % NCDXF_CALLS.length;
      var into = ago % 10;
      return {
        key: b.key,
        label: b.label,
        hz: b.hz,
        index: index,
        call: NCDXF_CALLS[index],
        left: Math.max(1, Math.ceil(10 - into))
      };
    });
  }

  /** Narrowest profile whose centre and sample rate actually cover hz. */
  function beaconProfileForHz(hz) {
    var list = [];
    try { list = profiles(); } catch (e) { list = []; }
    var best = null;
    var bestSpan = Infinity;
    var i, p, det, cf, sr, r;
    for (i = 0; i < list.length; i++) {
      p = list[i];
      if (!p || !p.value) continue;
      det = {};
      try { det = lookupProfileDetail(p) || {}; } catch (eDet) { det = {}; }
      cf = Number(det.center_freq);
      sr = Number(det.sample_rate);
      if (!(cf > 0) || !(sr > 0)) {
        try { r = profileMhzRange(p); } catch (eR) { r = null; }
        if (!r) continue;
        cf = ((Number(r.lo) + Number(r.hi)) / 2) * 1e6;
        sr = Math.abs(Number(r.hi) - Number(r.lo)) * 1e6;
      }
      if (!(cf > 0) || !(sr > 1000)) continue;
      if (Math.abs(hz - cf) > sr / 2 + 4000) continue;
      if (sr < bestSpan) {
        bestSpan = sr;
        best = p;
      }
    }
    return best;
  }

  function beaconOpenBand(hz) {
    hz = Math.round(Number(hz) || 0);
    if (!(hz > 0)) return;
    var band = null;
    NCDXF_BANDS.forEach(function (b) { if (b.hz === hz) band = b; });
    var label = band ? band.label : fmtMhz(hz);
    var p = null;
    try { p = beaconProfileForHz(hz); } catch (eP) { p = null; }
    setStatus("Opening " + label + " beacon…");
    function tune() {
      try { pluginSetFrequency(hz); } catch (eF) {}
      try {
        if (typeof exploreSetMode === "function") exploreSetMode("cw");
        else if (window.UI && typeof UI.setModulation === "function") UI.setModulation("cw", "");
      } catch (eM) {}
      setStatus("Beacon " + label + " · " + fmtMhz(hz) + " CW");
    }
    if (p && p.value && typeof switchProfile === "function") {
      try {
        switchProfile(p.value).then(tune).catch(tune);
        return;
      } catch (eSw) {}
    }
    tune();
  }

  function beaconRenderInto(hostId) {
    var host = $(hostId);
    if (!host) return;
    var live = ncdxfLive(Date.now());
    var sig = live.map(function (b) { return b.index; }).join(",");
    if (host.getAttribute("data-sig") !== sig || !host.querySelector(".bs-beacon-band")) {
      host.setAttribute("data-sig", sig);
      host.innerHTML = live.map(function (b) {
        var slots = NCDXF_CALLS.map(function (call, i) {
          var on = i === b.index;
          return '<button type="button" class="bs-beacon-slot' + (on ? " bs-on" : "") +
            '" data-beacon-hz="' + b.hz + '" data-beacon-i="' + i + '"' +
            ' title="' + (on ? "On now — click to open this band" : call) + '">' +
            call + "</button>";
        }).join("");
        return '<div class="bs-beacon-band">' +
          '<div class="bs-beacon-h">' +
          '<button type="button" class="bs-beacon-open" data-beacon-hz="' + b.hz +
          '" title="Open ' + b.label + ' on the beacon frequency, CW.">' +
          b.label + " · " + fmtMhz(b.hz) + "</button>" +
          '<span class="bs-beacon-now" data-beacon-now="' + b.key + '">' +
          b.call + " · " + b.left + "s</span></div>" +
          '<div class="bs-beacon-cycle">' + slots + "</div></div>";
      }).join("");
    } else {
      live.forEach(function (b) {
        var nowEl = host.querySelector('[data-beacon-now="' + b.key + '"]');
        if (nowEl) nowEl.textContent = b.call + " · " + b.left + "s";
      });
    }
    if (!host._bs_beacon_bound) {
      host._bs_beacon_bound = true;
      host.addEventListener("click", function (ev) {
        var btn = ev.target && ev.target.closest && ev.target.closest("[data-beacon-hz]");
        if (!btn || !host.contains(btn)) return;
        if (btn.classList.contains("bs-beacon-slot") && !btn.classList.contains("bs-on")) return;
        beaconOpenBand(btn.getAttribute("data-beacon-hz"));
      });
    }
  }

  function bandsBeaconRender() { beaconRenderInto("bs-beacon-host"); }
  function moreBeaconRender() { beaconRenderInto("bs-more-beacon-host"); }

  function activityBandName(hz) {
    hz = Number(hz) || 0;
    if (!(hz > 0)) return "";
    var mhz = hz / 1e6;
    var bands = [
      [0.472, 0.479, "630 m"],
      [1.8, 2.0, "160 m"],
      [3.5, 4.0, "80 m"],
      [5.25, 5.45, "60 m"],
      [7.0, 7.3, "40 m"],
      [10.1, 10.15, "30 m"],
      [14.0, 14.35, "20 m"],
      [18.068, 18.168, "17 m"],
      [21.0, 21.45, "15 m"],
      [24.89, 24.99, "12 m"],
      [28.0, 29.7, "10 m"],
      [50.0, 54.0, "6 m"],
      [70.0, 70.5, "4 m"],
      [87.5, 108.0, "FM broadcast"],
      [108.0, 137.0, "Airband"],
      [144.0, 148.0, "2 m"],
      [156.0, 162.05, "Marine"],
      [430.0, 440.0, "70 cm"],
      [1240.0, 1300.0, "23 cm"]
    ];
    var i;
    for (i = 0; i < bands.length; i++) {
      if (mhz >= bands[i][0] && mhz <= bands[i][1]) return bands[i][2];
    }
    if (mhz < 30) return "HF other";
    return "Other";
  }

  function bandsTodayRender() { todayRenderInto("bs-today-host", "bs-today-hint"); }
  function moreTodayRender() { todayRenderInto("bs-more-today-host", "bs-more-today-hint"); }

  function todayRenderInto(hostId, hintId) {
    var host = $(hostId);
    if (!host) return;
    var start = new Date();
    start.setHours(0, 0, 0, 0);
    var from = start.getTime();
    var buckets = {};
    function add(hz, kind) {
      var name = activityBandName(hz) || "No frequency";
      if (!buckets[name]) buckets[name] = { name: name, log: 0, watch: 0 };
      buckets[name][kind] += 1;
    }
    var rows = (typeof trafficLogRows !== "undefined" && trafficLogRows) ? trafficLogRows : [];
    var hits = (typeof sigWatchHits !== "undefined" && sigWatchHits) ? sigWatchHits : [];
    rows.forEach(function (r) {
      if (!r || !(r.at >= from)) return;
      add(r.freqHz, "log");
    });
    hits.forEach(function (h) {
      if (!h || !(h.at >= from)) return;
      add(h.freqHz, "watch");
    });
    var list = Object.keys(buckets).map(function (k) { return buckets[k]; });
    list.sort(function (a, b) {
      var d = (b.log + b.watch) - (a.log + a.watch);
      if (d) return d;
      return a.name < b.name ? -1 : 1;
    });
    var sig = from + "|" + list.map(function (b) {
      return b.name + ":" + b.log + ":" + b.watch;
    }).join(",");
    if (host.getAttribute("data-sig") === sig) return;
    host.setAttribute("data-sig", sig);
    var hint = hintId ? $(hintId) : null;
    if (hint) {
      hint.textContent = "Since local midnight (" +
        start.toLocaleDateString(undefined, { weekday: "short", day: "numeric", month: "short" }) + ").";
    }
    if (!list.length) {
      host.innerHTML = '<p class="bs-empty">Nothing in the log or watch for today yet.</p>';
      return;
    }
    host.innerHTML = '<table class="bs-today"><thead><tr>' +
      "<th>Band</th><th>Log</th><th>Watch</th></tr></thead><tbody>" +
      list.map(function (b) {
        return "<tr><td>" + escapeHtml(b.name) + "</td><td>" + b.log + "</td><td>" + b.watch + "</td></tr>";
      }).join("") +
      "</tbody></table>";
  }

