  function panelTabHtml_more() {
    var groupBtns = MORE_GROUPS.map(function (g, gi) {
      return '<button type="button" class="bs-more-group' + (gi === 0 ? " bs-more-group-on" : "") +
        '" data-more-group="' + g.id + '" role="tab" aria-selected="' + (gi === 0 ? "true" : "false") +
        '" title="' + escapeHtml(g.title || g.lab) + '">' + escapeHtml(g.lab) + "</button>";
    }).join("");
    var groupPanes = MORE_GROUPS.map(function (g, gi) {
      var inners = (g.panes || []).map(function (p, pi) {
        return '<button type="button" class="bs-more-sub' + (gi === 0 && pi === 0 ? " bs-more-sub-on" : "") +
          '" data-more-sub="' + p.id + '" role="tab" aria-selected="' + (gi === 0 && pi === 0 ? "true" : "false") +
          '" title="' + escapeHtml(p.title || p.lab) + '">' + escapeHtml(p.lab) + "</button>";
      }).join("");
      var panes = (g.panes || []).map(function (p, pi) {
        return '<div class="bs-more-subpane' + (gi === 0 && pi === 0 ? " bs-more-sub-on" : "") +
          '" id="bs-more-' + p.id + '" data-more-sub="' + p.id + '" role="tabpanel"' +
          (gi === 0 && pi === 0 ? "" : " hidden") + ">" +
          morePaneInnerHtml(p.id) +
          "</div>";
      }).join("");
      return '<div class="bs-more-grouppane' + (gi === 0 ? " bs-more-group-on" : "") +
        '" data-more-group="' + g.id + '" role="tabpanel"' + (gi === 0 ? "" : " hidden") + ">" +
        '<div class="bs-more-inners" role="tablist" aria-label="' + escapeHtml(g.lab) + ' sections">' +
        inners + "</div>" + panes + "</div>";
    }).join("");
    return (
      '<div class="bs-tab-pane" id="bs-tab-more" data-tab="more" role="tabpanel">' +
      '<div class="bs-tab-stack bs-more-stack">' +
      '<div class="bs-more-subs" id="bs-more-subs" role="tablist" aria-label="More groups">' +
      groupBtns +
      "</div>" +
      groupPanes +
      "</div></div>"
    );
  }

