  var dxSpots = [];
  var dxScope = "all";
  var dxFetchedAt = 0;
  var dxError = "";
  var DX_SPOT_URL = "https://dxc.jo30.de/dxcache/spots";
  var DX_MAX_AGE_MS = 30 * 60 * 1000;

  function dxHz(freq) {
    freq = Number(freq);
    if (!(freq > 0)) return 0;
    if (freq < 1000) return Math.round(freq * 1e6);
    if (freq < 2e6) return Math.round(freq * 1e3);
    return Math.round(freq);
  }

  function dxBandKey(s) {
    return String(s || "").toLowerCase().replace(/\s+/g, "");
  }

  function dxSpotWhen(spot) {
    var t = Date.parse(spot && spot.when);
    return t > 0 ? t : 0;
  }

  function dxSpotMode(spot) {
    var s = String((spot && (spot.submode || spot.mode)) || "").toLowerCase();
    if (s === "usb" || s === "lsb" || s === "cw" || s === "am" || s === "fm" || s === "nfm") return s;
    if (s === "ssb") return "usb";
    return "";
  }

  function dxVisibleSpots() {
    var now = Date.now();
    var band = "";
    try { band = dxBandKey(activityBandName(currentTuneHz())); } catch (eB) {}
    return dxSpots.filter(function (spot) {
      if (!spot) return false;
      var at = dxSpotWhen(spot);
      if (!at || now - at > DX_MAX_AGE_MS) return false;
      var hz = dxHz(spot.frequency);
      if (!(hz > 0)) return false;
      if (dxScope === "hf") return hz < 30e6;
      if (dxScope === "band") {
        if (!band) return true;
        return dxBandKey(spot.band) === band || dxBandKey(activityBandName(hz)) === band;
      }
      return true;
    }).sort(function (a, b) { return dxSpotWhen(b) - dxSpotWhen(a); }).slice(0, 80);
  }

  function dxRender() {
    var host = $("bs-dx-list");
    if (!host) return;
    var meta = $("bs-dx-meta");
    Array.prototype.forEach.call(document.querySelectorAll("#bs-dx-scopes [data-dx-scope]"), function (btn) {
      btn.classList.toggle("bs-on", btn.getAttribute("data-dx-scope") === dxScope);
    });
    var rows = dxVisibleSpots();
    var age = dxFetchedAt ? trafficLogAgo(dxFetchedAt) : "";
    if (meta) {
      meta.textContent = dxError
        ? dxError
        : (dxFetchedAt ? (rows.length + " spot" + (rows.length === 1 ? "" : "s") + " · updated " + age) : "Loading spots…");
    }
    if (!dxFetchedAt && !dxError) {
      host.innerHTML = '<p class="bs-empty">Loading spots…</p>';
      return;
    }
    if (!rows.length) {
      host.innerHTML = '<p class="bs-empty">' + (dxError
        ? "No spots loaded."
        : "No spots in the last 30 minutes for this filter.") + "</p>";
      return;
    }
    host.innerHTML = rows.map(function (spot) {
      var hz = dxHz(spot.frequency);
      var at = dxSpotWhen(spot);
      var fresh = Date.now() - at < 6 * 60 * 1000;
      var mode = String(spot.submode || spot.mode || "");
      var call = String(spot.spotted || "");
      return '<article class="bs-dx-row' + (fresh ? " bs-dx-fresh" : "") + '" data-dx-tune="' + hz + '" data-dx-mode="' + escapeHtml(dxSpotMode(spot)) + '" title="Tune this spot.">' +
        '<span class="bs-dx-when">' + escapeHtml(trafficLogAgo(at)) + "</span>" +
        '<span class="bs-dx-call">' + lookupHtml(call, mode, "FT8") + "</span>" +
        '<span class="bs-dx-mhz">' + escapeHtml(fmtMhz(hz)) + "</span>" +
        '<span class="bs-dx-mode">' + escapeHtml(mode) + "</span>" +
        '<span class="bs-dx-band">' + escapeHtml(spot.band || "") + "</span>" +
        '<span class="bs-dx-msg">' + escapeHtml(String(spot.message || "").replace(/\s+/g, " ").trim().slice(0, 80)) + "</span>" +
        '<span class="bs-dx-by">' + escapeHtml(spot.spotter || "") + "</span>" +
        "</article>";
    }).join("");
  }

  function dxFetch() {
    if (!moreNetworkAllowed("dx")) {
      dxError = "Network budget blocked More fetches.";
      dxRender();
      return Promise.resolve();
    }
    var meta = $("bs-dx-meta");
    if (meta && !dxSpots.length) meta.textContent = "Loading spots…";
    return fetch(DX_SPOT_URL, { cache: "no-store" }).then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.json();
    }).then(function (data) {
      dxSpots = Array.isArray(data) ? data : [];
      dxFetchedAt = Date.now();
      dxError = "";
      dxRender();
    }).catch(function () {
      dxError = "DX cluster did not answer.";
      dxRender();
      setStatus(dxError);
    });
  }

  function dxOnTab() {
    dxRender();
    if (!dxFetchedAt || Date.now() - dxFetchedAt > 60000) dxFetch();
  }

  function dxTune(hz, mode) {
    hz = Math.round(Number(hz) || 0);
    if (!(hz > 0)) return;
    function dial() {
      try { pluginSetFrequency(hz); } catch (eF) {}
      if (mode && window.UI && typeof UI.setModulation === "function") {
        try { UI.setModulation(mode, ""); } catch (eM) {}
      }
      setStatus("DX " + fmtMhz(hz) + (mode ? (" · " + mode.toUpperCase()) : "") + ".");
    }
    var p = null;
    try { p = profileForFreq(hz); } catch (eP) { p = null; }
    if (p && p.value && currentProfileValue() !== p.value && typeof switchProfile === "function") {
      switchProfile(p.value).then(dial).catch(dial);
      return;
    }
    dial();
  }

  function bindDxTab() {
    var root = $("bs-more-dx");
    if (!root || root._bsDxWired) return;
    root._bsDxWired = true;
    root.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      if (t.closest("a.bs-lookup")) return;
      var scope = t.closest("[data-dx-scope]");
      if (scope) {
        dxScope = scope.getAttribute("data-dx-scope") || "all";
        dxRender();
        return;
      }
      var row = t.closest("[data-dx-tune]");
      if (row) dxTune(row.getAttribute("data-dx-tune"), row.getAttribute("data-dx-mode"));
    });
    if ($("bs-dx-refresh")) $("bs-dx-refresh").onclick = function () { dxFetch(); };
    if (!window._bs_dx_timer) {
      window._bs_dx_timer = setInterval(function () {
        var pane = $("bs-tab-more");
        var sub = $("bs-more-dx");
        if (!pane || !pane.classList.contains("bs-tab-on")) return;
        if (!sub || !sub.classList.contains("bs-more-sub-on")) return;
        if (dxFetchedAt && Date.now() - dxFetchedAt < 150000) return;
        dxFetch();
      }, 60000);
    }
  }

  /* Near-earth SGP4 (Vallado). Deep-space orbits are refused. */
  var satPi = Math.PI;
  var satTwopi = 2 * satPi;
  var satDeg = satPi / 180;

  function satPosmod(a, m) {
    return ((a % m) + m) % m;
  }

  function satWgs72() {
    var mu = 398600.8;
    var radiusearthkm = 6378.135;
    var xke = 60.0 / Math.sqrt(radiusearthkm * radiusearthkm * radiusearthkm / mu);
    var j2 = 0.001082616;
    var j3 = -0.00000253881;
    var j4 = -0.00000165597;
    return {
      mu: mu,
      radiusearthkm: radiusearthkm,
      xke: xke,
      tumin: 1.0 / xke,
      j2: j2,
      j3: j3,
      j4: j4,
      j3oj2: j3 / j2
    };
  }

  function satGstime(jdut1) {
    var tut1 = (jdut1 - 2451545.0) / 36525.0;
    var temp = -6.2e-6 * tut1 * tut1 * tut1 + 0.093104 * tut1 * tut1 +
      (876600.0 * 3600 + 8640184.812866) * tut1 + 67310.54841;
    temp = (temp * satDeg / 240.0) % satTwopi;
    if (temp < 0) temp += satTwopi;
    return temp;
  }

  function satInitl(xke, j2, ecco, epoch, inclo, no) {
    var x2o3 = 2.0 / 3.0;
    var eccsq = ecco * ecco;
    var omeosq = 1.0 - eccsq;
    var rteosq = Math.sqrt(omeosq);
    var cosio = Math.cos(inclo);
    var cosio2 = cosio * cosio;
    var ak = Math.pow(xke / no, x2o3);
    var d1 = 0.75 * j2 * (3.0 * cosio2 - 1.0) / (rteosq * omeosq);
    var del = d1 / (ak * ak);
    var adel = ak * (1.0 - del * del - del * (1.0 / 3.0 + 134.0 * del * del / 81.0));
    del = d1 / (adel * adel);
    no = no / (1.0 + del);
    var ao = Math.pow(xke / no, x2o3);
    var sinio = Math.sin(inclo);
    var po = ao * omeosq;
    var con42 = 1.0 - 5.0 * cosio2;
    var con41 = -con42 - cosio2 - cosio2;
    var posq = po * po;
    var rp = ao * (1.0 - ecco);
    var gsto = satGstime(epoch + 2433281.5);
    return {
      no: no, ao: ao, con41: con41, con42: con42, cosio: cosio, cosio2: cosio2,
      omeosq: omeosq, posq: posq, rp: rp, rteosq: rteosq, sinio: sinio, gsto: gsto
    };
  }

  function satFromTle(line1, line2) {
    var g = satWgs72();
    var xpdotp = 1440.0 / satTwopi;
    var epochdays = parseFloat(line1.substring(20, 32));
    var ndot = parseFloat(line1.substring(33, 43));
    var nddot = parseFloat(line1.substring(44, 45) + "." + line1.substring(45, 50));
    var nexp = parseInt(line1.substring(50, 52), 10);
    var bstar = parseFloat(line1.substring(53, 54) + "." + line1.substring(54, 59));
    var ibexp = parseInt(line1.substring(59, 61), 10);
    var inclo = parseFloat(line2.substring(8, 16)) * satDeg;
    var nodeo = parseFloat(line2.substring(17, 25)) * satDeg;
    var ecco = parseFloat("0." + line2.substring(26, 33).replace(/ /g, "0"));
    var argpo = parseFloat(line2.substring(34, 42)) * satDeg;
    var mo = parseFloat(line2.substring(43, 51)) * satDeg;
    var no = parseFloat(line2.substring(52, 63)) / xpdotp;
    nddot = nddot * Math.pow(10, nexp);
    bstar = bstar * Math.pow(10, ibexp);
    ndot = ndot / (xpdotp * 1440.0);
    nddot = nddot / (xpdotp * 1440.0 * 1440);
    var year = parseInt(line1.substring(18, 20), 10);
    year = year < 57 ? 2000 + year : 1900 + year;
    var jd0 = satDatePartsToJd(year, 1, 1, 0, 0, 0) - 1;
    var jdsatepoch = jd0 + epochdays;
    var epoch = jdsatepoch - 2433281.5;
    var ini = satInitl(g.xke, g.j2, ecco, epoch, inclo, no);
    var sat = {
      xke: g.xke, j2: g.j2, j3: g.j3, j4: g.j4, j3oj2: g.j3oj2,
      radiusearthkm: g.radiusearthkm, tumin: g.tumin,
      bstar: bstar, ndot: ndot, nddot: nddot, ecco: ecco, argpo: argpo,
      inclo: inclo, mo: mo, no_kozai: no, nodeo: nodeo,
      no_unkozai: ini.no, con41: ini.con41, gsto: ini.gsto,
      isimp: 0, method: "n",
      cc1: 0, cc4: 0, cc5: 0, d2: 0, d3: 0, d4: 0, delmo: 0, eta: 0,
      argpdot: 0, omgcof: 0, sinmao: 0, t2cof: 0, t3cof: 0, t4cof: 0, t5cof: 0,
      x1mth2: 0, x7thm1: 0, mdot: 0, nodedot: 0, xlcof: 0, xmcof: 0, nodecf: 0, aycof: 0,
      jdsatepoch: jdsatepoch
    };
    var ss = 78.0 / g.radiusearthkm + 1.0;
    var qzms2ttemp = (120.0 - 78.0) / g.radiusearthkm;
    var qzms2t = qzms2ttemp * qzms2ttemp * qzms2ttemp * qzms2ttemp;
    var x2o3 = 2.0 / 3.0;
    var ao = ini.ao;
    var cosio = ini.cosio;
    var cosio2 = ini.cosio2;
    var omeosq = ini.omeosq;
    var posq = ini.posq;
    var rp = ini.rp;
    var rteosq = ini.rteosq;
    var sinio = ini.sinio;
    var con42 = ini.con42;
    if (rp < 220.0 / g.radiusearthkm + 1.0) sat.isimp = 1;
    var sfour = ss;
    var qzms24 = qzms2t;
    var perige = (rp - 1.0) * g.radiusearthkm;
    if (perige < 156.0) {
      sfour = perige - 78.0;
      if (perige < 98.0) sfour = 20.0;
      var qzms24temp = (120.0 - sfour) / g.radiusearthkm;
      qzms24 = qzms24temp * qzms24temp * qzms24temp * qzms24temp;
      sfour = sfour / g.radiusearthkm + 1.0;
    }
    var pinvsq = 1.0 / posq;
    var tsi = 1.0 / (ao - sfour);
    sat.eta = ao * ecco * tsi;
    var etasq = sat.eta * sat.eta;
    var eeta = ecco * sat.eta;
    var psisq = Math.abs(1.0 - etasq);
    var coef = qzms24 * Math.pow(tsi, 4.0);
    var coef1 = coef / Math.pow(psisq, 3.5);
    var cc2 = coef1 * sat.no_unkozai * (ao * (1.0 + 1.5 * etasq + eeta * (4.0 + etasq)) +
      0.375 * g.j2 * tsi / psisq * sat.con41 * (8.0 + 3.0 * etasq * (8.0 + etasq)));
    sat.cc1 = bstar * cc2;
    var cc3 = 0.0;
    if (ecco > 1.0e-4) cc3 = -2.0 * coef * tsi * g.j3oj2 * sat.no_unkozai * sinio / ecco;
    sat.x1mth2 = 1.0 - cosio2;
    sat.cc4 = 2.0 * sat.no_unkozai * coef1 * ao * omeosq *
      (sat.eta * (2.0 + 0.5 * etasq) + ecco * (0.5 + 2.0 * etasq) - g.j2 * tsi / (ao * psisq) *
        (-3.0 * sat.con41 * (1.0 - 2.0 * eeta + etasq * (1.5 - 0.5 * eeta)) +
          0.75 * sat.x1mth2 * (2.0 * etasq - eeta * (1.0 + etasq)) * Math.cos(2.0 * argpo)));
    sat.cc5 = 2.0 * coef1 * ao * omeosq * (1.0 + 2.75 * (etasq + eeta) + eeta * etasq);
    var cosio4 = cosio2 * cosio2;
    var temp1 = 1.5 * g.j2 * pinvsq * sat.no_unkozai;
    var temp2 = 0.5 * temp1 * g.j2 * pinvsq;
    var temp3 = -0.46875 * g.j4 * pinvsq * pinvsq * sat.no_unkozai;
    sat.mdot = sat.no_unkozai + 0.5 * temp1 * rteosq * sat.con41 +
      0.0625 * temp2 * rteosq * (13.0 - 78.0 * cosio2 + 137.0 * cosio4);
    sat.argpdot = -0.5 * temp1 * con42 + 0.0625 * temp2 * (7.0 - 114.0 * cosio2 + 395.0 * cosio4) +
      temp3 * (3.0 - 36.0 * cosio2 + 49.0 * cosio4);
    var xhdot1 = -temp1 * cosio;
    sat.nodedot = xhdot1 + (0.5 * temp2 * (4.0 - 19.0 * cosio2) + 2.0 * temp3 * (3.0 - 7.0 * cosio2)) * cosio;
    sat.omgcof = bstar * cc3 * Math.cos(argpo);
    sat.xmcof = 0.0;
    if (ecco > 1.0e-4) sat.xmcof = -x2o3 * coef * bstar / eeta;
    sat.nodecf = 3.5 * omeosq * xhdot1 * sat.cc1;
    sat.t2cof = 1.5 * sat.cc1;
    var temp4 = 1.5e-12;
    if (Math.abs(cosio + 1.0) > 1.5e-12) {
      sat.xlcof = -0.25 * g.j3oj2 * sinio * (3.0 + 5.0 * cosio) / (1.0 + cosio);
    } else {
      sat.xlcof = -0.25 * g.j3oj2 * sinio * (3.0 + 5.0 * cosio) / temp4;
    }
    sat.aycof = -0.5 * g.j3oj2 * sinio;
    var delmotemp = 1.0 + sat.eta * Math.cos(mo);
    sat.delmo = delmotemp * delmotemp * delmotemp;
    sat.sinmao = Math.sin(mo);
    sat.x7thm1 = 7.0 * cosio2 - 1.0;
    if (satTwopi / sat.no_unkozai >= 225.0) {
      sat.method = "d";
      sat.deep = true;
    }
    if (sat.isimp !== 1) {
      var cc1sq = sat.cc1 * sat.cc1;
      sat.d2 = 4.0 * ao * tsi * cc1sq;
      var temp = sat.d2 * tsi * sat.cc1 / 3.0;
      sat.d3 = (17.0 * ao + sfour) * temp;
      sat.d4 = 0.5 * temp * ao * tsi * (221.0 * ao + 31.0 * sfour) * sat.cc1;
      sat.t3cof = sat.d2 + 2.0 * cc1sq;
      sat.t4cof = 0.25 * (3.0 * sat.d3 + sat.cc1 * (12.0 * sat.d2 + 10.0 * cc1sq));
      sat.t5cof = 0.2 * (3.0 * sat.d4 + 12.0 * sat.cc1 * sat.d3 + 6.0 * sat.d2 * sat.d2 +
        15.0 * cc1sq * (2.0 * sat.d2 + cc1sq));
    }
    return sat;
  }

  function satSgp4(sat, tsince) {
    if (sat.method === "d") return null;
    var x2o3 = 2.0 / 3.0;
    var vkmpersec = sat.radiusearthkm * sat.xke / 60.0;
    var xmdf = sat.mo + sat.mdot * tsince;
    var argpdf = sat.argpo + sat.argpdot * tsince;
    var nodedf = sat.nodeo + sat.nodedot * tsince;
    var argpm = argpdf;
    var mm = xmdf;
    var t2 = tsince * tsince;
    var nodem = nodedf + sat.nodecf * t2;
    var tempa = 1.0 - sat.cc1 * tsince;
    var tempe = sat.bstar * sat.cc4 * tsince;
    var templ = sat.t2cof * t2;
    if (sat.isimp !== 1) {
      var delomg = sat.omgcof * tsince;
      var delmtemp = 1.0 + sat.eta * Math.cos(xmdf);
      var delm = sat.xmcof * (delmtemp * delmtemp * delmtemp - sat.delmo);
      var temp = delomg + delm;
      mm = xmdf + temp;
      argpm = argpdf - temp;
      var t3 = t2 * tsince;
      var t4 = t3 * tsince;
      tempa = tempa - sat.d2 * t2 - sat.d3 * t3 - sat.d4 * t4;
      tempe = tempe + sat.bstar * sat.cc5 * (Math.sin(mm) - sat.sinmao);
      templ = templ + sat.t3cof * t3 + t4 * (sat.t4cof + tsince * sat.t5cof);
    }
    var nm = sat.no_unkozai;
    var em = sat.ecco;
    var inclm = sat.inclo;
    var am = Math.pow(sat.xke / nm, x2o3) * tempa * tempa;
    nm = sat.xke / Math.pow(am, 1.5);
    em = em - tempe;
    if (em >= 1.0 || em < -0.001) return null;
    if (em < 1.0e-6) em = 1.0e-6;
    mm = mm + sat.no_unkozai * templ;
    var xlm = mm + argpm + nodem;
    nodem = nodem % satTwopi;
    argpm = satPosmod(argpm, satTwopi);
    xlm = satPosmod(xlm, satTwopi);
    mm = satPosmod(xlm - argpm - nodem, satTwopi);
    var sinim = Math.sin(inclm);
    var cosim = Math.cos(inclm);
    var ep = em;
    var xincp = inclm;
    var argpp = argpm;
    var nodep = nodem;
    var mp = mm;
    var sinip = sinim;
    var cosip = cosim;
    var axnl = ep * Math.cos(argpp);
    var tempL = 1.0 / (am * (1.0 - ep * ep));
    var aynl = ep * Math.sin(argpp) + tempL * sat.aycof;
    var xl = mp + argpp + nodep + tempL * sat.xlcof * axnl;
    var u = satPosmod(xl - nodep, satTwopi);
    var eo1 = u;
    var tem5 = 9999.9;
    var ktr = 1;
    var sineo1 = 0;
    var coseo1 = 0;
    while (Math.abs(tem5) >= 1.0e-12 && ktr <= 10) {
      sineo1 = Math.sin(eo1);
      coseo1 = Math.cos(eo1);
      tem5 = 1.0 - coseo1 * axnl - sineo1 * aynl;
      tem5 = (u - aynl * coseo1 + axnl * sineo1 - eo1) / tem5;
      if (Math.abs(tem5) >= 0.95) tem5 = tem5 > 0 ? 0.95 : -0.95;
      eo1 = eo1 + tem5;
      ktr = ktr + 1;
    }
    var ecose = axnl * coseo1 + aynl * sineo1;
    var esine = axnl * sineo1 - aynl * coseo1;
    var el2 = axnl * axnl + aynl * aynl;
    var pl = am * (1.0 - el2);
    if (pl < 0) return null;
    var rl = am * (1.0 - ecose);
    var rdotl = Math.sqrt(am) * esine / rl;
    var rvdotl = Math.sqrt(pl) / rl;
    var betal = Math.sqrt(1.0 - el2);
    var tempS = esine / (1.0 + betal);
    var sinu = am / rl * (sineo1 - aynl - axnl * tempS);
    var cosu = am / rl * (coseo1 - axnl + aynl * tempS);
    var su = Math.atan2(sinu, cosu);
    var sin2u = (cosu + cosu) * sinu;
    var cos2u = 1.0 - 2.0 * sinu * sinu;
    var temp = 1.0 / pl;
    var temp1 = 0.5 * sat.j2 * temp;
    var temp2 = temp1 * temp;
    var mrt = rl * (1.0 - 1.5 * temp2 * betal * sat.con41) + 0.5 * temp1 * sat.x1mth2 * cos2u;
    su = su - 0.25 * temp2 * sat.x7thm1 * sin2u;
    var xnode = nodep + 1.5 * temp2 * cosip * sin2u;
    var xinc = xincp + 1.5 * temp2 * cosip * sinip * cos2u;
    var mvt = rdotl - nm * temp1 * sat.x1mth2 * sin2u / sat.xke;
    var rvdot = rvdotl + nm * temp1 * (sat.x1mth2 * cos2u + 1.5 * sat.con41) / sat.xke;
    var sinsu = Math.sin(su);
    var cossu = Math.cos(su);
    var snod = Math.sin(xnode);
    var cnod = Math.cos(xnode);
    var sini = Math.sin(xinc);
    var cosi = Math.cos(xinc);
    var xmx = -snod * cosi;
    var xmy = cnod * cosi;
    var ux = xmx * sinsu + cnod * cossu;
    var uy = xmy * sinsu + snod * cossu;
    var uz = sini * sinsu;
    var vx = xmx * cossu - cnod * sinsu;
    var vy = xmy * cossu - snod * sinsu;
    var vz = sini * cossu;
    var mr = mrt * sat.radiusearthkm;
    return {
      r: [mr * ux, mr * uy, mr * uz],
      v: [
        (mvt * ux + rvdot * vx) * vkmpersec,
        (mvt * uy + rvdot * vy) * vkmpersec,
        (mvt * uz + rvdot * vz) * vkmpersec
      ]
    };
  }

  function satDatePartsToJd(y, m, d, hh, mm, ss) {
    if (m <= 2) { y -= 1; m += 12; }
    var A = Math.floor(y / 100);
    var B = 2 - A + Math.floor(A / 4);
    return Math.floor(365.25 * (y + 4716)) + Math.floor(30.6001 * (m + 1)) + d + B - 1524.5 +
      (hh + mm / 60 + ss / 3600) / 24;
  }


  var satRec = null;
  var satError = "";
  var satFetchGen = 0;
  var satFetchBusy = false;
  var satFollowing = false;
  var satSession = null;
  var satWasUp = false;
  var satMoved = false;
  var satLastHz = 0;
  var satProfilePending = "";
  var satAnnounced = false;
  var satFollowGen = 0;
  var satPassCache = null;
  var SAT_EARTH_ROT = 7.292115146706979e-5;
  var SAT_C_KMS = 299792.458;

  function satJdFromDate(date) {
    return satDatePartsToJd(
      date.getUTCFullYear(), date.getUTCMonth() + 1, date.getUTCDate(),
      date.getUTCHours(), date.getUTCMinutes(),
      date.getUTCSeconds() + date.getUTCMilliseconds() / 1000
    );
  }

  function satSelected() {
    var id = ($("bs-sat-pick") || {}).value || "";
    var i;
    for (i = 0; i < SAT_CATALOG.length; i++) {
      if (SAT_CATALOG[i].id === id) return SAT_CATALOG[i];
    }
    return SAT_CATALOG[0];
  }

  function satModeLabel(mode) {
    if (mode === "nfm" || mode === "fm") return "FM";
    return String(mode || "").toUpperCase();
  }

  function satFmtDop(hz) {
    if (!isFinite(hz)) return "—";
    var sign = hz > 0 ? "+" : "";
    if (Math.abs(hz) >= 1000) return sign + (hz / 1000).toFixed(2) + " kHz";
    return sign + Math.round(hz) + " Hz";
  }

  function satReadObs() {
    var lat = parseFloat(($("bs-sat-lat") || {}).value);
    var lon = parseFloat(($("bs-sat-lon") || {}).value);
    var alt = parseFloat(($("bs-sat-alt") || {}).value);
    if (!isFinite(alt)) alt = 0;
    if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) return null;
    return { lat: lat, lon: lon, alt: Math.max(-500, Math.min(9000, alt)) };
  }

  function satReadDownlink() {
    var sel = satSelected();
    var mhz = parseFloat(($("bs-sat-mhz") || {}).value);
    var mode = (($("bs-sat-mode") || {}).value) || sel.mode;
    if (!(mhz > 0)) mhz = sel.mhz;
    return { mhz: mhz, mode: mode };
  }

  function satSaveObs() {
    var o = satReadObs();
    if (!o) return;
    try { window.localStorage.setItem("owrx_toolbox_sat_obs_v1", JSON.stringify(o)); } catch (e) {}
    satPassCache = null;
  }

  /** Toolbox-saved lat/lon (Sats onchange or More → QTH Save) — not OpenWebRX General GPS. */
  function satObsFromToolboxStorage() {
    try {
      var raw = JSON.parse(window.localStorage.getItem("owrx_toolbox_sat_obs_v1") || "null");
      if (raw && typeof raw === "object" && isFinite(Number(raw.lat)) && isFinite(Number(raw.lon))) {
        return {
          lat: Number(raw.lat),
          lon: Number(raw.lon),
          alt: isFinite(Number(raw.alt)) ? Number(raw.alt) : 0,
          source: "saved"
        };
      }
    } catch (e) {}
    return null;
  }

  function satApplyObsToFields(o) {
    if (!o || !isFinite(o.lat) || !isFinite(o.lon)) return;
    if ($("bs-sat-lat")) $("bs-sat-lat").value = o.lat;
    if ($("bs-sat-lon")) $("bs-sat-lon").value = o.lon;
    if ($("bs-sat-alt") && isFinite(o.alt)) $("bs-sat-alt").value = o.alt;
  }

  function satLoadObs() {
    var saved = satObsFromToolboxStorage();
    if (saved) {
      satApplyObsToFields(saved);
      return;
    }
    if (satReadObs()) return;
    var owrx = owrxReceiverObs();
    if (owrx) {
      satApplyObsToFields(owrx);
      return;
    }
    owrxEnsureReceiverObs(function (obs) {
      if (!obs || satObsFromToolboxStorage() || satReadObs()) return;
      satApplyObsToFields(obs);
      try { satPaint(satLookAt(Date.now())); } catch (eP) {}
    });
  }

  function satApplyCatalogFields() {
    var sel = satSelected();
    if ($("bs-sat-mhz")) $("bs-sat-mhz").value = sel.mhz.toFixed(3);
    if ($("bs-sat-mode")) $("bs-sat-mode").value = sel.mode;
  }

  function satObserverEcf(obs) {
    var a = 6378.137;
    var f = 1 / 298.257223563;
    var e2 = f * (2 - f);
    var lat = obs.lat * satDeg;
    var lon = obs.lon * satDeg;
    var alt = obs.alt / 1000;
    var sl = Math.sin(lat);
    var cl = Math.cos(lat);
    var N = a / Math.sqrt(1 - e2 * sl * sl);
    return {
      x: (N + alt) * cl * Math.cos(lon),
      y: (N + alt) * cl * Math.sin(lon),
      z: (N * (1 - e2) + alt) * sl,
      lat: lat,
      lon: lon
    };
  }

  function satEcf(r, gmst) {
    var c = Math.cos(gmst);
    var s = Math.sin(gmst);
    return [c * r[0] + s * r[1], -s * r[0] + c * r[1], r[2]];
  }

  function satLookAt(ms) {
    var obsIn = satReadObs();
    var down = satReadDownlink();
    if (!satRec || !satRec.sat || satRec.deep || !obsIn) return null;
    var jd = satJdFromDate(new Date(ms));
    var mins = (jd - satRec.sat.jdsatepoch) * 1440;
    var p = satSgp4(satRec.sat, mins);
    if (!p) return null;
    var gm = satGstime(jd);
    var r = satEcf(p.r, gm);
    var vr = satEcf(p.v, gm);
    var vs = [vr[0] + SAT_EARTH_ROT * r[1], vr[1] - SAT_EARTH_ROT * r[0], vr[2]];
    var o = satObserverEcf(obsIn);
    var vo = [-SAT_EARTH_ROT * o.y, SAT_EARTH_ROT * o.x, 0];
    var rho = [r[0] - o.x, r[1] - o.y, r[2] - o.z];
    var range = Math.hypot(rho[0], rho[1], rho[2]);
    if (!(range > 0)) return null;
    var rr = ((vs[0] - vo[0]) * rho[0] + (vs[1] - vo[1]) * rho[1] + (vs[2] - vo[2]) * rho[2]) / range;
    var sl = Math.sin(o.lat);
    var cl = Math.cos(o.lat);
    var so = Math.sin(o.lon);
    var co = Math.cos(o.lon);
    var north = -(sl * co * rho[0] + sl * so * rho[1] - cl * rho[2]);
    var east = -so * rho[0] + co * rho[1];
    var up = cl * co * rho[0] + cl * so * rho[1] + sl * rho[2];
    var el = Math.asin(Math.max(-1, Math.min(1, up / range))) * 180 / satPi;
    var az = Math.atan2(east, north) * 180 / satPi;
    if (az < 0) az += 360;
    var tuneHz = down.mhz * 1e6 * (1 - rr / SAT_C_KMS);
    return {
      el: el,
      az: az,
      rangeKm: range,
      dopHz: tuneHz - down.mhz * 1e6,
      tuneHz: tuneHz,
      mhz: down.mhz,
      mode: down.mode
    };
  }

  function satPass() {
    var obs = satReadObs();
    var sel = satSelected();
    if (!obs || !satRec || satRec.deep) return null;
    var key = sel.norad + "|" + obs.lat.toFixed(3) + "|" + obs.lon.toFixed(3) + "|" + Math.floor(Date.now() / 60000);
    if (satPassCache && satPassCache.key === key) return satPassCache;
    var now = Date.now();
    var step = 20000;
    var end = now + 18 * 3600 * 1000;
    var nowLook = satLookAt(now);
    var prev = nowLook;
    var aos = 0;
    var los = 0;
    var t;
    if (prev) {
      for (t = now + step; t <= end; t += step) {
        var look = satLookAt(t);
        if (!look) break;
        if (prev.el <= 0 && look.el > 0 && !aos) aos = t;
        if (prev.el > 0 && look.el <= 0 && !los) los = t;
        if (prev.el > 0 && los) break;
        if (prev.el <= 0 && aos) break;
        prev = look;
      }
    }
    satPassCache = { key: key, aos: aos, los: los, up: !!(nowLook && nowLook.el > 0) };
    return satPassCache;
  }

  function satClock(ms) {
    if (!(ms > 0)) return "";
    var d = new Date(ms);
    function z(n) { return (n < 10 ? "0" : "") + n; }
    return z(d.getHours()) + ":" + z(d.getMinutes());
  }

  function satPassLine(look) {
    var pass = satPass();
    if (!pass) return look && look.el > 0 ? "Above the horizon." : "Below the horizon.";
    if (look && look.el > 0) {
      return pass.los ? ("Up · sets " + satClock(pass.los)) : "Above the horizon.";
    }
    return pass.aos ? ("Below the horizon · rises " + satClock(pass.aos)) : "Below the horizon.";
  }

  function satSyncFollowUi() {
    var followBtn = $("bs-sat-follow");
    var stopBtn = $("bs-sat-stop");
    var satsSub = document.querySelector('#bs-tab-more .bs-more-sub[data-more-sub="sats"]');
    if (followBtn) {
      followBtn.classList.toggle("bs-on", !!satFollowing);
      followBtn.textContent = satFollowing ? "Following…" : "Follow";
      followBtn.disabled = !!satFollowing;
    }
    if (stopBtn) stopBtn.disabled = !satFollowing;
    if (satsSub) {
      satsSub.classList.toggle("bs-more-live", !!satFollowing);
      satsSub.title = satFollowing
        ? "Following a satellite. Open here, then Stop to put the radio back."
        : "Pick a satellite and follow the Doppler shift.";
    }
  }

  function satPaint(look) {
    var host = $("bs-sat-readout");
    if (!host) return;
    satSyncFollowUi();
    if (satError) {
      host.textContent = satError;
      return;
    }
    if (!satRec) {
      host.textContent = "Loading orbit…";
      return;
    }
    var sel = satSelected();
    if (satRec.deep) {
      host.textContent = sel.name + " is above the low-orbit model this section can follow.";
      return;
    }
    if (!look) {
      host.textContent = "Set latitude and longitude. The pass and Doppler show here. Follow does not move the radio until you press it.";
      return;
    }
    host.innerHTML =
      "<div><b>" + escapeHtml(sel.name) + "</b> · " + escapeHtml(look.mhz.toFixed(3)) + " MHz " + escapeHtml(satModeLabel(look.mode)) +
      (satFollowing ? ' <span class="bs-sat-live">following</span>' : "") + "</div>" +
      "<div>Elevation " + look.el.toFixed(1) + "° · azimuth " + Math.round(look.az) + "° · range " + Math.round(look.rangeKm) + " km</div>" +
      "<div>Doppler " + escapeHtml(satFmtDop(look.dopHz)) + " · tune " + escapeHtml(fmtMhz(look.tuneHz)) + "</div>" +
      "<div>" + escapeHtml(satPassLine(look)) + "</div>";
  }

  function satEnsure(force) {
    var sel = satSelected();
    if (!force && satRec && satRec.norad === sel.norad && Date.now() - satRec.at < 6 * 3600 * 1000) {
      satPaint(satLookAt(Date.now()));
      return;
    }
    var gen = ++satFetchGen;
    satFetchBusy = true;
    satError = "";
    if (!satRec || satRec.norad !== sel.norad) satPaint(null);
    var url = "https://celestrak.org/NORAD/elements/gp.php?CATNR=" + sel.norad + "&FORMAT=TLE";
    fetch(url, { cache: "no-store" }).then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.text();
    }).then(function (text) {
      if (gen !== satFetchGen) return;
      var lines = String(text || "").split(/\r?\n/).map(function (s) { return s.replace(/\s+$/, ""); });
      var line1 = "";
      var line2 = "";
      lines.forEach(function (s) {
        if (s.indexOf("1 ") === 0) line1 = s;
        else if (s.indexOf("2 ") === 0) line2 = s;
      });
      if (line1.length < 60 || line2.length < 60) throw new Error("tle");
      var sat = satFromTle(line1, line2);
      satRec = { norad: sel.norad, sat: sat, deep: !!sat.deep, at: Date.now() };
      satError = "";
      satPassCache = null;
      satFetchBusy = false;
      satPaint(satLookAt(Date.now()));
    }).catch(function () {
      if (gen !== satFetchGen) return;
      satFetchBusy = false;
      satError = "Orbit data did not answer.";
      satPaint(null);
    });
  }

  function satTick() {
    if (!satRec || satRec.norad !== satSelected().norad) {
      if (!satFetchBusy) satEnsure(false);
      return;
    }
    var look = satLookAt(Date.now());
    satPaint(look);
    if (satFollowing) satApplyFollow(look);
  }

  function satCapture() {
    var d = (typeof getDemodulators === "function" && getDemodulators()[0]) || null;
    var mod = "";
    try { if (window.UI && UI.getModulation) mod = UI.getModulation() || ""; } catch (e) {}
    var sec = false;
    try { if (d && d.get_secondary_demod) sec = d.get_secondary_demod(); } catch (e2) {}
    return {
      profile: currentProfileValue(),
      hz: currentTuneHz(),
      mod: mod,
      secondary: sec
    };
  }

  function satApplyMode(mode) {
    var m = mode === "fm" ? "nfm" : mode;
    if (!m || !window.UI || typeof UI.setModulation !== "function") return;
    try { UI.setModulation(m, ""); } catch (e) {}
    if (m !== "usb" && m !== "lsb") {
      var d = (typeof getDemodulators === "function" && getDemodulators()[0]) || null;
      if (d && d.set_secondary_demod) {
        try { d.set_secondary_demod(false); } catch (e2) {}
      }
    }
  }

  function satProfileCovers(p, hz) {
    var r = null;
    try { r = profileMhzRange(p); } catch (eR) { r = null; }
    if (!r) return false;
    return hz >= r.lo * 1e6 && hz <= r.hi * 1e6;
  }

  function satApplyFollow(look) {
    var gen = satFollowGen;
    if (!look || !(look.el > 0)) {
      if (satWasUp) satFollowStop("set");
      return;
    }
    var hz = Math.round(look.tuneHz);
    if (!(hz > 0)) return;
    var prof = null;
    try { prof = profileForFreq(hz); } catch (eP) { prof = null; }
    if (!satProfileCovers(prof, hz)) {
      if (!satAnnounced) {
        satAnnounced = true;
        setStatus("No profile covers " + fmtMhz(hz) + ". Follow is not moving the radio.");
      }
      return;
    }
    if (!satSession) satSession = satCapture();
    try { stopFlag = true; } catch (eStop) {}
    if (!satWasUp) satApplyMode(look.mode);
    satWasUp = true;
    function dial() {
      if (!satFollowing || gen !== satFollowGen) return;
      try { pluginSetFrequency(hz); } catch (eF) {}
      satLastHz = hz;
      satMoved = true;
      if (!satAnnounced) {
        satAnnounced = true;
        setStatus("Following " + satSelected().name + ". Stop puts the radio back.");
      }
    }
    if (prof && prof.value && currentProfileValue() !== prof.value) {
      if (satProfilePending === prof.value) return;
      satProfilePending = prof.value;
      if (typeof switchProfile === "function") {
        switchProfile(prof.value).then(function () {
          if (gen !== satFollowGen) return;
          satProfilePending = "";
          dial();
        }).catch(function () {
          if (gen !== satFollowGen) return;
          satProfilePending = "";
          dial();
        });
        return;
      }
    }
    if (Math.abs(hz - (satLastHz || 0)) < 5) return;
    dial();
  }

  function satFollowStop(why) {
    var gen = ++satFollowGen;
    satFollowing = false;
    satWasUp = false;
    satLastHz = 0;
    satAnnounced = false;
    satProfilePending = "";
    var session = satSession;
    var moved = satMoved;
    satSession = null;
    satMoved = false;
    try { satSyncFollowUi(); } catch (eUi) {}
    try { satPaint(satLookAt(Date.now())); } catch (eP) {}
    if (!session || !moved) {
      if (why === "set") setStatus("Satellite set.");
      else if (why === "stop") setStatus("Follow stopped.");
      return;
    }
    function back() {
      if (gen !== satFollowGen) return;
      try { if (session.hz > 0) pluginSetFrequency(session.hz); } catch (eF) {}
      if (session.mod && window.UI && typeof UI.setModulation === "function") {
        try { UI.setModulation(session.mod, ""); } catch (eM) {}
      }
      setTimeout(function () {
        if (gen !== satFollowGen) return;
        var d = (typeof getDemodulators === "function" && getDemodulators()[0]) || null;
        if (d && d.set_secondary_demod) {
          try { d.set_secondary_demod(session.secondary || false); } catch (eS) {}
        }
        setStatus(why === "set" ? "Satellite set. Radio restored." : "Follow stopped. Radio restored.");
      }, 250);
    }
    if (session.profile && currentProfileValue() !== session.profile && typeof switchProfile === "function") {
      switchProfile(session.profile).then(back).catch(back);
    } else back();
  }

  function satFollowStart() {
    if (satFollowing) return;
    if (!satReadObs()) {
      setStatus("Set latitude and longitude before Follow.");
      satPaint(null);
      return;
    }
    if (!satRec || satRec.deep) {
      setStatus(satRec && satRec.deep ? "This satellite is above the low-orbit model." : "Orbit is not loaded yet.");
      return;
    }
    satFollowGen++;
    satFollowing = true;
    satWasUp = false;
    satMoved = false;
    satSession = satCapture();
    satLastHz = 0;
    satAnnounced = false;
    satProfilePending = "";
    satSyncFollowUi();
    var look = satLookAt(Date.now());
    if (look && look.el > 0) {
      setStatus("Following " + satSelected().name + ". Stop puts the radio back.");
    } else {
      setStatus(satSelected().name + " is below the horizon. Follow waits, and will not move the radio until it rises.");
    }
    satTick();
  }

  function satOnTab() {
    satLoadObs();
    satPaint(satRec ? satLookAt(Date.now()) : null);
    satEnsure(false);
  }

  function bindSatTab() {
    var root = $("bs-more-sats");
    if (!root || root._bsSatWired) return;
    root._bsSatWired = true;
    satLoadObs();
    if ($("bs-sat-mhz") && !$("bs-sat-mhz").value) satApplyCatalogFields();
    ["bs-sat-lat", "bs-sat-lon", "bs-sat-alt"].forEach(function (id) {
      if (!$(id)) return;
      $(id).onchange = function () {
        satSaveObs();
        satPaint(satLookAt(Date.now()));
      };
    });
    if ($("bs-sat-pick")) {
      $("bs-sat-pick").onchange = function () {
        if (satFollowing) satFollowStop("stop");
        satApplyCatalogFields();
        satRec = null;
        satPassCache = null;
        satError = "";
        satEnsure(true);
      };
    }
    if ($("bs-sat-mhz")) $("bs-sat-mhz").onchange = function () { satPaint(satLookAt(Date.now())); };
    if ($("bs-sat-mode")) {
      $("bs-sat-mode").onchange = function () {
        if (satFollowing && satWasUp) satApplyMode(satReadDownlink().mode);
        satPaint(satLookAt(Date.now()));
      };
    }
    if ($("bs-sat-follow")) $("bs-sat-follow").onclick = function () { satFollowStart(); };
    if ($("bs-sat-stop")) $("bs-sat-stop").onclick = function () { satFollowStop("stop"); };
    if ($("bs-sat-refresh")) $("bs-sat-refresh").onclick = function () { satEnsure(true); };
    if (!window._bs_sat_timer) {
      window._bs_sat_timer = setInterval(function () {
        if (satFollowing) {
          satTick();
          return;
        }
        var pane = $("bs-tab-more");
        var sub = $("bs-more-sats");
        if (!pane || !pane.classList.contains("bs-tab-on")) return;
        if (!sub || !sub.classList.contains("bs-more-sub-on")) return;
        satTick();
      }, 1000);
    }
  }

  /* —— More extras (Passes / RBN / Time / Prop / Grey / Contest / Nets / Links) ——
     All lazy: no network or timers until that sub-tab is selected. */

  function moreTune(hz, mode, label) {
    hz = Math.round(Number(hz) || 0);
    if (!(hz > 0)) return;
    function dial() {
      try { pluginSetFrequency(hz); } catch (eF) {}
      if (mode && window.UI && typeof UI.setModulation === "function") {
        try { UI.setModulation(mode, ""); } catch (eM) {}
      }
      setStatus((label || "Tune") + " " + fmtMhz(hz) + (mode ? (" · " + String(mode).toUpperCase()) : "") + ".");
    }
    var p = null;
    try { p = profileForFreq(hz); } catch (eP) { p = null; }
    if (p && p.value && currentProfileValue() !== p.value && typeof switchProfile === "function") {
      switchProfile(p.value).then(dial).catch(dial);
      return;
    }
    dial();
  }

  /** Cached OpenWebRX receiver GPS from /status.json (same origin). */
  var owrxStatusObsCache = null;
  var owrxStatusObsAt = 0;
  var owrxStatusObsBusy = false;
  var owrxStatusObsWaiters = [];

  function owrxNormalizeObs(lat, lon, alt, source) {
    lat = Number(lat);
    lon = Number(lon);
    if (!(isFinite(lat) && isFinite(lon))) return null;
    if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) return null;
    return {
      lat: lat,
      lon: lon,
      alt: isFinite(Number(alt)) ? Number(alt) : 0,
      source: source || "owrx"
    };
  }

  /** OpenWebRX General GPS — Utils, header locator, or /status.json cache. */
  function owrxReceiverObs() {
    try {
      if (window.Utils) {
        var p = null;
        if (typeof Utils.getReceiverPos === "function") p = Utils.getReceiverPos();
        if (!p) p = Utils.receiver_pos;
        if (p) {
          var lon = p.lon != null ? p.lon : p.lng;
          var oU = owrxNormalizeObs(p.lat, lon, p.alt, "owrx");
          if (oU) return oU;
        }
      }
    } catch (eU) {}
    if (owrxStatusObsCache) return owrxStatusObsCache;
    try {
      var desc = document.querySelector(".webrx-rx-desc, #webrx-rx-desc, .openwebrx-rx-desc");
      var txt = desc ? String(desc.textContent || "") : "";
      var m = txt.match(/\bLoc:\s*([A-R]{2}[0-9]{2}[A-X]{0,2})/i);
      if (m && typeof qthGridToLatLon === "function") {
        var g = qthGridToLatLon(m[1]);
        var oG = g ? owrxNormalizeObs(g.lat, g.lon, 0, "owrx") : null;
        if (oG) return oG;
      }
    } catch (eH) {}
    return null;
  }

  function owrxObsFromStatusData(data) {
    var rec = data && data.receiver;
    if (!rec) return null;
    var asl = rec.asl;
    var gps = rec.gps;
    var obs = null;
    if (gps) {
      obs = owrxNormalizeObs(gps.lat, gps.lon != null ? gps.lon : gps.lng, asl, "owrx");
    }
    if (!obs && isFinite(Number(rec.lat)) && isFinite(Number(rec.lon))) {
      obs = owrxNormalizeObs(rec.lat, rec.lon, asl, "owrx");
    }
    if (!obs && rec.locator && typeof qthGridToLatLon === "function") {
      var g = qthGridToLatLon(String(rec.locator).trim());
      if (g) obs = owrxNormalizeObs(g.lat, g.lon, asl, "owrx");
    }
    return obs;
  }

  /** One-shot /status.json pull for receiver.gps (Pi-light; cached ~5 min). */
  function owrxEnsureReceiverObs(done) {
    done = typeof done === "function" ? done : function () {};
    var have = owrxReceiverObs();
    if (have) {
      done(have);
      return;
    }
    if (owrxStatusObsCache && owrxStatusObsAt && Date.now() - owrxStatusObsAt < 300000) {
      done(owrxStatusObsCache);
      return;
    }
    owrxStatusObsWaiters.push(done);
    if (owrxStatusObsBusy) return;
    owrxStatusObsBusy = true;
    var urls = ["/status.json", "status.json"];
    function finish(obs) {
      owrxStatusObsBusy = false;
      if (obs) {
        owrxStatusObsCache = obs;
        owrxStatusObsAt = Date.now();
        try {
          if (window.Utils) {
            Utils.receiver_pos = { lat: obs.lat, lon: obs.lon };
          }
        } catch (eSet) {}
      }
      var cbs = owrxStatusObsWaiters.slice();
      owrxStatusObsWaiters = [];
      cbs.forEach(function (cb) {
        try { cb(obs || owrxReceiverObs()); } catch (eCb) {}
      });
    }
    function tryFetch(i) {
      if (i >= urls.length) {
        finish(null);
        return;
      }
      fetch(urls[i], { credentials: "same-origin", cache: "no-store" }).then(function (res) {
        if (!res || !res.ok) throw new Error("status");
        return res.json();
      }).then(function (data) {
        var obs = owrxObsFromStatusData(data);
        if (obs) finish(obs);
        else tryFetch(i + 1);
      }).catch(function () {
        tryFetch(i + 1);
      });
    }
    tryFetch(0);
  }

  function moreObsFromStorage() {
    var saved = satObsFromToolboxStorage();
    if (saved) return saved;
    var o = satReadObs();
    if (o) {
      o.source = o.source || "form";
      return o;
    }
    return owrxReceiverObs();
  }

  /* Passes — next AOS/LOS for SAT_CATALOG (one amateur TLE pull). */
  var passTleByNorad = {};
  var passFetchedAt = 0;
  var passError = "";
  var passBusy = false;
  var passRows = [];
  var passTimer = 0;

  function passStopTimer() {
    if (passTimer) {
      clearInterval(passTimer);
      passTimer = 0;
    }
  }

  function passLookAt(satObj, obs, mhz, ms) {
    if (!satObj || satObj.deep || !obs) return null;
    var jd = satJdFromDate(new Date(ms));
    var mins = (jd - satObj.jdsatepoch) * 1440;
    var p = satSgp4(satObj, mins);
    if (!p) return null;
    var gm = satGstime(jd);
    var r = satEcf(p.r, gm);
    var vr = satEcf(p.v, gm);
    var vs = [vr[0] + SAT_EARTH_ROT * r[1], vr[1] - SAT_EARTH_ROT * r[0], vr[2]];
    var o = satObserverEcf(obs);
    var vo = [-SAT_EARTH_ROT * o.y, SAT_EARTH_ROT * o.x, 0];
    var rho = [r[0] - o.x, r[1] - o.y, r[2] - o.z];
    var range = Math.hypot(rho[0], rho[1], rho[2]);
    if (!(range > 0)) return null;
    var rr = ((vs[0] - vo[0]) * rho[0] + (vs[1] - vo[1]) * rho[1] + (vs[2] - vo[2]) * rho[2]) / range;
    var sl = Math.sin(o.lat);
    var cl = Math.cos(o.lat);
    var so = Math.sin(o.lon);
    var co = Math.cos(o.lon);
    var north = -(sl * co * rho[0] + sl * so * rho[1] - cl * rho[2]);
    var east = -so * rho[0] + co * rho[1];
    var up = cl * co * rho[0] + cl * so * rho[1] + sl * rho[2];
    var el = Math.asin(Math.max(-1, Math.min(1, up / range))) * 180 / satPi;
    var az = Math.atan2(east, north) * 180 / satPi;
    if (az < 0) az += 360;
    var tuneHz = mhz * 1e6 * (1 - rr / SAT_C_KMS);
    return { el: el, az: az, rangeKm: range, tuneHz: tuneHz };
  }

  function passNextFor(satObj, obs, now) {
    if (!satObj || !obs) return null;
    var step = 30000;
    var end = now + 24 * 3600 * 1000;
    var prev = passLookAt(satObj, obs, 145.8, now);
    if (!prev) return null;
    var aos = 0;
    var los = 0;
    var t;
    if (prev.el > 0) {
      for (t = now + step; t <= end; t += step) {
        var look = passLookAt(satObj, obs, 145.8, t);
        if (!look) break;
        if (prev.el > 0 && look.el <= 0) { los = t; break; }
        prev = look;
      }
      return { up: true, aos: 0, los: los };
    }
    for (t = now + step; t <= end; t += step) {
      var look2 = passLookAt(satObj, obs, 145.8, t);
      if (!look2) break;
      if (prev.el <= 0 && look2.el > 0 && !aos) aos = t;
      if (aos && prev.el > 0 && look2.el <= 0) { los = t; break; }
      prev = look2;
    }
    return { up: false, aos: aos, los: los };
  }

  function passFmtEta(ms) {
    if (!(ms > 0)) return "—";
    var sec = Math.max(0, Math.round((ms - Date.now()) / 1000));
    if (sec < 60) return sec + "s";
    if (sec < 3600) return Math.floor(sec / 60) + "m";
    var h = Math.floor(sec / 3600);
    var m = Math.floor((sec % 3600) / 60);
    return h + "h " + m + "m";
  }

  function passUniqueCatalog() {
    var seen = {};
    var out = [];
    SAT_CATALOG.forEach(function (s) {
      if (seen[s.norad]) return;
      seen[s.norad] = 1;
      out.push(s);
    });
    return out;
  }

  function passComputeRows() {
    var obs = moreObsFromStorage();
    var now = Date.now();
    var rows = [];
    passUniqueCatalog().forEach(function (s) {
      var satObj = passTleByNorad[s.norad];
      if (!satObj) {
        rows.push({ name: s.name, norad: s.norad, mhz: s.mhz, mode: s.mode, miss: true });
        return;
      }
      if (satObj.deep) {
        rows.push({ name: s.name, norad: s.norad, mhz: s.mhz, mode: s.mode, deep: true });
        return;
      }
      var p = passNextFor(satObj, obs, now);
      rows.push({
        name: s.name, norad: s.norad, mhz: s.mhz, mode: s.mode,
        up: !!(p && p.up), aos: p && p.aos, los: p && p.los
      });
    });
    rows.sort(function (a, b) {
      if (a.up && !b.up) return -1;
      if (!a.up && b.up) return 1;
      var ta = a.up ? (a.los || 1e15) : (a.aos || 1e15);
      var tb = b.up ? (b.los || 1e15) : (b.aos || 1e15);
      return ta - tb;
    });
    passRows = rows;
  }

  function passRender() {
    var host = $("bs-pass-list");
    var meta = $("bs-pass-meta");
    if (!host) return;
    var obs = moreObsFromStorage();
    if (meta) {
      if (!obs) meta.textContent = "Set lat/lon on Sats first.";
      else if (passError) meta.textContent = passError;
      else if (passBusy) meta.textContent = "Loading orbits…";
      else if (passFetchedAt) meta.textContent = "orbits " + trafficLogAgo(passFetchedAt);
      else meta.textContent = "";
    }
    if (!obs) {
      host.innerHTML = '<p class="bs-empty">Open Sats, set latitude and longitude, then come back.</p>';
      return;
    }
    if (passBusy && !passRows.length) {
      host.innerHTML = '<p class="bs-empty">Loading orbits…</p>';
      return;
    }
    if (!passRows.length) {
      host.innerHTML = '<p class="bs-empty">' + (passError || "No pass data yet.") + "</p>";
      return;
    }
    host.innerHTML = passRows.map(function (r) {
      var status;
      if (r.miss) status = "no TLE";
      else if (r.deep) status = "deep orbit";
      else if (r.up) status = "Up · sets " + satClock(r.los) + " (" + passFmtEta(r.los) + ")";
      else if (r.aos) status = "Rises " + satClock(r.aos) + " (" + passFmtEta(r.aos) + ")";
      else status = "No pass in 24 h";
      return '<article class="bs-more-row' + (r.up ? " bs-more-row-live" : "") + '" data-pass-mhz="' + r.mhz + '" data-pass-mode="' + escapeHtml(r.mode) + '" title="Tune nominal downlink.">' +
        '<span class="bs-more-name">' + escapeHtml(r.name) + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(r.mhz.toFixed(3)) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(status) + "</span>" +
        "</article>";
    }).join("");
  }

  function passEnsure(force) {
    if (!moreNetworkAllowed("passes")) {
      passError = "Network budget blocked More fetches.";
      passRender();
      return;
    }
    var obs = moreObsFromStorage();
    if (!obs) {
      passRender();
      return;
    }
    if (!force && passFetchedAt && Date.now() - passFetchedAt < 6 * 3600 * 1000 && Object.keys(passTleByNorad).length) {
      passComputeRows();
      passRender();
      return;
    }
    if (passBusy && !force) return;
    passBusy = true;
    passError = "";
    passRender();
    fetch("https://celestrak.org/NORAD/elements/gp.php?GROUP=amateur&FORMAT=TLE", { cache: "no-store" }).then(function (res) {
      if (!res.ok) throw new Error("HTTP " + res.status);
      return res.text();
    }).then(function (text) {
      var lines = String(text || "").split(/\r?\n/).map(function (s) { return s.replace(/\s+$/, ""); }).filter(Boolean);
      var map = {};
      var i;
      for (i = 0; i + 2 < lines.length; i++) {
        var a = lines[i];
        var b = lines[i + 1];
        var c = lines[i + 2];
        if (b.indexOf("1 ") === 0 && c.indexOf("2 ") === 0) {
          try {
            var sat = satFromTle(b, c);
            var norad = parseInt(b.substring(2, 7), 10);
            if (norad > 0) map[norad] = sat;
          } catch (eT) {}
          i += 2;
        } else if (a.indexOf("1 ") === 0 && b.indexOf("2 ") === 0) {
          try {
            var sat2 = satFromTle(a, b);
            var norad2 = parseInt(a.substring(2, 7), 10);
            if (norad2 > 0) map[norad2] = sat2;
          } catch (eT2) {}
          i += 1;
        }
      }
      passTleByNorad = map;
      passFetchedAt = Date.now();
      passBusy = false;
      passError = Object.keys(map).length ? "" : "No TLEs parsed.";
      passComputeRows();
      passRender();
    }).catch(function () {
      passBusy = false;
      passError = "Orbit data did not answer.";
      passRender();
    });
  }

  function passOnTab() {
    passEnsure(false);
    passStopTimer();
    passTimer = setInterval(function () {
      var pane = $("bs-tab-more");
      var sub = $("bs-more-passes");
      if (!pane || !pane.classList.contains("bs-tab-on")) return;
      if (!sub || !sub.classList.contains("bs-more-sub-on")) return;
      if (Object.keys(passTleByNorad).length) {
        passComputeRows();
        passRender();
      }
    }, 30000);
  }

  function bindPassTab() {
    var root = $("bs-more-passes");
    if (!root || root._bsPassWired) return;
    root._bsPassWired = true;
    root.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      if (t.closest("#bs-pass-refresh")) {
        passEnsure(true);
        return;
      }
      var row = t.closest("[data-pass-mhz]");
      if (row) moreTune(parseFloat(row.getAttribute("data-pass-mhz")) * 1e6, row.getAttribute("data-pass-mode") || "nfm", "Pass");
    });
  }

  /* RBN — skimmer filter on shared DX cache. */
  var rbnScope = "cw";

  function rbnModeKind(spot) {
    var s = String((spot && (spot.submode || spot.mode)) || "").toLowerCase();
    if (s === "cw" || s.indexOf("cw") === 0) return "cw";
    if (/ft8|ft4|jt65|jt9|q65|msk|psk|rtty|olivia|js8|fst4|wspr/.test(s)) return "digi";
    return "";
  }

  function rbnVisibleSpots() {
    var now = Date.now();
    var band = "";
    try { band = dxBandKey(activityBandName(currentTuneHz())); } catch (eB) {}
    return dxSpots.filter(function (spot) {
      if (!spot) return false;
      var at = dxSpotWhen(spot);
      if (!at || now - at > DX_MAX_AGE_MS) return false;
      var hz = dxHz(spot.frequency);
      if (!(hz > 0)) return false;
      var kind = rbnModeKind(spot);
      if (!kind) return false;
      if (rbnScope === "cw") return kind === "cw";
      if (rbnScope === "digi") return kind === "digi";
      if (rbnScope === "band") {
        if (!band) return true;
        return dxBandKey(spot.band) === band || dxBandKey(activityBandName(hz)) === band;
      }
      return true;
    }).sort(function (a, b) { return dxSpotWhen(b) - dxSpotWhen(a); }).slice(0, 80);
  }

  function rbnRender() {
    var host = $("bs-rbn-list");
    if (!host) return;
    var meta = $("bs-rbn-meta");
    Array.prototype.forEach.call(document.querySelectorAll("#bs-rbn-scopes [data-rbn-scope]"), function (btn) {
      btn.classList.toggle("bs-on", btn.getAttribute("data-rbn-scope") === rbnScope);
    });
    var rows = rbnVisibleSpots();
    var age = dxFetchedAt ? trafficLogAgo(dxFetchedAt) : "";
    if (meta) {
      meta.textContent = dxError
        ? dxError
        : (dxFetchedAt ? (rows.length + " spot" + (rows.length === 1 ? "" : "s") + " · " + age) : "Loading spots…");
    }
    if (!dxFetchedAt && !dxError) {
      host.innerHTML = '<p class="bs-empty">Loading spots…</p>';
      return;
    }
    if (!rows.length) {
      host.innerHTML = '<p class="bs-empty">' + (dxError ? "No spots loaded." : "No skimmer spots for this filter.") + "</p>";
      return;
    }
    host.innerHTML = rows.map(function (spot) {
      var hz = dxHz(spot.frequency);
      var at = dxSpotWhen(spot);
      var fresh = Date.now() - at < 6 * 60 * 1000;
      var mode = String(spot.submode || spot.mode || "");
      var call = String(spot.spotted || "");
      return '<article class="bs-dx-row' + (fresh ? " bs-dx-fresh" : "") + '" data-rbn-tune="' + hz + '" data-rbn-mode="' + escapeHtml(dxSpotMode(spot)) + '" title="Tune this spot.">' +
        '<span class="bs-dx-when">' + escapeHtml(trafficLogAgo(at)) + "</span>" +
        '<span class="bs-dx-call">' + lookupHtml(call, mode, "FT8") + "</span>" +
        '<span class="bs-dx-mhz">' + escapeHtml(fmtMhz(hz)) + "</span>" +
        '<span class="bs-dx-mode">' + escapeHtml(mode) + "</span>" +
        '<span class="bs-dx-band">' + escapeHtml(spot.band || "") + "</span>" +
        '<span class="bs-dx-msg">' + escapeHtml(String(spot.message || "").replace(/\s+/g, " ").trim().slice(0, 80)) + "</span>" +
        '<span class="bs-dx-by">' + escapeHtml(spot.spotter || "") + "</span>" +
        "</article>";
    }).join("");
  }

  function rbnOnTab() {
    rbnRender();
    if (!dxFetchedAt || Date.now() - dxFetchedAt > 60000) {
      dxFetch().then(function () { rbnRender(); });
    }
  }

  function bindRbnTab() {
    var root = $("bs-more-rbn");
    if (!root || root._bsRbnWired) return;
    root._bsRbnWired = true;
    root.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      if (t.closest("a.bs-lookup")) return;
      if (t.closest("#bs-rbn-refresh")) {
        dxFetch().then(function () { rbnRender(); });
        return;
      }
      var scope = t.closest("[data-rbn-scope]");
      if (scope) {
        rbnScope = scope.getAttribute("data-rbn-scope") || "cw";
        rbnRender();
        return;
      }
      var row = t.closest("[data-rbn-tune]");
      if (row) moreTune(row.getAttribute("data-rbn-tune"), row.getAttribute("data-rbn-mode") || "cw", "RBN");
    });
  }

