  /* Prop — reuse solarEnsure / solarInfo (no extra polling). */
  function propPaint() {
    var host = $("bs-prop-host");
    var meta = $("bs-prop-meta");
    if (!host) return;
    if (meta) {
      meta.textContent = solarBusy
        ? "refreshing…"
        : (solarFetchedAt ? ("updated " + trafficLogAgo(solarFetchedAt)) : (solarError || ""));
    }
    if (!solarInfo) {
      host.innerHTML = '<p class="bs-empty">' + escapeHtml(solarError || "Loading solar weather…") + "</p>";
      return;
    }
    var sfi = Number(solarInfo.sfi);
    var k = Number(solarInfo.k);
    var tip = solarInfo.note || "";
    var muf = "—";
    if (sfi > 0) {
      /* Crude mid-latitude daytime F2 hint — not a real ionosonde. */
      var rough = Math.round(7 + (sfi - 70) * 0.08 - (isFinite(k) ? k * 0.4 : 0));
      if (rough < 5) rough = 5;
      if (rough > 45) rough = 45;
      muf = "~" + rough + " MHz";
    }
    host.innerHTML =
      solarMetricsGridHtml(solarInfo) +
      '<div class="bs-prop-extra"><span>Rough MUF hint</span><b>' + escapeHtml(muf) + "</b></div>" +
      '<p class="bs-solar-note">' + escapeHtml(tip) + "</p>";
  }

  function propOnTab() {
    try { solarEnsure(false); } catch (e) {}
    propPaint();
    /* Re-paint after solar fetch settles (solarPaint does not know Prop). */
    var n = 0;
    var iv = setInterval(function () {
      propPaint();
      n += 1;
      if (!solarBusy || n > 40) clearInterval(iv);
    }, 250);
  }

  function bindPropTab() {
    var root = $("bs-more-prop");
    if (!root || root._bsPropWired) return;
    root._bsPropWired = true;
    if ($("bs-prop-refresh")) {
      $("bs-prop-refresh").onclick = function () {
        try { solarEnsure(true); } catch (e) {}
        propOnTab();
      };
    }
  }

  /* Greyline — canvas redraw only while open. */
  var greyTimer = 0;

  function greyStopTimer() {
    if (greyTimer) {
      clearInterval(greyTimer);
      greyTimer = 0;
    }
  }

  function greySubsolar(date) {
    var jd = satJdFromDate(date);
    var T = (jd - 2451545.0) / 36525;
    var L0 = (280.46646 + 36000.76983 * T) % 360;
    if (L0 < 0) L0 += 360;
    var M = (357.52911 + 35999.05029 * T) % 360;
    if (M < 0) M += 360;
    var Mr = M * Math.PI / 180;
    var C = (1.914602 - 0.004817 * T) * Math.sin(Mr) + 0.019993 * Math.sin(2 * Mr);
    var tl = L0 + C;
    var eps = 23.439291 - 0.0130042 * T;
    var tr = tl * Math.PI / 180;
    var er = eps * Math.PI / 180;
    var dec = Math.asin(Math.sin(er) * Math.sin(tr)) * 180 / Math.PI;
    var ra = Math.atan2(Math.cos(er) * Math.sin(tr), Math.cos(tr)) * 180 / Math.PI;
    var gmst = satGstime(jd) * 180 / Math.PI;
    var lon = (ra - gmst) % 360;
    if (lon > 180) lon -= 360;
    if (lon < -180) lon += 360;
    return { lat: dec, lon: lon };
  }

  function greyPaint() {
    var canvas = $("bs-grey-canvas");
    var meta = $("bs-grey-meta");
    if (!canvas || !canvas.getContext) return;
    var ctx = canvas.getContext("2d");
    var w = canvas.width;
    var h = canvas.height;
    var sun = greySubsolar(new Date());
    var obs = moreObsFromStorage();
    var img = ctx.createImageData(w, h);
    var data = img.data;
    var sinSun = Math.sin(sun.lat * Math.PI / 180);
    var cosSun = Math.cos(sun.lat * Math.PI / 180);
    var y;
    var x;
    for (y = 0; y < h; y++) {
      var lat = 90 - (y / (h - 1)) * 180;
      var sinLat = Math.sin(lat * Math.PI / 180);
      var cosLat = Math.cos(lat * Math.PI / 180);
      for (x = 0; x < w; x++) {
        var lon = -180 + (x / (w - 1)) * 360;
        var cosc = sinLat * sinSun + cosLat * cosSun * Math.cos((lon - sun.lon) * Math.PI / 180);
        var i = (y * w + x) * 4;
        if (cosc < 0) {
          data[i] = 15; data[i + 1] = 23; data[i + 2] = 42; data[i + 3] = 255;
        } else if (cosc < 0.12) {
          data[i] = 120; data[i + 1] = 90; data[i + 2] = 40; data[i + 3] = 255;
        } else {
          data[i] = 30; data[i + 1] = 58; data[i + 2] = 95; data[i + 3] = 255;
        }
      }
    }
    ctx.putImageData(img, 0, 0);
    ctx.strokeStyle = "rgba(148, 163, 184, 0.35)";
    ctx.lineWidth = 1;
    for (var g = -150; g <= 150; g += 30) {
      var gx = ((g + 180) / 360) * w;
      ctx.beginPath();
      ctx.moveTo(gx, 0);
      ctx.lineTo(gx, h);
      ctx.stroke();
    }
    for (var gl = -60; gl <= 60; gl += 30) {
      var gy = ((90 - gl) / 180) * h;
      ctx.beginPath();
      ctx.moveTo(0, gy);
      ctx.lineTo(w, gy);
      ctx.stroke();
    }
    var sx = ((sun.lon + 180) / 360) * w;
    var sy = ((90 - sun.lat) / 180) * h;
    ctx.fillStyle = "#fbbf24";
    ctx.beginPath();
    ctx.arc(sx, sy, 4, 0, Math.PI * 2);
    ctx.fill();
    if (obs) {
      var ox = ((obs.lon + 180) / 360) * w;
      var oy = ((90 - obs.lat) / 180) * h;
      ctx.fillStyle = "#86efac";
      ctx.beginPath();
      ctx.arc(ox, oy, 5, 0, Math.PI * 2);
      ctx.fill();
      if (meta) meta.textContent = "Sun " + sun.lat.toFixed(1) + "° / " + sun.lon.toFixed(1) + "° · you " + obs.lat.toFixed(2) + ", " + obs.lon.toFixed(2);
    } else if (meta) {
      meta.textContent = "Sun " + sun.lat.toFixed(1) + "° / " + sun.lon.toFixed(1) + "° · set lat/lon on Sats to mark the receiver.";
    }
  }

  function greyOnTab() {
    greyPaint();
    greyStopTimer();
    greyTimer = setInterval(function () {
      var pane = $("bs-tab-more");
      var sub = $("bs-more-grey");
      if (!pane || !pane.classList.contains("bs-tab-on")) return;
      if (!sub || !sub.classList.contains("bs-more-sub-on")) return;
      greyPaint();
    }, 60000);
  }

  function bindGreyTab() {
    /* paint-only; no clicks */
  }

  /* Contests — static calendar, no network. */
  function contestWeekendStart(year, month0, nth) {
    /* nth full weekend: Saturday of the nth weekend that has Sat+Sun in month. */
    var d = new Date(Date.UTC(year, month0, 1));
    var weekends = [];
    while (d.getUTCMonth() === month0) {
      if (d.getUTCDay() === 6) {
        var sun = new Date(d.getTime() + 86400000);
        if (sun.getUTCMonth() === month0) weekends.push(new Date(d.getTime()));
      }
      d.setUTCDate(d.getUTCDate() + 1);
    }
    if (nth < 0) return weekends[weekends.length + nth] || null;
    return weekends[nth - 1] || null;
  }

  function contestBuildList() {
    var now = Date.now();
    var y0 = new Date().getUTCFullYear();
    var defs = [
      { name: "ARRL DX CW", month: 1, nth: 3, days: 2, bands: "HF" },
      { name: "ARRL DX SSB", month: 2, nth: 1, days: 2, bands: "HF" },
      { name: "CQ WPX SSB", month: 2, nth: -1, days: 2, bands: "HF" },
      { name: "CQ WPX CW", month: 4, nth: -1, days: 2, bands: "HF" },
      { name: "ARRL Field Day", month: 5, nth: 4, days: 2, bands: "HF / VHF" },
      { name: "IARU HF Championship", month: 6, nth: 2, days: 2, bands: "HF" },
      { name: "CQ WW RTTY", month: 8, nth: -1, days: 2, bands: "HF" },
      { name: "CQ WW SSB", month: 9, nth: -1, days: 2, bands: "HF" },
      { name: "CQ WW CW", month: 10, nth: -1, days: 2, bands: "HF" },
      { name: "ARRL 160 m", month: 11, nth: 1, days: 2, bands: "160 m" },
      { name: "ARRL 10 m", month: 11, nth: 2, days: 2, bands: "10 m" }
    ];
    var out = [];
    [y0, y0 + 1].forEach(function (y) {
      defs.forEach(function (def) {
        var start = contestWeekendStart(y, def.month, def.nth);
        if (!start) return;
        var end = new Date(start.getTime() + def.days * 86400000);
        if (end.getTime() < now - 86400000) return;
        out.push({ name: def.name, start: start, end: end, bands: def.bands });
      });
    });
    out.sort(function (a, b) { return a.start - b.start; });
    return out.slice(0, 14);
  }

  function contestFmt(d) {
    var months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
    return months[d.getUTCMonth()] + " " + d.getUTCDate();
  }

  function contestRender() {
    var host = $("bs-contest-list");
    if (!host) return;
    var rows = contestBuildList();
    if (!rows.length) {
      host.innerHTML = '<p class="bs-empty">No upcoming contests in the built-in list.</p>';
      return;
    }
    host.innerHTML = rows.map(function (c) {
      var live = Date.now() >= c.start.getTime() && Date.now() <= c.end.getTime();
      return '<article class="bs-more-row' + (live ? " bs-more-row-live" : "") + '">' +
        '<span class="bs-more-name">' + escapeHtml(c.name) + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(contestFmt(c.start) + "–" + contestFmt(c.end)) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(c.bands) + (live ? " · on now" : "") + "</span>" +
        "</article>";
    }).join("");
  }

  function contestOnTab() { contestRender(); }

  /* Nets — localStorage. */
  var netsList = [];

  function netsLoad() {
    try {
      var raw = JSON.parse(window.localStorage.getItem("owrx_toolbox_nets_v1") || "[]");
      netsList = Array.isArray(raw) ? raw.filter(function (n) {
        return n && n.name && isFinite(n.mhz);
      }) : [];
    } catch (e) { netsList = []; }
  }

  function netsSave() {
    try { window.localStorage.setItem("owrx_toolbox_nets_v1", JSON.stringify(netsList.slice(0, 40))); } catch (e) {}
  }

  function netsRender() {
    var host = $("bs-net-list");
    if (!host) return;
    if (!netsList.length) {
      host.innerHTML = '<p class="bs-empty">No nets yet — add one above.</p>';
      return;
    }
    host.innerHTML = netsList.map(function (n, i) {
      return '<article class="bs-more-row" data-net-i="' + i + '" data-net-mhz="' + n.mhz + '" data-net-mode="' + escapeHtml(n.mode || "usb") + '" title="Tune this net.">' +
        '<span class="bs-more-name">' + escapeHtml(n.name) + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(Number(n.mhz).toFixed(3)) + "</span>" +
        '<span class="bs-more-mode">' + escapeHtml(String(n.mode || "usb").toUpperCase()) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml((n.day || "Daily") + " " + (n.utc || "")) + "</span>" +
        '<button type="button" class="bs-tiny bs-btn-clear" data-net-del="' + i + '" title="Remove this net.">Del</button>' +
        "</article>";
    }).join("");
  }

  function netsOnTab() {
    netsLoad();
    netsRender();
    bindLightIoPair("bs-net-export", "bs-net-import", "bs-net-file",
      function () {
        netsLoad();
        return { kind: "owrx_toolbox_nets", when: Date.now(), nets: netsList };
      },
      function (text) {
        var o = JSON.parse(String(text || "").trim());
        var list = (o && o.nets) || (Array.isArray(o) ? o : []);
        netsLoad();
        var n = 0;
        list.forEach(function (row) {
          if (!row || !row.name || !isFinite(row.mhz)) return;
          netsList.push({
            name: String(row.name).slice(0, 48),
            mhz: Number(row.mhz),
            mode: row.mode || "usb",
            day: row.day || "Daily",
            utc: row.utc || ""
          });
          n++;
        });
        if (netsList.length > 40) netsList = netsList.slice(0, 40);
        netsSave();
        netsRender();
        setStatus(n ? ("Imported " + n + " net(s).") : "No nets in that file.");
      },
      "toolbox-nets.json", "application/json", "Import nets");
  }

  function bindNetsTab() {
    var root = $("bs-more-nets");
    if (!root || root._bsNetsWired) return;
    root._bsNetsWired = true;
    if ($("bs-net-add")) {
      $("bs-net-add").onclick = function () {
        var name = (($("bs-net-name") || {}).value || "").trim();
        var mhz = parseFloat(($("bs-net-mhz") || {}).value);
        var mode = (($("bs-net-mode") || {}).value) || "usb";
        var day = (($("bs-net-day") || {}).value) || "Daily";
        var utc = (($("bs-net-utc") || {}).value || "").trim();
        if (!name || !(mhz > 0)) {
          setStatus("Net needs a name and MHz.");
          return;
        }
        if (utc && !/^\d{1,2}:\d{2}$/.test(utc)) {
          setStatus("UTC time like 19:00.");
          return;
        }
        netsList.push({ name: name.slice(0, 48), mhz: mhz, mode: mode, day: day, utc: utc });
        netsSave();
        if ($("bs-net-name")) $("bs-net-name").value = "";
        netsRender();
        setStatus("Net saved.");
      };
    }
    root.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      var del = t.closest("[data-net-del]");
      if (del) {
        var di = parseInt(del.getAttribute("data-net-del"), 10);
        if (di >= 0) {
          netsList.splice(di, 1);
          netsSave();
          netsRender();
        }
        return;
      }
      var row = t.closest("[data-net-mhz]");
      if (row) moreTune(parseFloat(row.getAttribute("data-net-mhz")) * 1e6, row.getAttribute("data-net-mode") || "usb", "Net");
    });
  }

  /* Beacons (More) — same NCDXF cycle as Bands → Beacons; timer only while open. */
  var moreBeaconTimer = 0;

  function moreBeaconStopTimer() {
    if (moreBeaconTimer) {
      clearInterval(moreBeaconTimer);
      moreBeaconTimer = 0;
    }
  }

  function moreBeaconsOnTab() {
    moreBeaconRender();
    moreBeaconStopTimer();
    moreBeaconTimer = setInterval(function () {
      var pane = $("bs-tab-more");
      var sub = $("bs-more-beacons");
      if (!pane || !pane.classList.contains("bs-tab-on")) return;
      if (!sub || !sub.classList.contains("bs-more-sub-on")) return;
      moreBeaconRender();
    }, 1000);
  }

  /* Alerts — NOAA SWPC. */
  var alertsRows = [];
  var alertsFetchedAt = 0;
  var alertsError = "";
  var alertsBusy = false;
  var alertsGen = 0;

  function alertsTitleFromMessage(msg) {
    var lines = String(msg || "").replace(/\r/g, "").split("\n");
    var i, line, m;
    for (i = 0; i < lines.length; i++) {
      line = lines[i].trim();
      if (!line) continue;
      m = line.match(/^(ALERT|WARNING|WATCH|SUMMARY|EXTENDED WARNING)\b[:\s]*(.*)$/i);
      if (m) return (m[1].toUpperCase() + (m[2] ? (": " + m[2]) : "")).slice(0, 120);
    }
    for (i = 0; i < lines.length; i++) {
      line = lines[i].trim();
      if (line && !/^Space Weather Message/i.test(line) && !/^Serial Number/i.test(line) && !/^Issue Time/i.test(line)) {
        return line.slice(0, 120);
      }
    }
    return "SWPC message";
  }

  function alertsPaint() {
    var host = $("bs-alerts-list");
    var meta = $("bs-alerts-meta");
    var btn = $("bs-alerts-refresh");
    if (btn) {
      btn.disabled = !!alertsBusy;
      btn.textContent = alertsBusy ? "Refreshing…" : "Refresh";
    }
    if (meta) {
      meta.textContent = alertsBusy
        ? (alertsFetchedAt ? ("updated " + trafficLogAgo(alertsFetchedAt) + " · refreshing…") : "refreshing…")
        : (alertsFetchedAt ? ("updated " + trafficLogAgo(alertsFetchedAt)) : "");
    }
    if (!host) return;
    if (!alertsRows.length) {
      host.innerHTML = '<p class="bs-empty">' +
        escapeHtml(alertsError || (alertsBusy ? "Loading alerts…" : "No recent alerts.")) + "</p>";
      return;
    }
    host.innerHTML = alertsRows.map(function (a) {
      return '<article class="bs-more-row" title="' + escapeHtml(a.blurb || a.title) + '">' +
        '<span class="bs-more-name">' + escapeHtml(a.title) + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(a.when || "") + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(a.id || "") + "</span>" +
        "</article>";
    }).join("");
  }

  function alertsEnsure(force) {
    if (!moreNetworkAllowed("alerts")) {
      alertsError = "Network budget blocked More fetches.";
      alertsPaint();
      return;
    }
    if (!force && alertsFetchedAt && Date.now() - alertsFetchedAt < 10 * 60 * 1000 && alertsRows.length) {
      alertsPaint();
      return;
    }
    if (alertsBusy && !force) return;
    var gen = ++alertsGen;
    alertsBusy = true;
    alertsError = "";
    alertsPaint();
    fetch("https://services.swpc.noaa.gov/products/alerts.json", { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("http");
        return r.json();
      })
      .then(function (rows) {
        if (gen !== alertsGen) return;
        var list = Array.isArray(rows) ? rows : [];
        alertsRows = list.slice(0, 16).map(function (row) {
          var msg = String((row && row.message) || "");
          var title = alertsTitleFromMessage(msg);
          var when = String((row && row.issue_datetime) || "").replace("T", " ").slice(0, 16);
          var blurb = msg.replace(/\s+/g, " ").trim().slice(0, 220);
          return { id: (row && row.product_id) || "", title: title, when: when, blurb: blurb };
        });
        alertsFetchedAt = Date.now();
        alertsBusy = false;
        alertsError = alertsRows.length ? "" : "No alerts in the feed.";
        alertsPaint();
      })
      .catch(function () {
        if (gen !== alertsGen) return;
        alertsBusy = false;
        alertsError = "SWPC alerts did not answer.";
        alertsPaint();
      });
  }

  function alertsOnTab() { alertsEnsure(false); }

  function bindAlertsTab() {
    var root = $("bs-more-alerts");
    if (!root || root._bsAlertsWired) return;
    root._bsAlertsWired = true;
    if ($("bs-alerts-refresh")) {
      $("bs-alerts-refresh").onclick = function () { alertsEnsure(true); };
    }
  }

  /* Aurora — OVATION. */
  var auroraInfo = null;
  var auroraFetchedAt = 0;
  var auroraError = "";
  var auroraBusy = false;
  var auroraGen = 0;

  function auroraPaint() {
    var host = $("bs-aurora-host");
    var meta = $("bs-aurora-meta");
    var btn = $("bs-aurora-refresh");
    if (btn) {
      btn.disabled = !!auroraBusy;
      btn.textContent = auroraBusy ? "Refreshing…" : "Refresh";
    }
    if (meta) {
      meta.textContent = auroraBusy
        ? (auroraFetchedAt ? ("updated " + trafficLogAgo(auroraFetchedAt) + " · refreshing…") : "refreshing…")
        : (auroraFetchedAt ? ("updated " + trafficLogAgo(auroraFetchedAt)) : "");
    }
    if (!host) return;
    if (!auroraInfo) {
      host.innerHTML = '<p class="bs-empty">' +
        escapeHtml(auroraError || (auroraBusy ? "Loading OVATION…" : "Open Refresh, or set lat/lon on QTH / Sats.")) +
        "</p>";
      return;
    }
    var a = auroraInfo;
    var tip = "Quiet at your latitude.";
    if (a.at >= 50) tip = "Strong aurora probability overhead — HF polar paths may be disturbed.";
    else if (a.at >= 20) tip = "Elevated aurora chance nearby.";
    else if (a.at >= 5) tip = "Low aurora activity.";
    host.innerHTML =
      '<div class="bs-solar-grid">' +
      "<div><span>At QTH</span><b>" + escapeHtml(String(a.at)) + "%</b></div>" +
      "<div><span>Peak N</span><b>" + escapeHtml(String(a.maxN)) + "%</b></div>" +
      "<div><span>Peak S</span><b>" + escapeHtml(String(a.maxS)) + "%</b></div>" +
      "<div><span>Grid</span><b>" + escapeHtml(a.grid || "—") + "</b></div>" +
      "</div>" +
      '<p class="bs-solar-note">' + escapeHtml(tip) + "</p>" +
      '<p class="bs-hint">Forecast ' + escapeHtml(a.forecast || "—") +
      (a.obs ? (" · QTH " + a.obs.lat.toFixed(2) + ", " + a.obs.lon.toFixed(2)) : " · set lat/lon on QTH / Sats") +
      "</p>";
  }

  function auroraEnsure(force) {
    if (!moreNetworkAllowed("aurora")) {
      auroraError = "Network budget blocked More fetches.";
      auroraPaint();
      return;
    }
    if (!force && auroraFetchedAt && Date.now() - auroraFetchedAt < 15 * 60 * 1000 && auroraInfo) {
      auroraPaint();
      return;
    }
    if (auroraBusy && !force) return;
    var gen = ++auroraGen;
    auroraBusy = true;
    auroraError = "";
    auroraPaint();
    fetch("https://services.swpc.noaa.gov/json/ovation_aurora_latest.json", { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("http");
        return r.json();
      })
      .then(function (data) {
        if (gen !== auroraGen) return;
        var coords = (data && data.coordinates) || [];
        var obs = moreObsFromStorage();
        var at = 0;
        var maxN = 0;
        var maxS = 0;
        var i, c, lon, lat, v, dlon, dlat, best;
        best = 1e9;
        for (i = 0; i < coords.length; i++) {
          c = coords[i];
          if (!c || c.length < 3) continue;
          lon = Number(c[0]);
          lat = Number(c[1]);
          v = Number(c[2]) || 0;
          if (lat >= 0) { if (v > maxN) maxN = v; }
          else { if (v > maxS) maxS = v; }
          if (obs) {
            dlon = lon - ((obs.lon % 360) + 360) % 360;
            if (dlon > 180) dlon -= 360;
            if (dlon < -180) dlon += 360;
            dlat = lat - obs.lat;
            var dist = dlon * dlon + dlat * dlat;
            if (dist < best) {
              best = dist;
              at = v;
            }
          }
        }
        var grid = "";
        try { if (obs) grid = qthMaidenhead(obs.lat, obs.lon, 6); } catch (eG) { grid = ""; }
        auroraInfo = {
          at: Math.round(at),
          maxN: Math.round(maxN),
          maxS: Math.round(maxS),
          forecast: String((data && (data["Forecast Time"] || data.ForecastTime)) || "").replace("T", " ").replace("Z", " UTC"),
          obs: obs,
          grid: grid
        };
        auroraFetchedAt = Date.now();
        auroraBusy = false;
        auroraError = "";
        auroraPaint();
      })
      .catch(function () {
        if (gen !== auroraGen) return;
        auroraBusy = false;
        auroraError = "OVATION did not answer.";
        auroraPaint();
      });
  }

  function auroraOnTab() { auroraEnsure(false); }

  function bindAuroraTab() {
    var root = $("bs-more-aurora");
    if (!root || root._bsAuroraWired) return;
    root._bsAuroraWired = true;
    if ($("bs-aurora-refresh")) {
      $("bs-aurora-refresh").onclick = function () { auroraEnsure(true); };
    }
  }

  /* QTH — grid / clocks / sun — local only. */
  var qthTimer = 0;

  function qthStopTimer() {
    if (qthTimer) {
      clearInterval(qthTimer);
      qthTimer = 0;
    }
  }

  function qthMaidenhead(lat, lon, precision) {
    precision = precision || 6;
    lon = Number(lon);
    lat = Number(lat);
    if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) return "—";
    var adjLon = lon + 180;
    var adjLat = lat + 90;
    var out = "";
    out += String.fromCharCode(65 + Math.floor(adjLon / 20));
    out += String.fromCharCode(65 + Math.floor(adjLat / 10));
    out += String(Math.floor((adjLon % 20) / 2));
    out += String(Math.floor(adjLat % 10));
    if (precision >= 6) {
      out += String.fromCharCode(97 + Math.floor(((adjLon % 2) / 2) * 24));
      out += String.fromCharCode(97 + Math.floor(((adjLat % 1) / 1) * 24));
    }
    return out;
  }

  /** Approximate sunrise / sunset UTC for lat/lon on a given UTC date (civil −0.833°). */
  function qthSunTimes(lat, lon, when) {
    when = when || new Date();
    var rad = Math.PI / 180;
    var day = new Date(Date.UTC(when.getUTCFullYear(), when.getUTCMonth(), when.getUTCDate()));
    var n = Math.floor((day.getTime() - Date.UTC(when.getUTCFullYear(), 0, 0)) / 86400000);
    function forKind(rise) {
      var lngHour = lon / 15;
      var t = rise ? (n + ((6 - lngHour) / 24)) : (n + ((18 - lngHour) / 24));
      var M = (0.9856 * t) - 3.289;
      var L = M + (1.916 * Math.sin(M * rad)) + (0.020 * Math.sin(2 * M * rad)) + 282.634;
      L = ((L % 360) + 360) % 360;
      var RA = Math.atan(0.91764 * Math.tan(L * rad)) / rad;
      RA = ((RA % 360) + 360) % 360;
      var Lq = Math.floor(L / 90) * 90;
      var RAq = Math.floor(RA / 90) * 90;
      RA = (RA + (Lq - RAq)) / 15;
      var sinDec = 0.39782 * Math.sin(L * rad);
      var cosDec = Math.cos(Math.asin(sinDec));
      var cosH = (Math.cos(90.833 * rad) - (sinDec * Math.sin(lat * rad))) / (cosDec * Math.cos(lat * rad));
      if (cosH > 1 || cosH < -1) return null;
      var H = rise ? (360 - Math.acos(cosH) / rad) : (Math.acos(cosH) / rad);
      H /= 15;
      var T = H + RA - (0.06571 * t) - 6.622;
      var UT = ((T - lngHour) % 24 + 24) % 24;
      var ms = day.getTime() + UT * 3600000;
      return new Date(ms);
    }
    return { rise: forKind(true), set: forKind(false) };
  }

  function qthFmtUtc(d) {
    if (!d || !(d instanceof Date) || isNaN(d.getTime())) return "—";
    var hh = d.getUTCHours();
    var mm = d.getUTCMinutes();
    return (hh < 10 ? "0" : "") + hh + ":" + (mm < 10 ? "0" : "") + mm + " UTC";
  }

  function qthFieldsHaveObs() {
    var lat = parseFloat(($("bs-qth-lat") || {}).value);
    var lon = parseFloat(($("bs-qth-lon") || {}).value);
    return lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
  }

  function qthApplyObs(o) {
    if (!o || !isFinite(o.lat) || !isFinite(o.lon)) return;
    if ($("bs-qth-lat")) $("bs-qth-lat").value = o.lat;
    if ($("bs-qth-lon")) $("bs-qth-lon").value = o.lon;
  }

  function qthLoadFields() {
    var saved = satObsFromToolboxStorage();
    if (saved) {
      qthApplyObs(saved);
      return;
    }
    if (qthFieldsHaveObs()) return;
    var owrx = moreObsFromStorage();
    if (owrx) {
      qthApplyObs(owrx);
      return;
    }
    owrxEnsureReceiverObs(function (obs) {
      if (!obs || satObsFromToolboxStorage() || qthFieldsHaveObs()) return;
      qthApplyObs(obs);
      try { qthPaint(); } catch (eP) {}
    });
  }

  function qthPaint() {
    var host = $("bs-qth-host");
    if (!host) return;
    var lat = parseFloat(($("bs-qth-lat") || {}).value);
    var lon = parseFloat(($("bs-qth-lon") || {}).value);
    var now = new Date();
    var utc = now.toISOString().replace("T", " ").replace(/\.\d+Z$/, " UTC");
    var local = now.toLocaleString(undefined, { hour12: false });
    if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) {
      host.innerHTML =
        '<div class="bs-qth-grid">' +
        "<div><span>UTC</span><b>" + escapeHtml(utc) + "</b></div>" +
        "<div><span>Local</span><b>" + escapeHtml(local) + "</b></div>" +
        "</div>" +
        '<p class="bs-empty">Enter lat/lon (or set them on Sats) and Save.</p>';
      return;
    }
    var grid = qthMaidenhead(lat, lon, 6);
    var sun = qthSunTimes(lat, lon, now);
    host.innerHTML =
      '<div class="bs-qth-grid">' +
      "<div><span>Grid</span><b>" + escapeHtml(grid) + "</b></div>" +
      "<div><span>UTC</span><b>" + escapeHtml(utc) + "</b></div>" +
      "<div><span>Local</span><b>" + escapeHtml(local) + "</b></div>" +
      "<div><span>Sunrise</span><b>" + escapeHtml(qthFmtUtc(sun.rise)) + "</b></div>" +
      "<div><span>Sunset</span><b>" + escapeHtml(qthFmtUtc(sun.set)) + "</b></div>" +
      "<div><span>Lat / Lon</span><b>" + escapeHtml(lat.toFixed(4) + " / " + lon.toFixed(4)) + "</b></div>" +
      "</div>";
  }

  function qthOnTab() {
    qthLoadFields();
    qthPaint();
    qthStopTimer();
    qthTimer = setInterval(function () {
      var pane = $("bs-tab-more");
      var sub = $("bs-more-qth");
      if (!pane || !pane.classList.contains("bs-tab-on")) return;
      if (!sub || !sub.classList.contains("bs-more-sub-on")) return;
      qthPaint();
    }, 1000);
  }

  function bindQthTab() {
    var root = $("bs-more-qth");
    if (!root || root._bsQthWired) return;
    root._bsQthWired = true;
    if ($("bs-qth-save")) {
      $("bs-qth-save").onclick = function () {
        var lat = parseFloat(($("bs-qth-lat") || {}).value);
        var lon = parseFloat(($("bs-qth-lon") || {}).value);
        if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) {
          setStatus("QTH needs valid lat/lon.");
          return;
        }
        var alt = 0;
        try {
          var prev = JSON.parse(window.localStorage.getItem("owrx_toolbox_sat_obs_v1") || "null");
          if (prev && isFinite(prev.alt)) alt = Number(prev.alt);
        } catch (e) {}
        try {
          window.localStorage.setItem("owrx_toolbox_sat_obs_v1", JSON.stringify({ lat: lat, lon: lon, alt: alt }));
        } catch (eS) {}
        try {
          if ($("bs-sat-lat")) $("bs-sat-lat").value = lat;
          if ($("bs-sat-lon")) $("bs-sat-lon").value = lon;
        } catch (eF) {}
        qthPaint();
        setStatus("QTH saved (" + qthMaidenhead(lat, lon, 6) + ").");
      };
    }
    ["bs-qth-lat", "bs-qth-lon"].forEach(function (id) {
      var el = $(id);
      if (el) el.addEventListener("input", function () { qthPaint(); });
    });
  }

  /* News / custom feeds — RSS via same-origin proxy, then CORS helpers (rss2json often blocked). */
  function toolboxRssSameOriginUrl(feedUrl) {
    try {
      var u = new URL("/owrx-toolbox-rss", window.location.origin);
      u.searchParams.set("url", String(feedUrl || "").trim());
      return u.href;
    } catch (eU) {
      return "";
    }
  }

  function toolboxParseRssXml(xmlText) {
    var items = [];
    try {
      var doc = new DOMParser().parseFromString(String(xmlText || ""), "text/xml");
      var nodes = doc.querySelectorAll("item");
      if (!nodes.length) nodes = doc.querySelectorAll("entry");
      Array.prototype.forEach.call(nodes, function (node) {
        var titleEl = node.querySelector("title");
        var title = titleEl ? String(titleEl.textContent || "").replace(/\s+/g, " ").trim() : "";
        var link = "";
        var linkEl = node.querySelector("link[href]") || node.querySelector("link");
        if (linkEl) link = linkEl.getAttribute("href") || String(linkEl.textContent || "").trim();
        if (!link) {
          var guid = node.querySelector("guid, id");
          if (guid) link = String(guid.textContent || "").trim();
        }
        var pubEl = node.querySelector("pubDate, published, updated, date");
        var pubDate = pubEl ? String(pubEl.textContent || "").trim() : "";
        if (title) items.push({ title: title, link: link, pubDate: pubDate });
      });
    } catch (eP) {}
    return items;
  }

  function toolboxNormalizeRssItems(rawItems, fallbackUrl) {
    return (rawItems || []).map(function (it) {
      var when = String(it.pubDate || it.published || it.updated || "").replace(/ \+0000$/, "").slice(0, 22);
      return {
        title: String(it.title || "Untitled").replace(/\s+/g, " ").trim(),
        link: String(it.link || it.url || fallbackUrl || ""),
        when: when
      };
    }).filter(function (it) { return it.title; });
  }

  function toolboxFetchRssJson(feedUrl) {
    feedUrl = String(feedUrl || "").trim();
    function fromSameOrigin() {
      var api = toolboxRssSameOriginUrl(feedUrl);
      if (!api) return Promise.reject(new Error("no-origin"));
      return fetch(api, { cache: "no-store", credentials: "same-origin" })
        .then(function (r) {
          if (!r.ok) throw new Error("http");
          return r.json();
        })
        .then(function (data) {
          if (!data || data.status !== "ok" || !Array.isArray(data.items)) throw new Error("bad");
          return data.items;
        });
    }
    function fromAllOrigins() {
      var ao = "https://api.allorigins.win/raw?url=" + encodeURIComponent(feedUrl);
      return fetch(ao, { cache: "no-store" })
        .then(function (r) {
          if (!r.ok) throw new Error("http");
          return r.text();
        })
        .then(function (txt) {
          var items = toolboxParseRssXml(txt);
          if (!items.length) throw new Error("empty");
          return items;
        });
    }
    function fromRss2Json() {
      var api = "https://api.rss2json.com/v1/api.json?rss_url=" + encodeURIComponent(feedUrl);
      return fetch(api, { cache: "no-store" })
        .then(function (r) {
          if (!r.ok) throw new Error("http");
          return r.json();
        })
        .then(function (data) {
          if (!data || data.status !== "ok") throw new Error("bad");
          return data.items || [];
        });
    }
    return fromSameOrigin()
      .catch(function () { return fromAllOrigins(); })
      .catch(function () { return fromRss2Json(); });
  }

  var NEWS_FEEDS = {
    arrl: { name: "ARRL", url: "https://www.arrl.org/news/rss" },
    rsgb: { name: "RSGB", url: "https://rsgb.org/main/feed/" },
    amsat: { name: "AMSAT", url: "https://www.amsat.org/feed/" },
    amsatuk: { name: "AMSAT-UK", url: "https://amsat-uk.org/feed/" },
    newsline: { name: "Newsline", url: "https://www.arnewsline.org/news?format=rss" },
    dxworld: { name: "DX World", url: "https://www.dx-world.net/feed/" },
    rtlsdr: { name: "RTL-SDR", url: "https://www.rtl-sdr.com/feed/" },
    arcom: { name: "AR.com", url: "https://www.amateurradio.com/feed/" }
  };
  var newsFeedId = "arrl";
  var newsCache = {};
  var newsBusy = false;
  var newsError = "";
  var newsGen = 0;

  function newsPaintFeedUrls() {
    var feed = NEWS_FEEDS[newsFeedId] || NEWS_FEEDS.arrl;
    var urlA = $("bs-news-feed-url");
    var line = $("bs-news-feed-url-line");
    if (urlA && feed) {
      urlA.href = feed.url;
      urlA.textContent = feed.url;
      urlA.title = feed.name + " RSS";
    }
    if (line) line.hidden = !feed;
  }

  function newsPaint() {
    var host = $("bs-news-list");
    var meta = $("bs-news-meta");
    var btn = $("bs-news-refresh");
    var chips = $("bs-news-feeds");
    newsPaintFeedUrls();
    if (btn) {
      btn.disabled = !!newsBusy;
      btn.textContent = newsBusy ? "Refreshing…" : "Refresh";
    }
    if (chips) {
      Array.prototype.forEach.call(chips.querySelectorAll("[data-news-feed]"), function (c) {
        var id = c.getAttribute("data-news-feed");
        c.classList.toggle("bs-on", id === newsFeedId);
        var f = NEWS_FEEDS[id];
        if (f) c.title = f.name + " — " + f.url;
      });
    }
    var pack = newsCache[newsFeedId];
    if (meta) {
      meta.textContent = newsBusy
        ? "refreshing…"
        : (pack && pack.at ? ("updated " + trafficLogAgo(pack.at)) : "");
    }
    if (!host) return;
    var items = (pack && pack.items) || [];
    if (!items.length) {
      host.innerHTML = '<p class="bs-empty">' +
        escapeHtml(newsError || (newsBusy ? "Loading headlines…" : "No headlines yet — try Refresh.")) +
        "</p>";
      return;
    }
    host.innerHTML = items.map(function (it) {
      return '<a class="bs-more-row bs-link-row" href="' + escapeHtml(it.link) +
        '" target="_blank" rel="noopener noreferrer" title="' + escapeHtml(it.title) + '">' +
        '<span class="bs-more-name">' + escapeHtml(it.title) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(it.when || "") + "</span>" +
        "</a>";
    }).join("");
  }

  function newsEnsure(force) {
    if (!moreNetworkAllowed("news")) {
      newsError = "Network budget blocked More fetches.";
      newsPaint();
      return;
    }
    var feed = NEWS_FEEDS[newsFeedId] || NEWS_FEEDS.arrl;
    var pack = newsCache[newsFeedId];
    if (!force && pack && pack.at && Date.now() - pack.at < 15 * 60 * 1000) {
      newsError = "";
      newsPaint();
      return;
    }
    if (newsBusy && !force) return;
    var gen = ++newsGen;
    newsBusy = true;
    newsError = "";
    newsPaint();
    toolboxFetchRssJson(feed.url)
      .then(function (raw) {
        if (gen !== newsGen) return;
        var items = toolboxNormalizeRssItems(raw, feed.url).slice(0, 12);
        newsCache[newsFeedId] = { at: Date.now(), items: items };
        newsBusy = false;
        newsError = items.length ? "" : "Feed was empty.";
        newsPaint();
      })
      .catch(function () {
        if (gen !== newsGen) return;
        newsBusy = false;
        newsError = "News feed did not answer — try Refresh (rss2json is often blocked; use this receiver’s /owrx-toolbox-rss proxy when installed).";
        newsPaint();
      });
  }

  function newsOnTab() { newsEnsure(false); }

  /* Custom feeds — localStorage + rss2json (like News). */
  function customFeedHeadlinesEmptyMsg(busy) {
    if (busy) return "Loading headlines…";
    return "No headlines yet — press the Refresh button in this box (not your browser F5 / Ctrl+R reload).";
  }

  var customFeedsList = [];
  var customFeedPick = "";
  var customFeedCache = {};
  var customFeedBusy = false;
  var customFeedBusyId = "";
  var customFeedError = "";
  var customFeedGen = 0;

  function customFeedUrlOk(url) {
    try {
      var u = new URL(String(url || "").trim());
      return u.protocol === "http:" || u.protocol === "https:";
    } catch (eU) { return false; }
  }

  function customFeedsLoad() {
    try {
      var raw = JSON.parse(window.localStorage.getItem("owrx_toolbox_custom_feeds_v1") || "[]");
      customFeedsList = Array.isArray(raw) ? raw.filter(function (f) {
        return f && f.id && f.name && customFeedUrlOk(f.url);
      }) : [];
    } catch (e) { customFeedsList = []; }
    if (!customFeedPick || !customFeedsList.some(function (f) { return f.id === customFeedPick; })) {
      customFeedPick = customFeedsList.length ? customFeedsList[0].id : "";
    }
    try {
      var saved = extraOn("rememberSubs") ? window.localStorage.getItem("owrx_toolbox_cfeed_sub_v1") : null;
      if (saved && customFeedsList.some(function (f) { return f.id === saved; })) customFeedPick = saved;
    } catch (ePick) {}
  }

  function setCustomFeedSub(id, opts) {
    opts = opts || {};
    customFeedsLoad();
    if (!id || !customFeedsList.some(function (f) { return f.id === id; })) return;
    if (id !== customFeedPick) customFeedError = "";
    customFeedPick = id;
    if (!opts.skipSave) {
      try {
        if (extraOn("rememberSubs")) window.localStorage.setItem("owrx_toolbox_cfeed_sub_v1", id);
      } catch (eLs) {}
    }
    customFeedsPaintList();
    if (!opts.skipFetch) customFeedsEnsure(false);
  }

  function customFeedsSave() {
    try {
      window.localStorage.setItem("owrx_toolbox_custom_feeds_v1", JSON.stringify(customFeedsList.slice(0, 24)));
    } catch (e) {}
  }

  function customFeedsRemoveById(fid) {
    if (!fid) return;
    customFeedsLoad();
    var i = -1;
    customFeedsList.forEach(function (f, ix) { if (f.id === fid) i = ix; });
    if (i < 0) return;
    customFeedsList.splice(i, 1);
    delete customFeedCache[fid];
    customFeedsSave();
    var stack = $("bs-cfeed-stack");
    if (stack) stack.removeAttribute("data-cfeed-sig");
    if (customFeedPick === fid) {
      customFeedPick = customFeedsList.length ? customFeedsList[0].id : "";
    }
    customFeedsPaintList();
    setStatus("Feed removed.");
  }

  function customFeedsPaintPaneList(host, feedId) {
    if (!host) return;
    var pack = customFeedCache[feedId];
    var busyHere = customFeedBusy && customFeedBusyId === feedId;
    var errHere = feedId === customFeedPick ? customFeedError : "";
    var items = (pack && pack.items) || [];
    if (!items.length) {
      host.innerHTML = '<p class="bs-empty">' +
        escapeHtml(errHere || customFeedHeadlinesEmptyMsg(busyHere)) +
        "</p>";
      return;
    }
    host.innerHTML = items.map(function (it) {
      return '<a class="bs-more-row bs-link-row" href="' + escapeHtml(it.link) +
        '" target="_blank" rel="noopener noreferrer" title="' + escapeHtml(it.title) + '">' +
        '<span class="bs-more-name">' + escapeHtml(it.title) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(it.when || "") + "</span>" +
        "</a>";
    }).join("");
  }

  function customFeedsPaintSubs() {
    var subs = $("bs-cfeed-subs");
    var stack = $("bs-cfeed-stack");
    if (!subs || !stack) return;
    var sig = customFeedsList.map(function (f) { return f.id + ":" + f.name; }).join("|");
    if (stack.getAttribute("data-cfeed-sig") !== sig) {
      stack.setAttribute("data-cfeed-sig", sig);
      subs.innerHTML = "";
      stack.innerHTML = "";
      if (customFeedsList.length > 1) {
        subs.hidden = false;
        customFeedsList.forEach(function (f) {
          var btn = document.createElement("button");
          btn.type = "button";
          btn.className = "bs-cfeed-sub";
          btn.setAttribute("data-cfeed-sub", f.id);
          btn.setAttribute("role", "tab");
          btn.setAttribute("aria-selected", "false");
          btn.textContent = f.name;
          btn.title = f.name + " — " + f.url;
          subs.appendChild(btn);
        });
      } else {
        subs.hidden = true;
      }
      if (!customFeedsList.length) {
        stack.innerHTML = '<p class="bs-empty">Add an RSS URL above.</p>';
      } else {
        customFeedsList.forEach(function (f) {
          var pane = document.createElement("div");
          pane.className = "bs-cfeed-subpane";
          pane.setAttribute("data-cfeed-sub", f.id);
          pane.setAttribute("role", "tabpanel");
          pane.innerHTML =
            '<div class="bs-more-list bs-link-list" data-cfeed-list="' + escapeHtml(f.id) + '"></div>';
          stack.appendChild(pane);
        });
      }
    }
    if (customFeedsList.length > 1) {
      Array.prototype.forEach.call(subs.querySelectorAll(".bs-cfeed-sub"), function (btn) {
        var id = btn.getAttribute("data-cfeed-sub");
        var on = id === customFeedPick;
        btn.classList.toggle("bs-cfeed-sub-on", on);
        btn.setAttribute("aria-selected", on ? "true" : "false");
      });
    }
    Array.prototype.forEach.call(stack.querySelectorAll(".bs-cfeed-subpane"), function (pane) {
      var id = pane.getAttribute("data-cfeed-sub");
      var on = customFeedsList.length === 1 ? true : id === customFeedPick;
      pane.classList.toggle("bs-cfeed-sub-on", on);
      if (on) pane.removeAttribute("hidden");
      else pane.setAttribute("hidden", "");
    });
    customFeedsList.forEach(function (f) {
      var host = stack.querySelector('[data-cfeed-list="' + f.id + '"]');
      customFeedsPaintPaneList(host, f.id);
    });
    var urlLine = $("bs-cfeed-active-url");
    var activeFeed = customFeedsList.filter(function (f) { return f.id === customFeedPick; })[0];
    if (urlLine) {
      if (activeFeed) {
        urlLine.hidden = false;
        urlLine.innerHTML = "RSS for this feed: <a href=\"" + escapeHtml(activeFeed.url) +
          "\" target=\"_blank\" rel=\"noopener noreferrer\">" + escapeHtml(activeFeed.url) + "</a>";
      } else {
        urlLine.hidden = true;
        urlLine.innerHTML = "";
      }
    }
  }

  function customFeedsPaintList() {
    var meta = $("bs-cfeed-meta");
    var btn = $("bs-cfeed-refresh");
    var rm = $("bs-cfeed-remove");
    customFeedsLoad();
    if (btn) {
      btn.disabled = !!customFeedBusy || !customFeedPick;
      btn.textContent = customFeedBusy && customFeedBusyId === customFeedPick ? "Refreshing…" : "Refresh";
    }
    if (rm) rm.disabled = !customFeedPick;
    var pack = customFeedPick ? customFeedCache[customFeedPick] : null;
    if (meta) {
      meta.textContent = !customFeedPick
        ? ""
        : (customFeedBusy && customFeedBusyId === customFeedPick
          ? "refreshing…"
          : (pack && pack.at ? ("updated " + trafficLogAgo(pack.at)) : ""));
    }
    customFeedsPaintSubs();
  }

  function customFeedsEnsure(force) {
    customFeedsLoad();
    if (!customFeedPick) {
      customFeedError = "";
      customFeedsPaintList();
      return;
    }
    if (!moreNetworkAllowed("myfeeds")) {
      customFeedError = "Network budget blocked More fetches.";
      customFeedsPaintList();
      return;
    }
    var fetchId = customFeedPick;
    var feed = customFeedsList.filter(function (f) { return f.id === fetchId; })[0];
    if (!feed) return;
    var pack = customFeedCache[fetchId];
    if (!force && pack && pack.at && Date.now() - pack.at < 15 * 60 * 1000) {
      customFeedError = "";
      customFeedsPaintList();
      return;
    }
    if (customFeedBusy && !force && customFeedBusyId === fetchId) return;
    var gen = ++customFeedGen;
    customFeedBusy = true;
    customFeedBusyId = fetchId;
    if (fetchId === customFeedPick) customFeedError = "";
    customFeedsPaintList();
    var feedUrl = String(feed.url || "").trim();
    toolboxFetchRssJson(feedUrl)
      .then(function (raw) {
        if (gen !== customFeedGen) return;
        var items = toolboxNormalizeRssItems(raw, feedUrl).slice(0, 16);
        customFeedCache[fetchId] = { at: Date.now(), items: items };
        customFeedBusy = false;
        customFeedBusyId = "";
        if (fetchId === customFeedPick) {
          customFeedError = items.length ? "" : "Feed was empty.";
        }
        customFeedsPaintList();
      })
      .catch(function () {
        if (gen !== customFeedGen) return;
        customFeedBusy = false;
        customFeedBusyId = "";
        if (fetchId === customFeedPick) {
          customFeedError = "Feed did not answer — check URL or use a receiver with /owrx-toolbox-rss installed.";
        }
        customFeedsPaintList();
      });
  }

  function customFeedsOnTab() {
    customFeedsLoad();
    customFeedsPaintList();
    customFeedsEnsure(false);
    bindLightIoPair("bs-cfeed-export", "bs-cfeed-import", "bs-cfeed-file",
      function () {
        customFeedsLoad();
        return { kind: "owrx_toolbox_custom_feeds", when: Date.now(), feeds: customFeedsList };
      },
      function (text) {
        var o = JSON.parse(String(text || "").trim());
        var list = (o && o.feeds) || (Array.isArray(o) ? o : []);
        customFeedsLoad();
        var n = 0;
        list.forEach(function (row) {
          if (!row || !row.name || !customFeedUrlOk(row.url)) return;
          customFeedsList.push({
            id: "f" + Date.now().toString(36) + Math.random().toString(36).slice(2, 5),
            name: String(row.name).slice(0, 40),
            url: String(row.url).trim().slice(0, 512)
          });
          n++;
        });
        if (customFeedsList.length > 24) customFeedsList = customFeedsList.slice(0, 24);
        customFeedsSave();
        if (!customFeedPick && customFeedsList.length) customFeedPick = customFeedsList[0].id;
        customFeedsPaintList();
        setStatus(n ? ("Imported " + n + " feed(s).") : "No feeds in that file.");
      },
      "toolbox-feeds.json", "application/json", "Import feeds");
  }

  function bindCustomFeedsTab() {
    var root = $("bs-more-myfeeds");
    if (!root || root._bsCfeedWired) return;
    root._bsCfeedWired = true;
    if ($("bs-cfeed-add")) {
      $("bs-cfeed-add").onclick = function () {
        var name = (($("bs-cfeed-name") || {}).value || "").trim();
        var url = (($("bs-cfeed-url") || {}).value || "").trim();
        if (!name || !customFeedUrlOk(url)) {
          setStatus("Feed needs a name and https URL.");
          return;
        }
        customFeedsLoad();
        var id = "f" + Date.now().toString(36) + Math.random().toString(36).slice(2, 5);
        customFeedsList.push({ id: id, name: name.slice(0, 40), url: url.slice(0, 512) });
        if (customFeedsList.length > 24) customFeedsList = customFeedsList.slice(0, 24);
        customFeedsSave();
        setCustomFeedSub(id, { skipSave: true, skipFetch: true });
        if ($("bs-cfeed-name")) $("bs-cfeed-name").value = "";
        if ($("bs-cfeed-url")) $("bs-cfeed-url").value = "";
        customFeedsEnsure(true);
        try {
          if (extraOn("rememberSubs")) window.localStorage.setItem("owrx_toolbox_cfeed_sub_v1", id);
        } catch (eLs) {}
        setStatus("Feed saved.");
      };
    }
    if ($("bs-cfeed-refresh")) {
      $("bs-cfeed-refresh").onclick = function () { customFeedsEnsure(true); };
    }
    if ($("bs-cfeed-remove")) {
      $("bs-cfeed-remove").onclick = function () {
        customFeedsLoad();
        customFeedsRemoveById(customFeedPick);
      };
    }
    root.addEventListener("click", function (ev) {
      var t = ev.target;
      if (!t || !t.closest) return;
      var sub = t.closest(".bs-cfeed-sub");
      if (sub && sub.getAttribute("data-cfeed-sub")) {
        setCustomFeedSub(sub.getAttribute("data-cfeed-sub"));
      }
    });
  }

  function bindNewsTab() {
    var root = $("bs-more-news");
    if (!root || root._bsNewsWired) return;
    root._bsNewsWired = true;
    if ($("bs-news-refresh")) {
      $("bs-news-refresh").onclick = function () { newsEnsure(true); };
    }
    if ($("bs-news-feeds")) {
      $("bs-news-feeds").onclick = function (ev) {
        var btn = ev.target && ev.target.closest && ev.target.closest("[data-news-feed]");
        if (!btn) return;
        newsFeedId = btn.getAttribute("data-news-feed") || "arrl";
        newsEnsure(false);
      };
    }
  }

