  /* Explore band-hop / “you’re in …” still use R1-style edges. */
  var PLAN_BANDS = PLAN_REGIONS.eu.bands;
  var PLAN_REGION_ORDER = ["uk", "eu", "usa", "ca", "au", "jp", "za"];
  var planRegionId = "eu";

  function planDefaultRegion() {
    try {
      var obs = moreObsFromStorage();
      if (obs && isFinite(obs.lat) && isFinite(obs.lon)) {
        if (obs.lat >= 49 && obs.lat <= 61 && obs.lon >= -12 && obs.lon <= 3) return "uk";
        if (obs.lat >= 24 && obs.lat <= 46 && obs.lon >= 125 && obs.lon <= 150) return "jp";
        if (obs.lat <= -10 && obs.lon >= 110 && obs.lon <= 160) return "au";
        if (obs.lat >= -40 && obs.lat <= -20 && obs.lon >= 15 && obs.lon <= 35) return "za";
        if (obs.lat >= 41 && obs.lon >= -141 && obs.lon <= -52) return "ca";
        if (obs.lon >= -170 && obs.lon <= -50) return "usa";
        if (obs.lon >= -25 && obs.lon <= 60) return "eu";
      }
    } catch (e) {}
    return "eu";
  }

  function planEnsureRegionChips() {
    var host = $("bs-plan-regions");
    if (!host || host.getAttribute("data-bs-ready") === "1") return;
    host.setAttribute("data-bs-ready", "1");
    host.innerHTML = PLAN_REGION_ORDER.map(function (id) {
      var r = PLAN_REGIONS[id];
      if (!r) return "";
      return '<button type="button" class="bs-tiny bs-log-chip" data-plan-region="' + id +
        '" title="' + escapeHtml(r.title) + '">' + escapeHtml(r.lab) + "</button>";
    }).join("");
  }

  function planRender() {
    planEnsureRegionChips();
    if (!PLAN_REGIONS[planRegionId]) planRegionId = planDefaultRegion();
    var reg = PLAN_REGIONS[planRegionId] || PLAN_REGIONS.eu;
    var chips = $("bs-plan-regions");
    if (chips) {
      Array.prototype.forEach.call(chips.querySelectorAll("[data-plan-region]"), function (c) {
        c.classList.toggle("bs-on", c.getAttribute("data-plan-region") === planRegionId);
      });
    }
    var meta = $("bs-plan-meta");
    if (meta) meta.textContent = reg.blurb || "";
    var host = $("bs-plan-list");
    if (!host) return;
    host.innerHTML = (reg.bands || []).map(function (b) {
      var mid = (b.lo + b.hi) / 2;
      var status = (b.modes || b.note || "") + (b.power ? (" · " + b.power) : "");
      var digs = (b.lo < 1 || (b.hi - b.lo) < 0.05) ? 4 : (b.lo >= 100 ? 1 : 3);
      return '<article class="bs-more-row" data-plan-mhz="' + mid +
        '" title="Tune near centre of ' + escapeHtml(b.name) + ' · ' + escapeHtml(reg.lab) + '.">' +
        '<span class="bs-more-name">' + escapeHtml(b.name) + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(b.lo.toFixed(digs) + "–" + b.hi.toFixed(digs)) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(status) + "</span>" +
        "</article>";
    }).join("");
  }

  function planOnTab() {
    if (!PLAN_REGIONS[planRegionId]) {
      try {
        var raw = window.localStorage.getItem("owrx_toolbox_plan_region_v1");
        if (raw && PLAN_REGIONS[raw]) planRegionId = raw;
        else planRegionId = planDefaultRegion();
      } catch (e) {
        planRegionId = planDefaultRegion();
      }
    }
    planRender();
  }

  function bindPlanTab() {
    var root = $("bs-more-plan");
    if (!root || root._bsPlanWired) return;
    root._bsPlanWired = true;
    root.addEventListener("click", function (ev) {
      var chip = ev.target && ev.target.closest && ev.target.closest("[data-plan-region]");
      if (chip && root.contains(chip)) {
        planRegionId = chip.getAttribute("data-plan-region") || "eu";
        try { window.localStorage.setItem("owrx_toolbox_plan_region_v1", planRegionId); } catch (e) {}
        planRender();
        return;
      }
      var row = ev.target && ev.target.closest && ev.target.closest("[data-plan-mhz]");
      if (!row || !root.contains(row)) return;
      moreTune(parseFloat(row.getAttribute("data-plan-mhz")) * 1e6, "usb", "Plan");
    });
  }

  /* Path — grid distance / bearing. */
  function qthGridToLatLon(grid) {
    grid = String(grid || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
    if (grid.length < 4) return null;
    var lon = (grid.charCodeAt(0) - 65) * 20 + parseInt(grid.charAt(2), 10) * 2;
    var lat = (grid.charCodeAt(1) - 65) * 10 + parseInt(grid.charAt(3), 10);
    lon -= 180;
    lat -= 90;
    if (grid.length >= 6) {
      lon += (grid.charCodeAt(4) - 65) * (2 / 24) + (1 / 24);
      lat += (grid.charCodeAt(5) - 65) * (1 / 24) + (0.5 / 24);
    } else {
      lon += 1;
      lat += 0.5;
    }
    if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) return null;
    return { lat: lat, lon: lon };
  }

  function pathHaversineKm(a, b) {
    var R = 6371.0088;
    var r = Math.PI / 180;
    var dLat = (b.lat - a.lat) * r;
    var dLon = (b.lon - a.lon) * r;
    var s = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(a.lat * r) * Math.cos(b.lat * r) * Math.sin(dLon / 2) * Math.sin(dLon / 2);
    return 2 * R * Math.asin(Math.min(1, Math.sqrt(s)));
  }

  function pathBearingDeg(a, b) {
    var r = Math.PI / 180;
    var dLon = (b.lon - a.lon) * r;
    var y = Math.sin(dLon) * Math.cos(b.lat * r);
    var x = Math.cos(a.lat * r) * Math.sin(b.lat * r) -
      Math.sin(a.lat * r) * Math.cos(b.lat * r) * Math.cos(dLon);
    return ((Math.atan2(y, x) * 180 / Math.PI) + 360) % 360;
  }

  function pathPaint() {
    var host = $("bs-path-host");
    if (!host) return;
    var obs = moreObsFromStorage();
    var grid = (($("bs-path-grid") || {}).value || "").trim().toUpperCase();
    if (!obs) {
      host.innerHTML = '<p class="bs-empty">Set lat/lon on QTH or Sats first.</p>';
      return;
    }
    if (!grid) {
      host.innerHTML = '<p class="bs-empty">Enter a target grid (e.g. JO02 or FN42ab).</p>';
      return;
    }
    var tgt = qthGridToLatLon(grid);
    if (!tgt) {
      host.innerHTML = '<p class="bs-empty">That does not look like a Maidenhead grid.</p>';
      return;
    }
    var km = pathHaversineKm(obs, tgt);
    var brg = pathBearingDeg(obs, tgt);
    var fromG = "";
    try { fromG = qthMaidenhead(obs.lat, obs.lon, 6); } catch (e) { fromG = "—"; }
    host.innerHTML =
      '<div class="bs-qth-grid">' +
      "<div><span>From</span><b>" + escapeHtml(fromG) + "</b></div>" +
      "<div><span>To</span><b>" + escapeHtml(grid) + "</b></div>" +
      "<div><span>Distance</span><b>" + escapeHtml(km.toFixed(0) + " km") + "</b></div>" +
      "<div><span>Bearing</span><b>" + escapeHtml(brg.toFixed(0) + "°") + "</b></div>" +
      "</div>";
  }

  function pathOnTab() { pathPaint(); }

  function bindPathTab() {
    var root = $("bs-more-path");
    if (!root || root._bsPathWired) return;
    root._bsPathWired = true;
    if ($("bs-path-go")) $("bs-path-go").onclick = function () { pathPaint(); };
    if ($("bs-path-grid")) {
      $("bs-path-grid").addEventListener("keydown", function (ev) {
        if (ev.key === "Enter") { ev.preventDefault(); pathPaint(); }
      });
    }
  }

  /* POTA spots. */
  var potaRows = [];
  var potaFetchedAt = 0;
  var potaError = "";
  var potaBusy = false;
  var potaGen = 0;

  function potaMode(m) {
    m = String(m || "").toUpperCase();
    if (m === "CW") return "cw";
    if (m === "FM" || m === "NFM") return "nfm";
    if (m === "AM") return "am";
    if (m === "LSB") return "lsb";
    return "usb";
  }

  function potaPaint() {
    var host = $("bs-pota-list");
    var meta = $("bs-pota-meta");
    var btn = $("bs-pota-refresh");
    if (btn) {
      btn.disabled = !!potaBusy;
      btn.textContent = potaBusy ? "Refreshing…" : "Refresh";
    }
    if (meta) {
      meta.textContent = potaBusy
        ? (potaFetchedAt ? ("updated " + trafficLogAgo(potaFetchedAt) + " · refreshing…") : "refreshing…")
        : (potaFetchedAt ? ("updated " + trafficLogAgo(potaFetchedAt) + " · " + potaRows.length + " spots") : "");
    }
    if (!host) return;
    if (!potaRows.length) {
      host.innerHTML = '<p class="bs-empty">' +
        escapeHtml(potaError || (potaBusy ? "Loading POTA…" : "No spots yet — try Refresh.")) + "</p>";
      return;
    }
    host.innerHTML = potaRows.map(function (s) {
      return '<article class="bs-more-row" data-pota-hz="' + s.hz + '" data-pota-mode="' + escapeHtml(s.mode) +
        '" title="' + escapeHtml(s.park + " · " + s.ref) + '">' +
        '<span class="bs-more-name">' + escapeHtml(s.call) + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(fmtMhz(s.hz)) + "</span>" +
        '<span class="bs-more-mode">' + escapeHtml(String(s.mode).toUpperCase()) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(s.ref + (s.park ? (" · " + s.park) : "")) + "</span>" +
        "</article>";
    }).join("");
  }

  function potaEnsure(force) {
    if (!moreNetworkAllowed("pota")) {
      potaError = "Network budget blocked More fetches.";
      potaPaint();
      return;
    }
    if (!force && potaFetchedAt && Date.now() - potaFetchedAt < 3 * 60 * 1000 && potaRows.length) {
      potaPaint();
      return;
    }
    if (potaBusy && !force) return;
    var gen = ++potaGen;
    potaBusy = true;
    potaError = "";
    potaPaint();
    fetch("https://api.pota.app/spot/activator", { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("http");
        return r.json();
      })
      .then(function (rows) {
        if (gen !== potaGen) return;
        var list = Array.isArray(rows) ? rows : [];
        potaRows = list.slice(0, 40).map(function (row) {
          var kHz = parseFloat(row && row.frequency);
          var hz = kHz > 0 ? Math.round(kHz * 1000) : 0;
          return {
            call: String((row && row.activator) || "?").toUpperCase(),
            hz: hz,
            mode: potaMode(row && row.mode),
            ref: String((row && row.reference) || ""),
            park: String((row && (row.name || row.parkName)) || "").slice(0, 48)
          };
        }).filter(function (s) { return s.hz > 0; });
        potaFetchedAt = Date.now();
        potaBusy = false;
        potaError = potaRows.length ? "" : "No activator spots right now.";
        potaPaint();
      })
      .catch(function () {
        if (gen !== potaGen) return;
        potaBusy = false;
        potaError = "POTA did not answer.";
        potaPaint();
      });
  }

  function potaOnTab() { potaEnsure(false); }

  function bindPotaTab() {
    var root = $("bs-more-pota");
    if (!root || root._bsPotaWired) return;
    root._bsPotaWired = true;
    if ($("bs-pota-refresh")) $("bs-pota-refresh").onclick = function () { potaEnsure(true); };
    root.addEventListener("click", function (ev) {
      var row = ev.target && ev.target.closest && ev.target.closest("[data-pota-hz]");
      if (!row || !root.contains(row)) return;
      moreTune(parseFloat(row.getAttribute("data-pota-hz")), row.getAttribute("data-pota-mode") || "usb", "POTA");
    });
  }

  /* Keys — static cheat sheet. */
  var KEYS_ROWS = [
    { key: "S", note: "Stop scan" },
    { key: "B", note: "Scan bookmarks" },
    { key: "H", note: "Hold / resume" },
    { key: "K / →", note: "Skip current" },
    { key: "←", note: "Previous bookmark (while scanning)" },
    { key: "D", note: "Detach Toolbox window" },
    { key: "M", note: "Minimal header" },
    { key: "S (title)", note: "Side dock on/off" },
    { key: "R (title)", note: "Hard refresh" },
    { key: "% (title)", note: "Reset side width" },
    { key: "?", note: "Help" }
  ];

  var Q_SIGNAL_ROWS = [
    { key: "QRL", note: "Are you busy?" },
    { key: "QRM", note: "Interference" },
    { key: "QRN", note: "Static / natural noise" },
    { key: "QRO", note: "Shall I increase power?" },
    { key: "QRP", note: "Shall I decrease power?" },
    { key: "QRT", note: "Stop sending" },
    { key: "QRZ", note: "Who is calling me?" },
    { key: "QSB", note: "Fading" },
    { key: "QSL", note: "Acknowledge / card" },
    { key: "QSO", note: "Contact" },
    { key: "QSY", note: "Change frequency" },
    { key: "QTH", note: "Location" }
  ];

  function keysRender() {
    var host = $("bs-keys-list");
    if (!host) return;
    var html = KEYS_ROWS.map(function (k) {
      return '<article class="bs-more-row" style="cursor:default">' +
        '<span class="bs-more-name">' + escapeHtml(k.key) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(k.note) + "</span>" +
        "</article>";
    }).join("");
    html += '<p class="bs-hint" style="margin:8px 0 4px">Common Q-signals</p>';
    html += Q_SIGNAL_ROWS.map(function (k) {
      return '<article class="bs-more-row" style="cursor:default">' +
        '<span class="bs-more-name">' + escapeHtml(k.key) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(k.note) + "</span>" +
        "</article>";
    }).join("");
    host.innerHTML = html;
  }

  function keysOnTab() { keysRender(); }

  function todayOnTab() { moreTodayRender(); }

  /* SOTA spots. */
  var sotaRows = [];
  var sotaFetchedAt = 0;
  var sotaError = "";
  var sotaBusy = false;
  var sotaGen = 0;

  function sotaPaint() {
    var host = $("bs-sota-list");
    var meta = $("bs-sota-meta");
    var btn = $("bs-sota-refresh");
    if (btn) {
      btn.disabled = !!sotaBusy;
      btn.textContent = sotaBusy ? "Refreshing…" : "Refresh";
    }
    if (meta) {
      meta.textContent = sotaBusy
        ? (sotaFetchedAt ? ("updated " + trafficLogAgo(sotaFetchedAt) + " · refreshing…") : "refreshing…")
        : (sotaFetchedAt ? ("updated " + trafficLogAgo(sotaFetchedAt) + " · " + sotaRows.length + " spots") : "");
    }
    if (!host) return;
    if (!sotaRows.length) {
      host.innerHTML = '<p class="bs-empty">' +
        escapeHtml(sotaError || (sotaBusy ? "Loading SOTA…" : "No spots yet — try Refresh.")) + "</p>";
      return;
    }
    host.innerHTML = sotaRows.map(function (s) {
      return '<article class="bs-more-row" data-sota-hz="' + s.hz + '" data-sota-mode="' + escapeHtml(s.mode) +
        '" title="' + escapeHtml(s.summit + " · " + s.ref) + '">' +
        '<span class="bs-more-name">' + escapeHtml(s.call) + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(fmtMhz(s.hz)) + "</span>" +
        '<span class="bs-more-mode">' + escapeHtml(String(s.mode).toUpperCase()) + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(s.ref + (s.summit ? (" · " + s.summit) : "")) + "</span>" +
        "</article>";
    }).join("");
  }

  function sotaEnsure(force) {
    if (!moreNetworkAllowed("sota")) {
      sotaError = "Network budget blocked More fetches.";
      sotaPaint();
      return;
    }
    if (!force && sotaFetchedAt && Date.now() - sotaFetchedAt < 3 * 60 * 1000 && sotaRows.length) {
      sotaPaint();
      return;
    }
    if (sotaBusy && !force) return;
    var gen = ++sotaGen;
    sotaBusy = true;
    sotaError = "";
    sotaPaint();
    fetch("https://api-db2.sota.org.uk/api/spots/20/all/0", { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("http");
        return r.json();
      })
      .then(function (rows) {
        if (gen !== sotaGen) return;
        var list = Array.isArray(rows) ? rows : [];
        sotaRows = list.slice(0, 30).map(function (row) {
          var mhz = parseFloat(row && row.frequency);
          var hz = 0;
          if (mhz > 0 && mhz < 1000) hz = Math.round(mhz * 1e6);
          else if (mhz >= 1000) hz = Math.round(mhz * 1000);
          return {
            call: String((row && (row.activatorCallsign || row.callsign)) || "?").toUpperCase(),
            hz: hz,
            mode: potaMode(row && row.mode),
            ref: String((row && row.summitCode) || ""),
            summit: String((row && row.summitName) || "").slice(0, 40)
          };
        }).filter(function (s) { return s.hz > 0; });
        sotaFetchedAt = Date.now();
        sotaBusy = false;
        sotaError = sotaRows.length ? "" : "No SOTA spots right now.";
        sotaPaint();
      })
      .catch(function () {
        if (gen !== sotaGen) return;
        sotaBusy = false;
        sotaError = "SOTA did not answer.";
        sotaPaint();
      });
  }

  function sotaOnTab() { sotaEnsure(false); }

  function bindSotaTab() {
    var root = $("bs-more-sota");
    if (!root || root._bsSotaWired) return;
    root._bsSotaWired = true;
    if ($("bs-sota-refresh")) $("bs-sota-refresh").onclick = function () { sotaEnsure(true); };
    root.addEventListener("click", function (ev) {
      var row = ev.target && ev.target.closest && ev.target.closest("[data-sota-hz]");
      if (!row || !root.contains(row)) return;
      moreTune(parseFloat(row.getAttribute("data-sota-hz")), row.getAttribute("data-sota-mode") || "usb", "SOTA");
    });
  }

  /* Moon — phase + rough altitude (local math). */
  function moonPaint() {
    var host = $("bs-moon-host");
    if (!host) return;
    var now = new Date();
    var jd = satJdFromDate ? satJdFromDate(now) : (now.getTime() / 86400000 + 2440587.5);
    var T = (jd - 2451545.0) / 36525;
    var Lp = (218.3164477 + 481267.88123421 * T) % 360;
    if (Lp < 0) Lp += 360;
    var D = (297.8501921 + 445267.1114034 * T) % 360;
    var M = (357.5291092 + 35999.0502909 * T) % 360;
    var Mp = (134.9633964 + 477198.8675055 * T) % 360;
    var rad = Math.PI / 180;
    var phaseAng = (D * rad);
    var illum = 0.5 * (1 - Math.cos(phaseAng));
    var age = ((Lp - ((280.46646 + 36000.76983 * T) % 360)) % 360 + 360) % 360 / 12.1907;
    var phaseName = "Waxing";
    if (illum < 0.03) phaseName = "New";
    else if (illum > 0.97) phaseName = "Full";
    else if (age > 14) phaseName = illum > 0.5 ? "Waning gibbous" : "Waning crescent";
    else phaseName = illum > 0.5 ? "Waxing gibbous" : "Waxing crescent";
    /* Rough ecliptic → equatorial → alt (low precision). */
    var ecl = (1.914666471 * Math.sin(M * rad) + Lp) * rad;
    var eps = (23.439291 - 0.0130042 * T) * rad;
    var dec = Math.asin(Math.sin(ecl) * Math.sin(eps));
    var ra = Math.atan2(Math.cos(eps) * Math.sin(ecl), Math.cos(ecl));
    var obs = moreObsFromStorage();
    var altStr = "—";
    var azStr = "—";
    if (obs) {
      var gst = satGstime ? satGstime(jd) : 0;
      var lst = gst + obs.lon * rad;
      var ha = lst - ra;
      var sinAlt = Math.sin(obs.lat * rad) * Math.sin(dec) + Math.cos(obs.lat * rad) * Math.cos(dec) * Math.cos(ha);
      var alt = Math.asin(Math.max(-1, Math.min(1, sinAlt))) / rad;
      var az = Math.atan2(
        -Math.sin(ha),
        Math.tan(dec) * Math.cos(obs.lat * rad) - Math.sin(obs.lat * rad) * Math.cos(ha)
      ) / rad;
      az = (az + 360) % 360;
      altStr = alt.toFixed(0) + "°";
      azStr = az.toFixed(0) + "°";
    }
    host.innerHTML =
      '<div class="bs-qth-grid">' +
      "<div><span>Phase</span><b>" + escapeHtml(phaseName) + "</b></div>" +
      "<div><span>Illum</span><b>" + escapeHtml(Math.round(illum * 100) + "%") + "</b></div>" +
      "<div><span>Altitude</span><b>" + escapeHtml(altStr) + "</b></div>" +
      "<div><span>Azimuth</span><b>" + escapeHtml(azStr) + "</b></div>" +
      "</div>" +
      (obs ? "" : '<p class="bs-empty">Set lat/lon on QTH for altitude / azimuth.</p>');
  }

