  function prefixLookup(call) {
    call = String(call || "").trim().toUpperCase().replace(/[^A-Z0-9\/]/g, "");
    if (!call) return null;
    var base = call.split("/")[0];
    var best = null;
    var bestLen = 0;
    var i, p, ent;
    for (i = 0; i < PREFIX_MAP.length; i++) {
      p = PREFIX_MAP[i][0];
      ent = PREFIX_MAP[i][1];
      if (base.indexOf(p) === 0 && p.length > bestLen) {
        bestLen = p.length;
        best = { prefix: p, entity: ent, call: base };
      }
    }
    return best;
  }

  var prefixRemoteCache = {};
  var prefixFetchGen = 0;
  var prefixBusy = false;
  var prefixInputTimer = 0;

  function prefixNormalizeCall(raw) {
    var s = String(raw || "").trim().toUpperCase().replace(/[^A-Z0-9\/]/g, "");
    if (!s) return "";
    var parts = s.split("/").filter(function (x) { return x; });
    var base = parts[0] || "";
    if (parts.length > 1) {
      var tail = parts[parts.length - 1];
      if (tail.length >= 3 && /[0-9]/.test(tail) && /[A-Z]/.test(tail)) base = tail;
    }
    return base;
  }

  function prefixCallValid(call) {
    call = String(call || "");
    if (call.length < 3 || call.length > 12) return false;
    if (!/[0-9]/.test(call) || !/[A-Z]/.test(call)) return false;
    return /^[A-Z0-9]+$/.test(call);
  }

  function prefixFetchRemote(call, done) {
    done = typeof done === "function" ? done : function () {};
    call = prefixNormalizeCall(call);
    if (!prefixCallValid(call)) {
      done(null);
      return;
    }
    if (prefixRemoteCache[call]) {
      done(prefixRemoteCache[call]);
      return;
    }
    if (!moreNetworkAllowed("prefix")) {
      done(null);
      return;
    }
    var gen = ++prefixFetchGen;
    prefixBusy = true;
    try { prefixPaint(); } catch (eP0) {}
    var callookP = fetch("https://callook.info/" + encodeURIComponent(call) + "/json", { cache: "no-store" })
      .then(function (r) { return r && r.ok ? r.json() : null; })
      .catch(function () { return null; });
    var qrzP = fetch("https://www.qrzcq.com/api/callinfo/" + encodeURIComponent(call), { cache: "no-store" })
      .then(function (r) { return r && r.ok ? r.json() : null; })
      .catch(function () { return null; });
    Promise.all([callookP, qrzP]).then(function (parts) {
      if (gen !== prefixFetchGen) return;
      prefixBusy = false;
      var ck = parts[0];
      var qz = parts[1];
      var merged = { call: call };
      if (ck && ck.status === "VALID") {
        merged.name = String(ck.name || "").trim();
        merged.licenseClass = ck.current && ck.current.operClass ? String(ck.current.operClass) : "";
        merged.licenseType = ck.type ? String(ck.type) : "";
        if (ck.location) {
          merged.grid = String(ck.location.gridsquare || "").toUpperCase();
          merged.lat = ck.location.latitude;
          merged.lon = ck.location.longitude;
        }
        if (ck.address) {
          var addr = [];
          if (ck.address.line1) addr.push(String(ck.address.line1).trim());
          if (ck.address.line2) addr.push(String(ck.address.line2).trim());
          merged.address = addr.join(", ");
        }
        if (ck.otherInfo) {
          merged.grant = ck.otherInfo.grantDate || "";
          merged.expiry = ck.otherInfo.expiryDate || "";
          merged.ulsUrl = ck.otherInfo.ulsUrl || "";
        }
        merged.fcc = true;
      }
      if (qz && qz.status === "OK" && qz.callinfo) {
        var ci = qz.callinfo;
        merged.country = ci.country ? String(ci.country) : "";
        merged.continent = ci.continent ? String(ci.continent) : "";
        merged.cq = ci.cq != null ? String(ci.cq) : "";
        merged.itu = ci.itu != null ? String(ci.itu) : "";
        merged.dxcc = ci.dxcc != null ? String(ci.dxcc) : "";
        merged.qrzcq = true;
      }
      if (merged.fcc || merged.qrzcq) {
        prefixRemoteCache[call] = merged;
      }
      done(merged.fcc || merged.qrzcq ? merged : null);
      try { prefixPaint(); } catch (eP1) {}
    }).catch(function () {
      if (gen !== prefixFetchGen) return;
      prefixBusy = false;
      done(null);
      try { prefixPaint(); } catch (eP2) {}
    });
  }

  function prefixRemoteHtml(call, remote) {
    if (!remote || (!remote.fcc && !remote.qrzcq)) return "";
    var rows = "";
    if (remote.name) {
      rows += "<div><span>Name</span><b>" + escapeHtml(remote.name) + "</b></div>";
    }
    if (remote.licenseClass || remote.licenseType) {
      rows += "<div><span>Licence</span><b>" + escapeHtml(
        [remote.licenseClass, remote.licenseType].filter(function (x) { return x; }).join(" · ")
      ) + "</b></div>";
    }
    if (remote.country) {
      rows += "<div><span>Country</span><b>" + escapeHtml(remote.country) + "</b></div>";
    }
    if (remote.continent) {
      rows += "<div><span>Continent</span><b>" + escapeHtml(remote.continent) + "</b></div>";
    }
    if (remote.grid) {
      rows += "<div><span>Grid</span><b>" + escapeHtml(remote.grid) + "</b></div>";
    }
    if (remote.cq || remote.itu) {
      rows += "<div><span>CQ / ITU</span><b>" + escapeHtml(
        [remote.cq ? ("CQ " + remote.cq) : "", remote.itu ? ("ITU " + remote.itu) : ""].filter(function (x) { return x; }).join(" · ")
      ) + "</b></div>";
    }
    if (remote.dxcc) {
      rows += "<div><span>DXCC</span><b>" + escapeHtml(remote.dxcc) + "</b></div>";
    }
    if (remote.address) {
      rows += "<div><span>Address</span><b>" + escapeHtml(remote.address) + "</b></div>";
    }
    if (remote.grant || remote.expiry) {
      rows += "<div><span>Grant / expiry</span><b>" + escapeHtml(
        [remote.grant, remote.expiry].filter(function (x) { return x; }).join(" → ")
      ) + "</b></div>";
    }
    var links = lookupLinkHtml("call", call, "Full lookup");
    if (remote.ulsUrl) {
      links += ' · <a class="bs-lookup" target="_blank" rel="noopener" href="' + escapeHtml(remote.ulsUrl) +
        '" title="FCC Universal Licensing System record.">FCC ULS</a>';
    }
    return (
      '<div class="bs-qth-grid bs-prefix-remote">' + rows + "</div>" +
      '<p class="bs-hint bs-prefix-links">' + links + "</p>"
    );
  }

  function prefixPaint() {
    var host = $("bs-prefix-host");
    var meta = $("bs-prefix-meta");
    if (!host) return;
    var raw = (($("bs-prefix-in") || {}).value || "").trim();
    if (!raw) {
      if (meta) meta.textContent = "";
      host.innerHTML = '<p class="bs-empty">Type a call or prefix (e.g. G4EA5, G4, VK3, W1AW).</p>';
      return;
    }
    var norm = prefixNormalizeCall(raw);
    var hit = prefixLookup(raw);
    var remote = norm && prefixRemoteCache[norm] ? prefixRemoteCache[norm] : null;
    if (meta) {
      if (!moreNetworkAllowed("prefix")) {
        meta.textContent = "Network off — local prefix table only.";
      } else if (prefixBusy) {
        meta.textContent = "Fetching licence info…";
      } else if (remote && (remote.fcc || remote.qrzcq)) {
        meta.textContent = (remote.fcc ? "FCC" : "") + (remote.fcc && remote.qrzcq ? " + " : "") + (remote.qrzcq ? "QRZCQ" : "");
      } else if (prefixCallValid(norm)) {
        meta.textContent = "No online match yet.";
      } else {
        meta.textContent = "";
      }
    }
    var html = "";
    if (hit) {
      html +=
        '<div class="bs-qth-grid">' +
        "<div><span>Call</span><b>" + escapeHtml(hit.call) + "</b></div>" +
        "<div><span>Prefix</span><b>" + escapeHtml(hit.prefix) + "</b></div>" +
        "<div><span>Entity (local)</span><b>" + escapeHtml(hit.entity) + "</b></div>" +
        "</div>";
    } else if (prefixCallValid(norm)) {
      html += '<p class="bs-empty">No match in the local prefix table — trying online sources…</p>';
    } else {
      html += '<p class="bs-empty">No match in the local prefix table.</p>';
    }
    if (remote) html += prefixRemoteHtml(norm, remote);
    else if (prefixBusy && prefixCallValid(norm)) {
      html += '<p class="bs-empty">Loading Callook / QRZCQ…</p>';
    }
    host.innerHTML = html;
    if (prefixCallValid(norm) && !remote && !prefixBusy && moreNetworkAllowed("prefix")) {
      prefixFetchRemote(norm, function () {});
    }
  }

  function prefixOnTab() { prefixPaint(); }

  function bindPrefixTab() {
    var root = $("bs-more-prefix");
    if (!root || root._bsPrefixWired) return;
    root._bsPrefixWired = true;
    if ($("bs-prefix-go")) {
      $("bs-prefix-go").onclick = function () {
        var call = prefixNormalizeCall(($("bs-prefix-in") || {}).value);
        if (call && prefixRemoteCache[call]) delete prefixRemoteCache[call];
        prefixFetchGen += 1;
        prefixPaint();
      };
    }
    if ($("bs-prefix-browse")) {
      $("bs-prefix-browse").onclick = function () {
        try { setMoreSubTab("callsigns"); } catch (eBr) {}
      };
    }
    if ($("bs-prefix-in")) {
      $("bs-prefix-in").addEventListener("input", function () {
        if (prefixInputTimer) clearTimeout(prefixInputTimer);
        prefixInputTimer = setTimeout(function () { prefixPaint(); }, 400);
      });
      $("bs-prefix-in").addEventListener("keydown", function (ev) {
        if (ev.key === "Enter") {
          ev.preventDefault();
          if (prefixInputTimer) clearTimeout(prefixInputTimer);
          prefixPaint();
        }
      });
    }
  }

