  function mufRoughMhz() {
    if (!solarInfo) return null;
    var sfi = Number(solarInfo.sfi);
    var k = Number(solarInfo.k);
    if (!(sfi > 0)) return null;
    var rough = Math.round(7 + (sfi - 70) * 0.08 - (isFinite(k) ? k * 0.4 : 0));
    if (rough < 5) rough = 5;
    if (rough > 45) rough = 45;
    return rough;
  }

  function mufPaint() {
    var host = $("bs-muf-host");
    var meta = $("bs-muf-meta");
    var btn = $("bs-muf-refresh");
    if (btn) {
      btn.disabled = !!solarBusy;
      btn.textContent = solarBusy ? "Refreshing…" : "Refresh";
    }
    if (meta) {
      meta.textContent = solarBusy
        ? "refreshing…"
        : (solarFetchedAt ? ("updated " + trafficLogAgo(solarFetchedAt)) : (solarError || ""));
    }
    if (!host) return;
    if (!solarInfo) {
      host.innerHTML = '<p class="bs-empty">' + escapeHtml(solarError || "Loading solar figures…") + "</p>";
      return;
    }
    var muf = mufRoughMhz();
    var tip = "Daytime F2 often supports paths below this rough ceiling; night is lower.";
    var k = Number(solarInfo.k);
    if (isFinite(k) && k >= 5) tip = "High K — expect depressed MUF and polar path trouble.";
    else if (muf && muf >= 28) tip = "High SFI — 10 m / 12 m may open mid-latitudes.";
    else if (muf && muf <= 12) tip = "Soft conditions — favour 40 / 80 m and greyline.";
    host.innerHTML =
      '<div class="bs-solar-grid">' +
      "<div><span>Rough MUF</span><b>" + escapeHtml(muf ? ("~" + muf + " MHz") : "—") + "</b></div>" +
      "<div><span>SFI</span><b>" + escapeHtml(String(solarInfo.sfi)) + "</b></div>" +
      "<div><span>K</span><b>" + escapeHtml(String(solarInfo.k)) + "</b></div>" +
      "<div><span>A</span><b>" + escapeHtml(String(solarInfo.a)) + "</b></div>" +
      "</div>" +
      '<p class="bs-solar-note">' + escapeHtml(tip) + "</p>" +
      '<p class="bs-hint">Not an ionosonde. Open Sky → Prop for X-ray / full tip.</p>';
  }

