  function stormGScale(k) {
    k = Number(k);
    if (!(k >= 0)) return { g: "—", lab: "unknown" };
    if (k < 5) return { g: "G0", lab: "quiet / unsettled" };
    if (k < 6) return { g: "G1", lab: "minor storm" };
    if (k < 7) return { g: "G2", lab: "moderate" };
    if (k < 8) return { g: "G3", lab: "strong" };
    if (k < 9) return { g: "G4", lab: "severe" };
    return { g: "G5", lab: "extreme" };
  }

  function stormPaint() {
    var host = $("bs-storm-host");
    var list = $("bs-storm-list");
    var meta = $("bs-storm-meta");
    var btn = $("bs-storm-refresh");
    if (btn) {
      btn.disabled = !!(solarBusy || alertsBusy);
      btn.textContent = (solarBusy || alertsBusy) ? "Refreshing…" : "Refresh";
    }
    if (meta) {
      var bits = [];
      if (solarFetchedAt) bits.push("solar " + trafficLogAgo(solarFetchedAt));
      if (alertsFetchedAt) bits.push("alerts " + trafficLogAgo(alertsFetchedAt));
      if (solarBusy || alertsBusy) bits.push("refreshing…");
      meta.textContent = bits.join(" · ");
    }
    var g = stormGScale(solarInfo && solarInfo.k);
    if (host) {
      if (!solarInfo) {
        host.innerHTML = '<p class="bs-empty">' + escapeHtml(solarError || "Loading K-index…") + "</p>";
      } else {
        host.innerHTML =
          '<div class="bs-solar-grid">' +
          "<div><span>Now</span><b>" + escapeHtml(g.g) + "</b></div>" +
          "<div><span>K</span><b>" + escapeHtml(String(solarInfo.k)) + "</b></div>" +
          "<div><span>A</span><b>" + escapeHtml(String(solarInfo.a)) + "</b></div>" +
          "<div><span>Level</span><b>" + escapeHtml(g.lab) + "</b></div>" +
          "</div>";
      }
    }
    if (!list) return;
    var stormish = (alertsRows || []).filter(function (a) {
      var t = String((a && (a.title || a.blurb || "")) || "").toLowerCase();
      return /geomagnetic|storm|g[1-5]|k-index|radiation|radio blackout|x-ray/.test(t);
    }).slice(0, 8);
    if (!stormish.length) {
      list.innerHTML = '<p class="bs-empty">' +
        escapeHtml(alertsError || (alertsBusy ? "Loading alerts…" : "No recent storm-related SWPC alerts.")) +
        "</p>";
      return;
    }
    list.innerHTML = stormish.map(function (a) {
      return '<article class="bs-more-row" style="cursor:default">' +
        '<span class="bs-more-name">' + escapeHtml(a.title || "Alert") + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(a.when || "") + "</span>" +
        '<span class="bs-more-status">' + escapeHtml((a.blurb || "").slice(0, 120)) + "</span></article>";
    }).join("");
  }

