  var wxInfo = null;
  var wxFetchedAt = 0;
  var wxError = "";
  var wxBusy = false;
  var wxGen = 0;

  function wxPaint() {
    var host = $("bs-wx-host");
    var meta = $("bs-wx-meta");
    var btn = $("bs-wx-refresh");
    if (btn) {
      btn.disabled = !!wxBusy;
      btn.textContent = wxBusy ? "Refreshing…" : "Refresh";
    }
    if (meta) {
      meta.textContent = wxBusy
        ? (wxFetchedAt ? ("updated " + trafficLogAgo(wxFetchedAt) + " · refreshing…") : "refreshing…")
        : (wxFetchedAt ? ("updated " + trafficLogAgo(wxFetchedAt)) : "");
    }
    if (!host) return;
    var obs = moreObsFromStorage();
    if (!obs) {
      host.innerHTML = '<p class="bs-empty">Set lat/lon on QTH / Sats first.</p>';
      return;
    }
    if (!wxInfo) {
      host.innerHTML = '<p class="bs-empty">' +
        escapeHtml(wxError || (wxBusy ? "Loading Open-Meteo…" : "Press Refresh for local weather.")) +
        "</p>";
      return;
    }
    var w = wxInfo;
    host.innerHTML =
      '<div class="bs-solar-grid">' +
      "<div><span>Temp</span><b>" + escapeHtml(w.temp) + "°C</b></div>" +
      "<div><span>Feels</span><b>" + escapeHtml(w.feels) + "°C</b></div>" +
      "<div><span>Wind</span><b>" + escapeHtml(w.wind) + " km/h</b></div>" +
      "<div><span>Humidity</span><b>" + escapeHtml(w.hum) + "%</b></div>" +
      "</div>" +
      '<p class="bs-solar-note">' + escapeHtml(w.summary) + "</p>" +
      '<p class="bs-hint">QTH ' + obs.lat.toFixed(2) + ", " + obs.lon.toFixed(2) +
      " · Open-Meteo · precipitation " + escapeHtml(w.precip) + " mm</p>";
  }

  function wxCodeSummary(code) {
    code = Number(code) || 0;
    if (code === 0) return "Clear sky.";
    if (code <= 3) return "Mainly clear to overcast.";
    if (code <= 48) return "Fog / depositing rime.";
    if (code <= 57) return "Drizzle.";
    if (code <= 67) return "Rain.";
    if (code <= 77) return "Snow.";
    if (code <= 82) return "Rain showers.";
    if (code <= 86) return "Snow showers.";
    if (code >= 95) return "Thunderstorm.";
    return "Mixed conditions.";
  }

  function wxEnsure(force) {
    if (!moreNetworkAllowed("wx")) {
      wxError = "Network budget blocked More fetches.";
      wxPaint();
      return;
    }
    var obs = moreObsFromStorage();
    if (!obs) {
      wxPaint();
      return;
    }
    if (!force && wxFetchedAt && Date.now() - wxFetchedAt < 10 * 60 * 1000 && wxInfo) {
      wxPaint();
      return;
    }
    if (wxBusy && !force) return;
    var gen = ++wxGen;
    wxBusy = true;
    wxError = "";
    wxPaint();
    var url = "https://api.open-meteo.com/v1/forecast?latitude=" + encodeURIComponent(obs.lat) +
      "&longitude=" + encodeURIComponent(obs.lon) +
      "&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m" +
      "&wind_speed_unit=kmh&timezone=auto";
    fetch(url, { cache: "no-store" })
      .then(function (r) {
        if (!r.ok) throw new Error("http");
        return r.json();
      })
      .then(function (data) {
        if (gen !== wxGen) return;
        var c = (data && data.current) || {};
        wxInfo = {
          temp: isFinite(Number(c.temperature_2m)) ? Number(c.temperature_2m).toFixed(1) : "—",
          feels: isFinite(Number(c.apparent_temperature)) ? Number(c.apparent_temperature).toFixed(1) : "—",
          wind: isFinite(Number(c.wind_speed_10m)) ? Number(c.wind_speed_10m).toFixed(0) : "—",
          hum: isFinite(Number(c.relative_humidity_2m)) ? String(Math.round(Number(c.relative_humidity_2m))) : "—",
          precip: isFinite(Number(c.precipitation)) ? Number(c.precipitation).toFixed(1) : "0.0",
          summary: wxCodeSummary(c.weather_code)
        };
        wxFetchedAt = Date.now();
        wxBusy = false;
        wxError = "";
        wxPaint();
      })
      .catch(function () {
        if (gen !== wxGen) return;
        wxBusy = false;
        wxError = "Open-Meteo did not answer.";
        wxPaint();
      });
  }

  function wxOnTab() { wxEnsure(false); }

  function bindWxTab() {
    var root = $("bs-more-wx");
    if (!root || root._bsWxWired) return;
    root._bsWxWired = true;
    if ($("bs-wx-refresh")) $("bs-wx-refresh").onclick = function () { wxEnsure(true); };
  }

  var LS_NOISE = "owrx_toolbox_noise_log_v1";
  var noiseRows = null;

  function noiseLoad() {
    if (noiseRows) return noiseRows;
    try {
      var raw = window.localStorage.getItem(LS_NOISE);
      var arr = raw ? JSON.parse(raw) : [];
      noiseRows = Array.isArray(arr) ? arr : [];
    } catch (e) {
      noiseRows = [];
    }
    return noiseRows;
  }

  function noiseSave() {
    try {
      var cap = 40;
      try { normalizeSdrControl(S); cap = S.maxNoiseSamples || 40; } catch (eC) {}
      window.localStorage.setItem(LS_NOISE, JSON.stringify((noiseRows || []).slice(0, cap)));
    } catch (e) {}
  }

  function noisePaint() {
    var host = $("bs-noise-list");
    var meta = $("bs-noise-meta");
    var rows = noiseLoad();
    if (meta) meta.textContent = rows.length ? (rows.length + " sample" + (rows.length === 1 ? "" : "s")) : "";
    if (!host) return;
    if (!rows.length) {
      host.innerHTML = '<p class="bs-empty">No samples yet — tune a quiet spot and press Sample now.</p>';
      return;
    }
    host.innerHTML = rows.map(function (r) {
      var when = r.at ? trafficLogAgo(r.at) : "";
      return '<article class="bs-more-row" style="cursor:default">' +
        '<span class="bs-more-name">' + escapeHtml(String(r.db) + " dB") + "</span>" +
        '<span class="bs-more-mhz">' + escapeHtml(r.mhz != null ? Number(r.mhz).toFixed(3) : "—") + "</span>" +
        '<span class="bs-more-status">' + escapeHtml(when + (r.note ? (" · " + r.note) : "")) + "</span></article>";
    }).join("");
  }

  function noiseSample() {
    var db = null;
    try { db = smeterDbRaw(); } catch (e) { db = null; }
    if (!(isFinite(db))) {
      setStatus("No S-meter reading yet — wait for audio levels.");
      return;
    }
    var mhz = null;
    try { mhz = currentTuneHz() / 1e6; } catch (eH) { mhz = null; }
    noiseLoad();
    noiseRows.unshift({
      at: Date.now(),
      db: Math.round(Number(db) * 10) / 10,
      mhz: isFinite(mhz) ? Math.round(mhz * 1000) / 1000 : null,
      note: "raw"
    });
    var cap = 40;
    try { normalizeSdrControl(S); cap = S.maxNoiseSamples || 40; } catch (eCap) {}
    if (noiseRows.length > cap) noiseRows.length = cap;
    noiseSave();
    noisePaint();
    setStatus("Noise sample " + db.toFixed(1) + " dB" + (isFinite(mhz) ? (" @ " + mhz.toFixed(3) + " MHz") : "") + ".");
  }

