  function leoKindOrder(kind) {
    if (kind === "fm") return 0;
    if (kind === "linear") return 1;
    if (kind === "digi") return 2;
    if (kind === "geo") return 3;
    return 4;
  }

  function leoKindLabel(kind) {
    if (kind === "fm") return "FM voice / repeaters";
    if (kind === "linear") return "Linear transponders (SSB/CW)";
    if (kind === "digi") return "Digital / store-and-forward";
    if (kind === "geo") return "Geostationary (reference dial)";
    return "Other";
  }

  function leoRowHtml(s, status) {
    return '<article class="bs-more-row" data-leo-mhz="' + s.mhz + '" data-leo-mode="' + escapeHtml(s.mode || "nfm") +
      '" title="Tune ' + escapeHtml(s.name) + '.">' +
      '<span class="bs-more-name">' + escapeHtml(s.name) + "</span>" +
      '<span class="bs-more-mhz">' + escapeHtml(Number(s.mhz).toFixed(3)) + "</span>" +
      '<span class="bs-more-mode">' + escapeHtml(String(s.mode || "").toUpperCase()) + "</span>" +
      '<span class="bs-more-status">' + escapeHtml(status) + "</span></article>";
  }

  function leoRender() {
    var host = $("bs-leo-list");
    if (!host) return;
    var rows = (typeof SAT_CATALOG !== "undefined" && SAT_CATALOG) ? SAT_CATALOG.slice() : [];
    if (!rows.length && !(WX_SAT_ROWS && WX_SAT_ROWS.length)) {
      host.innerHTML = '<p class="bs-empty">No sat catalog loaded.</p>';
      return;
    }
    rows.sort(function (a, b) {
      var ka = leoKindOrder(a.kind);
      var kb = leoKindOrder(b.kind);
      if (ka !== kb) return ka - kb;
      return String(a.name).localeCompare(String(b.name));
    });
    var html = "";
    var lastKind = null;
    rows.forEach(function (s) {
      var kind = s.kind || "fm";
      if (kind !== lastKind) {
        lastKind = kind;
        html += '<p class="bs-opt-lab bs-leo-kind-lab">' + escapeHtml(leoKindLabel(kind)) + "</p>";
      }
      html += leoRowHtml(s, "NORAD " + String(s.norad || ""));
    });
    if (WX_SAT_ROWS && WX_SAT_ROWS.length) {
      html += '<p class="bs-opt-lab bs-leo-kind-lab">Weather satellites (APT / LRPT · RX only)</p>';
      WX_SAT_ROWS.forEach(function (w) {
        html += leoRowHtml(w, w.note || "RX only");
      });
    }
    host.innerHTML = html;
  }

