  function panelTabHtml_listenerInner(id) {
    var c = LISTENER_PANE_CFG[id];
    if (!c) return "";
    var listId = "bs-" + id + "-list";
    var boxId = "bs-" + id + "-box";
    var foot = c.foot || "";
    var body = c.kind === "utc"
      ? ('<div id="' + listId + '" class="bs-qth-host"></div>')
      : ('<div class="bs-more-notes" id="' + listId + '"></div>');
    return tabBoxHtml(c.title, body + '<p class="bs-hint">' + foot + "</p>",
      { wide: true, id: boxId, cls: "bs-listener-box", help: c.title + " — static listener guide in Toolbox." });
  }

  function listenerUtcRender() {
    var host = $("bs-hereutc-list");
    if (!host) return;
    var d = new Date();
    var utc = d.toISOString().replace("T", " ").slice(0, 19) + " UTC";
    var loc = d.toString();
    var rows = [
      { name: "UTC (snapshot)", note: utc + " — captured when you opened this tab." },
      { name: "Local browser", note: loc + " — from your PC clock, not the receiver." },
      { name: "Logging tip", note: "Ham logs use UTC (Zulu). Convert local QSO time before submitting to LoTW/Club Log." },
      { name: "Sked tip", note: "Nets and contests are often advertised in UTC — Sked → Nets uses UTC in the form." },
      { name: "No live clock", note: "Toolbox does not run a timer here — re-open the tab for a fresh snapshot." },
      { name: "QTH clocks", note: "Here → QTH shows sunrise and clocks tied to receiver lat/lon while that pane is open." }
    ];
    host.innerHTML = rows.map(function (r) { return moreNoteCardHtml(r.name, r.note); }).join("");
  }

  function listenerPaneOnTab(id) {
    var c = LISTENER_PANE_CFG[id];
    if (!c) return;
    if (c.kind === "utc") {
      listenerUtcRender();
      return;
    }
    var listId = "bs-" + id + "-list";
    if (c.freqRows) {
      moreRenderMfqList(listId, c.freqRows);
      return;
    }
    if (c.links) {
      moreRenderLinkList(listId, c.links);
      return;
    }
    moreRenderNoteList(listId, LISTENER_NOTE_ROWS[c.rowsKey] || []);
  }

  function bindListenerPaneTab(id) {
    var root = $("bs-more-" + id);
    if (!root || root._bsListenerPaneWired) return;
    root._bsListenerPaneWired = true;
    var c = LISTENER_PANE_CFG[id];
    if (c && c.freqRows) {
      moreBindMfqPane("bs-more-" + id, c.tuneLabel || "Tune", "_bsMfq_" + id);
    }
  }

  function bindAllListenerPaneTabs() {
    Object.keys(LISTENER_PANE_CFG).forEach(bindListenerPaneTab);
  }

  function latLonToMaidenhead(lat, lon, digits) {
    lat = Number(lat);
    lon = Number(lon);
    digits = digits === 4 ? 4 : 6;
    if (!(isFinite(lat) && isFinite(lon))) return "";
    if (lat < -90 || lat > 90 || lon < -180 || lon > 180) return "";
    lon += 180;
    lat += 90;
    var s = "";
    s += String.fromCharCode(65 + Math.floor(lon / 20));
    s += String.fromCharCode(65 + Math.floor(lat / 10));
    s += String(Math.floor((lon % 20) / 2));
    s += String(Math.floor(lat % 10));
    if (digits === 4) return s;
    lon = (lon % 2) * 12;
    lat = (lat % 1) * 24;
    s += String.fromCharCode(65 + Math.floor(lon));
    s += String.fromCharCode(65 + Math.floor(lat));
    return s;
  }

  function locatorPaint(msg) {
    var host = $("bs-loc-host");
    if (!host) return;
    var grid = (($("bs-loc-grid") || {}).value || "").trim().toUpperCase();
    var lat = Number(($("bs-loc-lat") || {}).value);
    var lon = Number(($("bs-loc-lon") || {}).value);
    host.innerHTML =
      '<div class="bs-qth-grid">' +
      "<div><span>Grid</span><b>" + escapeHtml(grid || "—") + "</b></div>" +
      "<div><span>Lat</span><b>" + escapeHtml(isFinite(lat) ? lat.toFixed(4) : "—") + "</b></div>" +
      "<div><span>Lon</span><b>" + escapeHtml(isFinite(lon) ? lon.toFixed(4) : "—") + "</b></div>" +
      "<div><span>Status</span><b>" + escapeHtml(msg || "Ready") + "</b></div>" +
      "</div>";
  }

  function locatorOnTab() {
    var obs = null;
    try { obs = moreObsFromStorage(); } catch (e) {}
    if (obs && $("bs-loc-lat") && !$("bs-loc-lat").value) {
      $("bs-loc-lat").value = obs.lat.toFixed(4);
      $("bs-loc-lon").value = obs.lon.toFixed(4);
      var g = latLonToMaidenhead(obs.lat, obs.lon, 6);
      if ($("bs-loc-grid") && g) $("bs-loc-grid").value = g;
    }
    locatorPaint(obs ? "From QTH if fields were empty." : "Enter grid or lat/lon.");
  }

  function bindLocatorTab() {
    var root = $("bs-more-locator");
    if (!root || root._bsLocWired) return;
    root._bsLocWired = true;
    if ($("bs-loc-grid2ll")) {
      $("bs-loc-grid2ll").onclick = function () {
        var g = (($("bs-loc-grid") || {}).value || "").trim();
        var ll = qthGridToLatLon(g);
        if (!ll) {
          locatorPaint("Need a valid 4- or 6-character grid.");
          return;
        }
        if ($("bs-loc-lat")) $("bs-loc-lat").value = ll.lat.toFixed(4);
        if ($("bs-loc-lon")) $("bs-loc-lon").value = ll.lon.toFixed(4);
        locatorPaint("Grid → lat/lon.");
      };
    }
    if ($("bs-loc-ll2grid")) {
      $("bs-loc-ll2grid").onclick = function () {
        var lat = Number(($("bs-loc-lat") || {}).value);
        var lon = Number(($("bs-loc-lon") || {}).value);
        var g = latLonToMaidenhead(lat, lon, 6);
        if (!g) {
          locatorPaint("Enter valid lat (−90…90) and lon (−180…180).");
          return;
        }
        if ($("bs-loc-grid")) $("bs-loc-grid").value = g;
        locatorPaint("Lat/lon → grid.");
      };
    }
    if ($("bs-loc-from-qth")) {
      $("bs-loc-from-qth").onclick = function () {
        var obs = moreObsFromStorage();
        if (!obs) {
          locatorPaint("Set lat/lon on QTH / Sats first.");
          return;
        }
        if ($("bs-loc-lat")) $("bs-loc-lat").value = obs.lat.toFixed(4);
        if ($("bs-loc-lon")) $("bs-loc-lon").value = obs.lon.toFixed(4);
        if ($("bs-loc-grid")) $("bs-loc-grid").value = latLonToMaidenhead(obs.lat, obs.lon, 6);
        locatorPaint("Filled from QTH.");
      };
    }
  }

