  function moreLeaveHeavy() {
    passStopTimer();
    greyStopTimer();
    moreBeaconStopTimer();
    qthStopTimer();
  }

  function moreGroupVisible(gid) {
    var g = MORE_GROUP_META[gid];
    if (!g) return false;
    var i;
    for (i = 0; i < (g.panes || []).length; i++) {
      if (!isMoreSubHidden(g.panes[i].id)) return true;
    }
    return false;
  }

  function firstVisiblePaneInGroup(gid) {
    var g = MORE_GROUP_META[gid];
    var i;
    if (!g) return firstVisibleMoreSub();
    for (i = 0; i < (g.panes || []).length; i++) {
      if (!isMoreSubHidden(g.panes[i].id)) return g.panes[i].id;
    }
    return firstVisibleMoreSub();
  }

  function setMoreSubTab(name, opts) {
    opts = opts || {};
    if (!MORE_SUBS[name] || isMoreSubHidden(name)) name = firstVisibleMoreSub();
    var gid = MORE_PANE_GROUP[name] || "spots";
    var root = $("bs-tab-more");
    if (!root) return;
    moreLeaveHeavy();
    Array.prototype.forEach.call(root.querySelectorAll(".bs-more-group"), function (btn) {
      var id = btn.getAttribute("data-more-group");
      var hide = !moreGroupVisible(id);
      btn.hidden = hide;
      if (hide) btn.setAttribute("hidden", "");
      else btn.removeAttribute("hidden");
      var on = !hide && id === gid;
      btn.classList.toggle("bs-more-group-on", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    Array.prototype.forEach.call(root.querySelectorAll(".bs-more-grouppane"), function (pane) {
      var id = pane.getAttribute("data-more-group");
      var on = moreGroupVisible(id) && id === gid;
      pane.classList.toggle("bs-more-group-on", on);
      if (on) pane.removeAttribute("hidden");
      else pane.setAttribute("hidden", "");
    });
    Array.prototype.forEach.call(root.querySelectorAll(".bs-more-sub"), function (btn) {
      var id = btn.getAttribute("data-more-sub");
      var hide = isMoreSubHidden(id);
      btn.hidden = hide;
      if (hide) btn.setAttribute("hidden", "");
      else btn.removeAttribute("hidden");
      var on = !hide && id === name;
      btn.classList.toggle("bs-more-sub-on", on);
      btn.setAttribute("aria-selected", on ? "true" : "false");
    });
    Array.prototype.forEach.call(root.querySelectorAll(".bs-more-subpane"), function (pane) {
      var id = pane.getAttribute("data-more-sub");
      var on = !isMoreSubHidden(id) && id === name;
      pane.classList.toggle("bs-more-sub-on", on);
      if (on) pane.removeAttribute("hidden");
      else pane.setAttribute("hidden", "");
    });
    moreActivateSub(name);
    if (!opts.skipSave) {
      try { if (extraOn("rememberSubs")) window.localStorage.setItem("owrx_toolbox_more_sub_v1", name); } catch (eLs) {}
    }
    try { injectBoxHelpButtons(root); } catch (eH) {}
  }

  function restoreMoreSubTab() {
    var name = firstVisibleMoreSub();
    try {
      var raw = extraOn("rememberSubs") ? window.localStorage.getItem("owrx_toolbox_more_sub_v1") : null;
      if (raw && MORE_SUBS[raw] && !isMoreSubHidden(raw)) name = raw;
    } catch (e) {}
    setMoreSubTab(name, { skipSave: true });
  }

  function moreOnTab() {
    try { syncMoreTabHoverHints(); } catch (eMoreTipTab) {}
    var name = "dx";
    var on = document.querySelector("#bs-tab-more .bs-more-subpane.bs-more-sub-on");
    if (on) name = on.getAttribute("data-more-sub") || "dx";
    moreActivateSub(name);
  }

  function bindMoreTab() {
    var root = $("bs-tab-more");
    if (!root || root._bsMoreWired) return;
    root._bsMoreWired = true;
    try { syncMoreTabHoverHints(); } catch (eMoreTip) {}
    root.addEventListener("click", function (ev) {
      var gbtn = ev.target && ev.target.closest && ev.target.closest(".bs-more-group");
      if (gbtn && root.contains(gbtn)) {
        var gid = gbtn.getAttribute("data-more-group");
        if (gid) setMoreSubTab(firstVisiblePaneInGroup(gid));
        return;
      }
      var btn = ev.target && ev.target.closest && ev.target.closest(".bs-more-sub");
      if (!btn || !root.contains(btn)) return;
      var name = btn.getAttribute("data-more-sub");
      if (name) setMoreSubTab(name);
    });
    bindDxTab();
    bindSatTab();
    bindPassTab();
    bindRbnTab();
    bindPotaTab();
    bindSotaTab();
    bindDialTab();
    bindPlanTab();
    bindCallTab();
    bindTimeTab();
    bindPropTab();
    bindAlertsTab();
    bindAuroraTab();
    bindGreyTab();
    bindQthTab();
    bindPathTab();
    bindPrefixTab();
    bindGb2rsTab();
    bindNetsTab();
    bindNewsTab();
    bindCustomFeedsTab();
    bindWwffTab();
    bindClusterTab();
    bindIssTab();
    bindMeteorTab();
    bindMaritimeTab();
    bindAirTab();
    bindMufTab();
    bindStormTab();
    bindWxTab();
    bindNoiseTab();
    bindSpecialTab();
    bindRepeaterTab();
    bindIaruTab();
    bindLicenseTab();
    bindQslTab();
    bindLeoTab();
    bindCbTab();
    bindEsTab();
    bindLocatorTab();
    bindAwardTab();
    bindCallsTab();
    bindPhoneticTab();
    bindFt8Tab();
    bindSstvTab();
    bindSwlTab();
    bindHfdayTab();
    bindUnitsTab();
    bindFildayTab();
    bindAllListenerPaneTabs();
    restoreMoreSubTab();
  }

