  /** Peaks actions — eager tab, but must bind even if Bookmarks cold stubs abort later wire steps. */
  function bindJumpTuningControls() {
    try { migrateHopSkipButtonLayout(); } catch (eHopSk) {}
    JUMP_THR_IDS.concat(JUMP_CLUSTER_IDS).forEach(function (id) {
      var el = $(id);
      if (!el || el._bsJumpTuneBound) return;
      el._bsJumpTuneBound = true;
      el.onchange = function () {
        readForm();
        /* Keep current band key so a manual tweak is not wiped until the band class changes. */
        try {
          var def = jumpEffectiveDefaults();
          _jumpAutoKey = String(def.key || "default");
        } catch (eKey) {}
        saveSettings();
      };
    });
    JUMP_CENTER_IDS.forEach(function (id) {
      var el = $(id);
      if (!el || el._bsJumpCenterBound) return;
      el._bsJumpCenterBound = true;
      el.onchange = function () {
        S.jumpCenterScreen = syncJumpCenterUi(this.checked);
        saveSettings();
      };
    });
    JUMP_FM_GRID_IDS.concat(JUMP_FM_SCAN_IDS).concat(JUMP_FM_DETECT_IDS).forEach(function (id) {
      var el = $(id);
      if (!el || el._bsJumpFmBound) return;
      el._bsJumpFmBound = true;
      el.onchange = function () {
        readForm();
        saveSettings();
      };
    });
    var fmExp = $("bs-jump-fm-exp-on");
    if (fmExp && !fmExp._bsJumpFmExpBound) {
      fmExp._bsJumpFmExpBound = true;
      fmExp.onchange = function () {
        setJumpFmExp(!!fmExp.checked);
        setStatus(fmExp.checked
          ? "Jump loudest on FM broadcast enabled (experimental)."
          : "Jump loudest on FM broadcast off.");
      };
    }
    try { injectJumpFmRowsIfMissing(); } catch (eFmInj) {}
    try { applyJumpBandDefaults(false); } catch (eApply) {}
    try { syncJumpCenterUi(jumpCenterScreenEnabled()); } catch (eCen) {}
    try { syncJumpFmUiFromSettings(); } catch (eFmSync) {}
    try { syncJumpFmExpUi(); } catch (eJumpFm) {}
    try { syncJumpLoudestVisibility(); } catch (eJumpVis) {}
  }

  function bindPeaksTabControls() {
    if ($("bs-pk-subs") && !$("bs-pk-subs")._bsPkSubsWired) {
      $("bs-pk-subs")._bsPkSubsWired = true;
      $("bs-pk-subs").onclick = function (ev) {
        var btn = ev.target && ev.target.closest && ev.target.closest(".bs-pk-sub");
        if (!btn) return;
        var name = btn.getAttribute("data-pk-sub");
        if (name) setPeaksSubTab(name);
      };
      try { restorePeaksSubTab(); } catch (ePk) {}
    }
    if ($("bs-bmqual")) {
      $("bs-bmqual").onclick = function () {
        var created = autoBookmarkQualified();
        var n = created.filter(function (r) { return !r.already; }).length;
        setStatus("Bookmarked " + n + " new (seen ≥ " + S.minHits + "). Click a name to rename.");
        renderHits();
        if (S.scanAfter && lastCreated.length && !running) {
          stopFlag = false;
          running = true;
          var btn2 = $("bs-toggle-btn");
          if (btn2) btn2.classList.add("bs-running");
          listenBookmarks(lastCreated).then(function () {
            running = false;
            if (btn2) btn2.classList.remove("bs-running");
          }).catch(function (err) {
            running = false;
            if (btn2) btn2.classList.remove("bs-running");
            setStatus(friendlyError(err, "Listen"));
          });
        }
      };
    }
    if ($("bs-copy")) $("bs-copy").onclick = copyResults;
    if ($("bs-csv")) $("bs-csv").onclick = function () { exportCsv(); };
    if ($("bs-json")) $("bs-json").onclick = function () { exportServerJson(); };
    if ($("bs-csv-in")) $("bs-csv-in").onclick = function (ev) { startImport("csv", ev); };
    if ($("bs-json-in")) $("bs-json-in").onclick = function (ev) { startImport("json", ev); };
    if ($("bs-clearhits")) {
      $("bs-clearhits").onclick = function () {
        if (!requirePublicFeature("clearData", "Clear peaks")) return;
        hits = [];
        tileLooks = {};
        _hitsClassified = false;
        _hitsLoaded = true;
        try { window.localStorage.removeItem(LS_HITS); } catch (eClr) {}
        saveHits();
        renderHits();
        updateTabLabels();
        setStatus("Peaks cleared.");
      };
    }
    if ($("bs-hitwrap") && !$("bs-hitwrap")._bs_peaks_bound) {
      $("bs-hitwrap")._bs_peaks_bound = true;
      $("bs-hitwrap").onclick = function (ev) {
        var t = ev.target;
        if (!t) return;
        if (t.closest) {
          var renameEl = t.closest("[data-rename]");
          if (renameEl) {
            if (ev.stopPropagation) ev.stopPropagation();
            askRename(Number(renameEl.getAttribute("data-rename")));
            return;
          }
        }
        if (t.getAttribute("data-sort")) {
          sortKey = t.getAttribute("data-sort");
          renderHits();
          return;
        }
        if (t.getAttribute("data-rename")) {
          if (ev.stopPropagation) ev.stopPropagation();
          askRename(Number(t.getAttribute("data-rename")));
          return;
        }
        if (t.getAttribute("data-tune")) {
          tuneTo(Number(t.getAttribute("data-tune")), t.getAttribute("data-pid"));
          if (extraOn("peakOpenIdentify")) {
            try { switchTab("identify"); } catch (eId) {}
            try { if (typeof idRunOnce === "function") setTimeout(idRunOnce, 200); } catch (eId2) {}
          }
          return;
        }
        if (t.getAttribute("data-lockout")) {
          var loF = Number(t.getAttribute("data-lockout"));
          if (isFinite(loF) && loF > 0) {
            try { lockout(loF); } catch (eLo) {}
            var mins = Math.max(1, Number(S.lockoutMin) || 30);
            setStatus("Lockout " + fmtMhz(loF) + " · " + mins + " min");
            try { if (typeof renderLockouts === "function") renderLockouts(); } catch (eR) {}
            try { renderHits(); } catch (eH) {}
          }
          return;
        }
        if (t.getAttribute("data-ignore")) {
          var ignF = Number(t.getAttribute("data-ignore"));
          if (isIgnoredFreq(ignF)) {
            unignoreFreq(ignF);
            setStatus("Will land on " + fmtMhz(ignF) + " again.");
          } else {
            ignoreFreq(ignF);
            if (continueIfPausedOn(ignF)) {
              setStatus("Always skip " + fmtMhz(ignF) + " — continuing scan.");
            } else {
              setStatus("Always skip " + fmtMhz(ignF) + " (saved in this browser).");
            }
          }
          return;
        }
        if (t.getAttribute("data-del-peak")) {
          if (typeof publicAllowsFeature === "function" && !publicAllowsFeature("clearData")) {
            setStatus("Clear peaks is not allowed for visitors on this receiver.");
            return;
          }
          var delF = Number(t.getAttribute("data-del-peak"));
          if (removePeak(delF)) setStatus("Removed peak " + fmtMhz(delF) + ".");
          else setStatus("Peak not found.");
          return;
        }
        if (t.getAttribute("data-named-bm")) {
          addNamedBookmarkFromPeak(Number(t.getAttribute("data-named-bm")));
          return;
        }
        if (t.getAttribute("data-copy-tune")) {
          copyTuneText(Number(t.getAttribute("data-copy-tune")), t.getAttribute("data-copy-mode") || "");
          return;
        }
        if (t.getAttribute("data-freq-note")) {
          var nf = Number(t.getAttribute("data-freq-note"));
          var cur = noteForFreq(nf);
          var nn = window.prompt("Note for " + fmtMhz(nf) + ":", cur);
          if (nn == null) return;
          setNoteForFreq(nf, nn);
          renderHits();
          setStatus(nn.trim() ? ("Note saved for " + fmtMhz(nf)) : ("Note cleared for " + fmtMhz(nf)));
          return;
        }
        if (t.getAttribute("data-bm")) {
          var f = Number(t.getAttribute("data-bm"));
          var hit = hits.filter(function (h) { return h.freq === f; })[0];
          if (hit && addBookmark(hit)) {
            setStatus("Bookmarked " + (hit.name || fmtMhz(f)) + " — click the name to rename.");
            renderHits();
          }
        }
      };
    }
    try { updateClearSkipBtn(); } catch (eClr) {}
    try { gatePublicActions(); } catch (eGate) {}
  }

