    root.querySelectorAll(".bs-ex-mode[data-ex-mod], .openwebrx-demodulator-button[data-modulation]").forEach(function (btn) {
      var mod = btn.getAttribute("data-ex-mod") || btn.getAttribute("data-modulation") || "";
      var lab = String(btn.textContent || "").replace(/\s+/g, " ").trim() || mod;
      setHoverTip(btn, demodModeHoverTip(mod, lab));
    });
    var digBtn = root.querySelector && root.querySelector(".openwebrx-button-dig");
    if (digBtn) {
      setHoverTip(digBtn, "Digital modes — pick FT8, FT4, WSPR, packet, AIS, etc. from the dropdown. Opens decode panels; tune to the correct dial frequency.");
    }
