  function bindExploreProfileSelect(profSel) {
    if (!profSel) return;
    if (!profSel._bsProfBusyBound) {
      profSel._bsProfBusyBound = true;
      var markBusy = function () {
        explore._profileSelBusy = true;
        if (explore._profileSelBusyTimer) clearTimeout(explore._profileSelBusyTimer);
        explore._profileSelBusyTimer = setTimeout(function () {
          explore._profileSelBusy = false;
          explore._profileSelBusyTimer = null;
        }, 30000);
      };
      var clearBusy = function () {
        explore._profileSelBusy = false;
        if (explore._profileSelBusyTimer) {
          clearTimeout(explore._profileSelBusyTimer);
          explore._profileSelBusyTimer = null;
        }
      };
      /* Do NOT clear on blur — opening the native list often blurs the <select>. */
      profSel.addEventListener("pointerdown", markBusy);
      profSel.addEventListener("mousedown", markBusy);
      profSel.addEventListener("touchstart", markBusy, { passive: true });
      profSel.addEventListener("focus", markBusy);
      profSel.addEventListener("keydown", function (ev) {
        if (ev.key === "Escape") clearBusy();
      });
      document.addEventListener("pointerdown", function (ev) {
        if (!explore._profileSelBusy) return;
        var t = ev.target;
        if (t && (t === profSel || (profSel.contains && profSel.contains(t)))) return;
        clearBusy();
      }, true);
      explore._clearProfileSelBusy = clearBusy;
    }
    profSel.onchange = function () {
      if (typeof explore._clearProfileSelBusy === "function") explore._clearProfileSelBusy();
      var v = profSel.value;
      if (!v) return;
      var list = typeof profiles === "function" ? profiles() : [];
      var meta = null;
      list.forEach(function (p) { if (p.value === v) meta = p; });
      if (!meta) meta = { value: v, label: v, id: v };
      if (!profileAllowedForPublicExplore(meta)) {
        exploreSetStatus("Public Explore: band not allowed.");
        exploreFillProfiles();
        return;
      }
      switchProfile(v).then(function (ok) {
        if (!ok) {
          try {
            exploreSetStatus(profileSwitchFailureHint(v));
          } catch (eSt) {}
          try { exploreFillProfiles(); } catch (eFill) {}
          return;
        }
        exploreApplyProfileHop(meta);
      });
    };
  }

