  /** MHz to tune after an explicit Explore / Ident profile hop (not lock-profile drag). */
  function exploreProfileTargetHz(p) {
    if (!p) return 0;
    var det = lookupProfileDetail(p);
    var hz = 0;
    if (det && det.start_freq > 0 && isFinite(det.start_freq)) hz = Math.round(det.start_freq);
    else if (det && det.center_freq > 0 && isFinite(det.center_freq)) hz = Math.round(det.center_freq);
    if (!hz) {
      var r = profileMhzRange(p);
      if (r) hz = Math.round(((r.lo + r.hi) / 2) * 1e6);
    }
    if (!hz) {
      var c = typeof window.center_freq === "number" ? window.center_freq : 0;
      if (c > 0) hz = Math.round(c);
    }
    return hz;
  }

  function exploreApplyProfileHop(meta, statusPrefix) {
    var label = (meta && (meta.label || meta.id || meta.value)) || "profile";
    try { applyExploreChannelStepForProfile(meta); } catch (eStepProf) {}
    var hz = exploreProfileTargetHz(meta);
    if (hz > 0) {
      var clamped = clampPublicExploreHz(hz);
      if (clamped.clamped) hz = clamped.hz;
      pluginSetFrequency(hz);
      var bw = window.bandwidth || 0;
      var c = window.center_freq || 0;
      if (bw && c && (hz < c - bw * 0.42 || hz > c + bw * 0.42)) {
        if (!exCtl.lockProf) exploreSendCenter(hz, true);
      }
      explorePushHistory(hz);
      exploreStoreActiveVfo();
      exploreSetStatus((statusPrefix || "→") + " " + label + " · " + fmtMhz(hz));
    } else {
      exploreSetStatus((statusPrefix || "→") + " " + label);
    }
    explore.overview = null;
    explore.segmentStart = 0;
    explore.segmentEnd = 0;
    exploreFillProfiles();
    exploreRefreshHud();
    try { idSyncFreqUi(); } catch (eId) {}
  }

  function exploreProfileSelBusy() {
    if (explore._profileSelBusy) return true;
    var ids = ["bs-ex-profile-sel", "bs-id-profile-sel"];
    var i, dest;
    for (i = 0; i < ids.length; i++) {
      dest = $(ids[i]);
      if (!dest) continue;
      try {
        if (document.activeElement === dest) return true;
        if (dest.matches && dest.matches(":focus")) return true;
      } catch (eF) {}
    }
    return false;
  }

  function exploreFillOneProfileSelect(dest) {
    var src = $("openwebrx-sdr-profiles-listbox");
    if (!dest) return;
    if (!src || !src.options.length) {
      if (dest.getAttribute("data-sig") !== "empty") {
        dest.setAttribute("data-sig", "empty");
        dest.innerHTML = '<option value="">No profiles</option>';
      }
      return;
    }
    var list = typeof profiles === "function" ? profiles() : [];
    var byVal = {};
    list.forEach(function (p) { byVal[p.value] = p; });
    var restrict = publicExploreBandsRestricted() || !!publicExploreLimitsHz();
    var sig = restrict ? "pub:" : "";
    if (dest.id === "bs-id-profile-sel") {
      sig += "idSdr:" + String(S.idSdrShowOnly || "") + "|h:" + JSON.stringify(hiddenSdrKindsMap()) + ";";
    } else {
      sig += "sdr:" + String(S.exploreSdrShowOnly || "") + "|h:" + JSON.stringify(hiddenSdrKindsMap()) + ";";
    }
    var html = "";
    var i, opt, meta, allowed;
    var currentVal = src.value || "";
    for (i = 0; i < src.options.length; i++) {
      opt = src.options[i];
      meta = byVal[opt.value] || { value: opt.value, label: opt.text || opt.value, id: "" };
      allowed = !restrict || profileAllowedForPublicExplore(meta);
      if (!allowed) continue;
      if (!exploreProfileListed(opt.value, currentVal, dest.id)) continue;
      sig += (opt.value || "") + "\t" + (opt.text || "") + "\n";
      var lab = opt.text || opt.value;
      if (bandIsHidden(opt.value)) lab += " (hidden)";
      html += '<option value="' + escapeHtml(opt.value) + '">' +
        escapeHtml(lab) + "</option>";
    }
    if (!html) {
      sig = "blocked";
      html = '<option value="">No allowed bands</option>';
    }
    if (dest.getAttribute("data-sig") !== sig) {
      dest.setAttribute("data-sig", sig);
      dest.innerHTML = html;
    }
    var want = src.value;
    var found = false;
    if (want) {
      for (i = 0; i < dest.options.length; i++) {
        if (dest.options[i].value === want) {
          if (dest.selectedIndex !== i) dest.selectedIndex = i;
          found = true;
          break;
        }
      }
    }
    if (!found && dest.options.length && dest.selectedIndex < 0) dest.selectedIndex = 0;
  }

  function exploreFillProfiles() {
    /* Don't rebuild / retarget while a list is open — that closes the dropdown. */
    if (exploreProfileSelBusy()) return;
    exploreFillOneProfileSelect($("bs-ex-profile-sel"));
    exploreFillOneProfileSelect($("bs-id-profile-sel"));
    try { exploreSyncSdrFilterUi(); } catch (eSf) {}
    try { exploreEnsureStockProfileMatchesSdrFilter(); } catch (eSync) {}
  }

  /** Occasional profile-list refresh (not on the HUD tick) so new SDR profiles appear. */
  function exploreMaybeFillProfiles() {
    if (exploreProfileSelBusy()) return;
    try { exploreFillProfiles(); } catch (eFill) {}
  }

  function exploreRefreshHud() {
    exploreRefreshReadout();
  }

  function exploreTuneTo(hz) {
    if (!requirePublicFeature("exploreTune", "Retune")) return;
    hz = Math.round(hz);
    if (!isFinite(hz) || hz <= 0) {
      exploreSetStatus("Need a frequency to tune.");
      return;
    }
    var clamped = clampPublicExploreHz(hz);
    if (clamped.clamped) {
      hz = clamped.hz;
      exploreSetStatus("Public Explore limited to " + publicExploreLimitLabel() + " — using " + fmtMhz(hz));
    }
    var p = profileForFreq(hz);
    if (isPublicReceiver() && (publicExploreBandsRestricted() || publicExploreLimitsHz())) {
      if (!p || !profileAllowedForPublicExplore(p)) {
        p = allowedPublicExploreProfileForHz(hz);
      }
      if (!p) {
        exploreSetStatus("Public Explore: " + fmtMhz(hz) + " is outside allowed bands" +
          (publicExploreLimitLabel() ? " (" + publicExploreLimitLabel() + ")" : "") + ".");
        return;
      }
    }
    var sel = $("openwebrx-sdr-profiles-listbox");
    var needSwitch = !!(p && sel && p.value && sel.value !== p.value);
    if (needSwitch && exCtl.lockProf) {
      exploreSetStatus("Profile locked — staying on this profile.");
      needSwitch = false;
    }
    var finish = function () {
      pluginSetFrequency(hz);
      var bw = window.bandwidth || 0;
      var c = window.center_freq || 0;
      if (bw && c && (hz < c - bw * 0.42 || hz > c + bw * 0.42)) {
        if (!exCtl.lockProf) exploreSendCenter(hz, true);
      }
      explorePushHistory(hz);
      exploreStoreActiveVfo();
      exploreRefreshHud();
    };
    if (needSwitch) {
      exploreSetStatus("Profile → " + (p.label || p.id || "") + " · " + fmtMhz(hz));
      switchProfile(p.value).then(function () { finish(); });
    } else {
      finish();
      exploreSetStatus(clamped.clamped
        ? ("Tune → " + fmtMhz(hz) + " (public limit " + publicExploreLimitLabel() + ")")
        : ("Tune → " + fmtMhz(hz)));
    }
  }

  function exploreFlashFreqInput() {
    var el = $("bs-ex-goto");
    if (!el) return;
    el.classList.remove("bs-ex-freq-flash");
    void el.offsetWidth;
    el.classList.add("bs-ex-freq-flash");
    try {
      if (el.value) {
        el.focus({ preventScroll: true });
        el.setSelectionRange(0, el.value.length);
      }
    } catch (eSel) {}
    clearTimeout(exploreFlashFreqInput._t);
    exploreFlashFreqInput._t = setTimeout(function () {
      el.classList.remove("bs-ex-freq-flash");
      try {
        if (document.activeElement === el) el.blur();
      } catch (eBl) {}
    }, 750);
  }

  function exploreNudge(dir) {
    var hz = exploreCurrentHz();
    if (!hz) {
      exploreSetStatus("No tune yet — wait for the receiver, or use Go MHz.");
      return;
    }
    var step = exploreNudgeStepHz();
    exploreTuneTo(hz + dir * step);
    exploreSetStatus((dir < 0 ? "− " : "+ ") + exploreNudgeStepLabel() + " → " + fmtMhz(hz + dir * step));
    setTimeout(function () { exploreFlashFreqInput(); }, 100);
  }

  function exploreSnap() {
    var hz = exploreCurrentHz();
    if (!hz) {
      exploreSetStatus("Nothing to snap.");
      return;
    }
    exploreTuneTo(exploreSnapHz(hz));
  }

  function exploreGo() {
    var el = $("bs-ex-goto");
    var rawStr = el ? String(el.value || "").trim() : "";
    /* Accept "145.5", "145,5", "145.500 MHz", or Hz if ≥10000. */
    rawStr = rawStr.replace(/,/g, ".").replace(/\s*MHz\s*$/i, "").replace(/[^\d.eE+-]/g, "");
    var raw = Number(rawStr);
    if (!isFinite(raw) || raw <= 0) {
      exploreSetStatus("Type a frequency in MHz, then Go.");
      return;
    }
    var hz = raw >= 10000 ? raw : raw * 1e6;
    exploreTuneTo(hz);
  }

  /** Parse Go field to Hz, or fall back to live tune. */
  function exploreGotoFieldHz() {
    var el = $("bs-ex-goto");
    var rawStr = el ? String(el.value || "").trim() : "";
    rawStr = rawStr.replace(/,/g, ".").replace(/\s*MHz\s*$/i, "").replace(/[^\d.eE+-]/g, "");
    var raw = Number(rawStr);
    if (isFinite(raw) && raw > 0) return raw >= 10000 ? raw : raw * 1e6;
    return exploreCurrentHz() || 0;
  }

  /** Character index under mouse in the monospace LCD input (letter-spacing aware). */
  function exploreGotoCharIndexAtX(el, clientX) {
    if (!el) return -1;
    var text = String(el.value || "");
    if (!text) return -1;
    var style = window.getComputedStyle(el);
    var canvas = exploreGotoCharIndexAtX._c || (exploreGotoCharIndexAtX._c = document.createElement("canvas"));
    var ctx = canvas.getContext("2d");
    if (!ctx) return -1;
    ctx.font = style.font || ((style.fontWeight || "700") + " " + (style.fontSize || "18px") + " " + (style.fontFamily || "monospace"));
    var padL = parseFloat(style.paddingLeft) || 0;
    var rect = el.getBoundingClientRect();
    var x = clientX - rect.left - padL + (el.scrollLeft || 0);
    if (x < 0) return 0;
    var ls = 0;
    var lsRaw = style.letterSpacing || "0";
    if (lsRaw === "normal") ls = 0;
    else if (/em$/i.test(lsRaw)) ls = (parseFloat(lsRaw) || 0) * (parseFloat(style.fontSize) || 16);
    else ls = parseFloat(lsRaw) || 0;
    var acc = 0;
    for (var i = 0; i < text.length; i++) {
      var ch = text.charAt(i);
      var w = ctx.measureText(ch).width + ls;
      if (x < acc + w * 0.5) return i;
      acc += w;
    }
    return text.length - 1;
  }

  /** Place value in Hz for the digit at index in an MHz display string (e.g. 145.500000). */
  function exploreGotoDigitPlaceHz(text, index) {
    text = String(text || "");
    if (index < 0 || index >= text.length) return 0;
    var ch = text.charAt(index);
    if (ch < "0" || ch > "9") return 0;
    var dp = text.indexOf(".");
    if (dp < 0) {
      /* No decimal — treat as whole MHz digits. */
      var placeMhz = Math.pow(10, text.length - 1 - index);
      return placeMhz * 1e6;
    }
    if (index < dp) return Math.pow(10, dp - 1 - index) * 1e6;
    return Math.pow(10, dp - index) * 1e6;
  }

  function exploreGotoPlaceLabel(placeHz) {
    if (!(placeHz > 0)) return "";
    if (placeHz >= 1e6) {
      var mhz = placeHz / 1e6;
      return mhz >= 1 ? (mhz + " MHz") : (placeHz / 1e3 + " kHz");
    }
    if (placeHz >= 1e3) return (placeHz / 1e3) + " kHz";
    return placeHz + " Hz";
  }

  function bindExploreGotoDigitWheel(el) {
    if (!el || el._bs_digit_wheel) return;
    el._bs_digit_wheel = true;
    if (!el._bs_goto_tip_base) {
      el._bs_goto_tip_base = el.getAttribute("data-tip") || el.getAttribute("title") ||
        "Type MHz and Go/Enter. Hover a digit and scroll the wheel to nudge that place (Shift ×10).";
      setHoverTip(el, el._bs_goto_tip_base);
    }
    var tipBase = el._bs_goto_tip_base;

    el.addEventListener("mousemove", function (ev) {
      var idx = exploreGotoCharIndexAtX(el, ev.clientX);
      var place = exploreGotoDigitPlaceHz(el.value, idx);
      if (place > 0) {
        el.classList.add("bs-ex-freq-wheel");
        setHoverTip(el, tipBase + " · now ±" + exploreGotoPlaceLabel(place));
      } else {
        el.classList.remove("bs-ex-freq-wheel");
        setHoverTip(el, tipBase);
      }
    });
    el.addEventListener("mouseleave", function () {
      el.classList.remove("bs-ex-freq-wheel");
      setHoverTip(el, tipBase);
    });
    el.addEventListener("wheel", function (ev) {
      if (!String(el.value || "").trim()) {
        var seed = exploreCurrentHz();
        if (seed > 0) el.value = exploreFmtMhz(seed);
      }
      var idx = exploreGotoCharIndexAtX(el, ev.clientX);
      var place = exploreGotoDigitPlaceHz(el.value, idx);
      if (!(place > 0)) return;
      if (ev.preventDefault) ev.preventDefault();
      if (ev.stopPropagation) ev.stopPropagation();
      if (exCtl.lockTune) {
        exploreSetStatus("Tune locked.");
        return;
      }
      var base = exploreGotoFieldHz();
      if (!(base > 0)) {
        exploreSetStatus("No frequency to nudge.");
        return;
      }
      var step = place;
      if (ev.shiftKey) step *= 10;
      var next = base + (ev.deltaY > 0 ? -step : step);
      if (!(next > 0)) next = place;
      exploreTuneTo(next);
      /* Keep LCD + caret in sync while the field is focused (live refresh skips then). */
      try {
        var shown = $("bs-ex-goto");
        if (shown) {
          shown.value = exploreFmtMhz(next);
          var t = String(shown.value || "");
          var i = Math.min(idx, Math.max(0, t.length - 1));
          if (t.charAt(i) >= "0" && t.charAt(i) <= "9") shown.setSelectionRange(i, i + 1);
        }
      } catch (eSel) {}
    }, { passive: false });
  }

  function exploreFallbackCopy(text) {
    try {
      var ta = document.createElement("textarea");
      ta.value = text;
      document.body.appendChild(ta);
      ta.select();
      document.execCommand("copy");
      document.body.removeChild(ta);
      exploreSetStatus("Copied " + text);
    } catch (e) {
      exploreSetStatus("Copy failed.");
    }
  }

  function exploreCopyFreq() {
    var hz = exploreCurrentHz();
    if (!hz) {
      exploreSetStatus("No frequency to copy.");
      return;
    }
    var t = exploreFmtMhz(hz) + " MHz";
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(t).then(function () {
        exploreSetStatus("Copied " + t);
      }).catch(function () { exploreFallbackCopy(t); });
    } else exploreFallbackCopy(t);
  }

  function exploreBookmarkHere() {
    var hz = exploreCurrentHz();
    if (!hz) {
      exploreSetStatus("No frequency to bookmark.");
      return;
    }
    var defName = "";
    try { defName = existingName(hz) || ""; } catch (eN) {}
    if (!defName) defName = "Explore " + exploreFmtMhz(hz);
    var name = window.prompt("Bookmark name for " + exploreFmtMhz(hz) + " MHz:", defName);
    if (name == null) return;
    name = String(name).trim();
    if (!name) name = defName;
    var sel = $("openwebrx-sdr-profiles-listbox");
    var pid = "";
    if (sel && sel.value) {
      pid = sel.value.indexOf("|") >= 0 ? sel.value.split("|").slice(1).join("|") : sel.value;
    }
    var row = addBookmark({
      freq: hz,
      seen: 99,
      pid: pid,
      mode: (exploreModeLabel() !== "—" ? String(exploreModeLabel()).toLowerCase() : guessMode(pid)),
      label: "Explore",
      name: name
    });
    if (row) {
      refreshBookmarks();
      exploreSetStatus(row.already ? "Already bookmarked · " + row.name : "Bookmarked " + row.name);
    }
  }

  var exploreRecent = [];
  var exploreRecentLoaded = false;
  var exploreRecentRendered = false;
  var exploreRecentTimer = 0;
  var exploreRecentPending = 0;
  var exploreHereSig = "";

  function exploreRecentLoad() {
    if (exploreRecentLoaded) return;
    exploreRecentLoaded = true;
    try {
      var o = JSON.parse(window.localStorage.getItem(LS_RECENT_TUNES) || "[]");
      exploreRecent = Array.isArray(o) ? o.filter(function (r) { return r && r.hz > 0; }).slice(0, 16) : [];
    } catch (e) { exploreRecent = []; }
  }

  function exploreRecentSave() {
    try { window.localStorage.setItem(LS_RECENT_TUNES, JSON.stringify(exploreRecent.slice(0, 16))); } catch (e) {}
  }

  function exploreBookmarkAt(hz) {
    var list = [];
    try {
      if (typeof BookmarkLocalStorage === "function") {
        list = list.concat(new BookmarkLocalStorage().getBookmarks() || []);
      }
    } catch (e) {}
    try { list = list.concat(allBookmarks() || []); } catch (e2) {}
    try {
      if (typeof loadedBookmarks !== "undefined" && loadedBookmarks) list = list.concat(loadedBookmarks);
    } catch (e3) {}
    var best = null;
    var bestD = 2500;
    for (var i = 0; i < list.length; i++) {
      var b = list[i];
      if (!b || !(Number(b.frequency) > 0)) continue;
      var d = Math.abs(Number(b.frequency) - hz);
      if (d < bestD) { bestD = d; best = b; }
    }
    return best;
  }

  function exploreLogNear(hz) {
    if (typeof trafficLogRows === "undefined" || !trafficLogRows || !trafficLogRows.length) return null;
    for (var i = trafficLogRows.length - 1; i >= 0; i--) {
      var r = trafficLogRows[i];
      if (!r || !(r.freqHz > 0)) continue;
      if (Math.abs(r.freqHz - hz) <= 4000) return r;
    }
    return null;
  }

  function exploreWatchesHere(hz, logRow) {
    var out = [];
    var seen = {};
    function add(text) {
      var key = "";
      try { key = sigWatchNorm(text); } catch (eN) { key = String(text || "").toUpperCase(); }
      if (!key || seen[key]) return;
      seen[key] = true;
      out.push(String(text));
    }
    if (typeof sigWatchHits !== "undefined" && sigWatchHits) {
      sigWatchHits.forEach(function (h) {
        if (!h || !(h.freqHz > 0) || Math.abs(h.freqHz - hz) > 5000) return;
        add(h.term);
      });
    }
    if (logRow && typeof sigWatchRules !== "undefined" && sigWatchRules) {
      var blob = "";
      try { blob = sigWatchBlob(logRow); } catch (eB) { blob = ""; }
      sigWatchRules.forEach(function (r) {
        if (!r || r.on === false) return;
        var term = "";
        try { term = sigWatchNorm(r.text); } catch (eT) { term = ""; }
        if (term.length < 2 || blob.indexOf(term) < 0) return;
        add(r.text);
      });
    }
    return out.slice(0, 8);
  }

  function exploreRenderHere(hz, mode) {
    var mhzEl = $("bs-ex-here-mhz");
    if (!mhzEl && !$("bs-ex-here-log")) return;
    if (!(hz > 0)) {
      if (exploreHereSig !== "0") {
        exploreHereSig = "0";
        if (mhzEl) mhzEl.textContent = "—";
      }
      return;
    }
    var mhzTxt = fmtMhz(hz) + (mode ? (" · " + mode) : "");
    var bm = exploreBookmarkAt(hz);
    var bmTxt = bm && bm.name
      ? ("Bookmark " + bm.name + (bm.modulation ? (" · " + bm.modulation) : ""))
      : "No bookmark here";
    var band = null;
    try { band = modeForBandFreq(hz); } catch (eBand) { band = null; }
    var bandTxt = band && band.why ? ("Band " + band.why) : "Band —";
    var row = exploreLogNear(hz);
    var logHtml = '<p class="bs-ex-here-empty">Nothing logged on this frequency.</p>';
    if (row) {
      var ago = "";
      try { ago = trafficLogAgo(row.at); } catch (eA) { ago = ""; }
      logHtml = '<p class="bs-ex-here-logline">' +
        (ago ? ('<span class="bs-ex-here-ago">' + escapeHtml(ago) + "</span> ") : "") +
        lookupHtml(row.title || "", row.mode, row.badge) + "</p>";
    }
    var watches = exploreWatchesHere(hz, row);
    var watchHtml = watches.length
      ? ('<p class="bs-ex-here-watches">Watch ' + watches.map(function (t) { return lookupHtml(t, "", ""); }).join(" · ") + "</p>")
      : '<p class="bs-ex-here-empty">No watch on this frequency.</p>';
    var sig = mhzTxt + "\n" + bmTxt + "\n" + bandTxt + "\n" + logHtml + "\n" + watchHtml;
    if (sig === exploreHereSig) return;
    exploreHereSig = sig;
    if (mhzEl) mhzEl.textContent = mhzTxt;
    var bmEl = $("bs-ex-here-bm");
    if (bmEl) bmEl.textContent = bmTxt;
    var bandEl = $("bs-ex-here-band");
    if (bandEl) bandEl.textContent = bandTxt;
    var logEl = $("bs-ex-here-log");
    if (logEl) logEl.innerHTML = logHtml;
    var watchEl = $("bs-ex-here-watch");
    if (watchEl) watchEl.innerHTML = watchHtml;
  }

  function exploreRecentRender() {
    var host = $("bs-ex-recent");
    if (!host) return;
    exploreRecentLoad();
    exploreRecentRendered = true;
    if (!exploreRecent.length) {
      host.innerHTML = '<p class="bs-ex-here-empty">Frequencies you stay on will land here.</p>';
      return;
    }
    host.innerHTML = exploreRecent.map(function (r, i) {
      return '<button type="button" class="bs-ex-recent-row" data-ex-recent="' + i + '" title="Tune this frequency again.">' +
        "<b>" + escapeHtml(fmtMhz(r.hz)) + "</b>" +
        (r.mode ? ("<span>" + escapeHtml(r.mode) + "</span>") : "") +
        (r.name ? ('<span class="bs-ex-recent-name">' + escapeHtml(r.name) + "</span>") : "") +
        "</button>";
    }).join("");
  }

  function exploreRecentPush(hz, mode) {
    exploreRecentLoad();
    hz = Math.round(hz);
    if (!(hz > 0)) return;
    var bm = null;
    try { bm = exploreBookmarkAt(hz); } catch (eBm) { bm = null; }
    var name = bm && bm.name ? String(bm.name).slice(0, 40) : "";
    exploreRecent = exploreRecent.filter(function (r) { return r && Math.abs(r.hz - hz) >= 1500; });
    exploreRecent.unshift({
      hz: hz,
      mode: String(mode || "").slice(0, 18),
      name: name,
      at: Date.now()
    });
    if (exploreRecent.length > 16) exploreRecent.length = 16;
    exploreRecentSave();
    exploreRecentRender();
  }

  function exploreRecentConsider(hz, mode) {
    if (typeof surveyRunning !== "undefined" && surveyRunning) return;
    if (typeof listenScanRunning !== "undefined" && listenScanRunning) return;
    if (typeof running !== "undefined" && running) return;
    hz = Math.round(Number(hz) || 0);
    if (!(hz > 0)) return;
    exploreRecentLoad();
    var last = exploreRecent[0];
    if (last && Math.abs(last.hz - hz) < 1500) return;
    if (exploreRecentPending === hz) return;
    exploreRecentPending = hz;
    clearTimeout(exploreRecentTimer);
    exploreRecentTimer = setTimeout(function () {
      var nowHz = 0;
      try { nowHz = Math.round(exploreCurrentHz() || 0); } catch (e) {}
      if (Math.abs(nowHz - hz) > 1500) {
        exploreRecentPending = 0;
        return;
      }
      exploreRecentPending = 0;
      exploreRecentPush(hz, mode);
    }, 1200);
  }

  function exploreRecentClear() {
    exploreRecent = [];
    exploreRecentPending = 0;
    clearTimeout(exploreRecentTimer);
    exploreRecentSave();
    exploreRecentRender();
    try { exploreSetStatus("Recent tunes cleared."); } catch (e) {}
  }

  /* Listen — local day/night advisor (Pi-light: no polling; uses cached solar if Prop/Bands already fetched). */
  var exploreListenTimer = 0;
  var exploreListenRetry = 0;
  var exploreListenSig = "";

  function exploreListenStop() {
    if (exploreListenTimer) {
      clearInterval(exploreListenTimer);
      exploreListenTimer = 0;
    }
    if (exploreListenRetry) {
      clearInterval(exploreListenRetry);
      exploreListenRetry = 0;
    }
  }

  function exploreListenOpenQth() {
    try {
      if (typeof switchTab === "function") switchTab("more");
    } catch (eSw) {}
    try {
      if (typeof setMoreSubTab === "function") setMoreSubTab("qth");
    } catch (eSub) {}
    try { setStatus("More → Here → QTH — set lat/lon or use OpenWebRX receiver GPS."); } catch (eSt) {}
  }

  function exploreListenSunCos(obs) {
    if (!obs) return null;
    var sun = greySubsolar(new Date());
    var sinSun = Math.sin(sun.lat * Math.PI / 180);
    var cosSun = Math.cos(sun.lat * Math.PI / 180);
    var sinLat = Math.sin(obs.lat * Math.PI / 180);
    var cosLat = Math.cos(obs.lat * Math.PI / 180);
    return sinLat * sinSun + cosLat * cosSun * Math.cos((obs.lon - sun.lon) * Math.PI / 180);
  }

  function exploreListenPhase(cosc) {
    if (!(typeof cosc === "number") || !isFinite(cosc)) return "unknown";
    if (cosc >= 0.12) return "day";
    if (cosc >= 0) return "grey";
    return "night";
  }

  function exploreListenBands(phase, sfi) {
    var day = [
      { name: "20 m", mhz: 14.2, mode: "usb" },
      { name: "17 m", mhz: 18.12, mode: "usb" },
      { name: "15 m", mhz: 21.3, mode: "usb" },
      { name: "12 m", mhz: 24.94, mode: "usb" },
      { name: "10 m", mhz: 28.5, mode: "usb" }
    ];
    var night = [
      { name: "160 m", mhz: 1.9, mode: "lsb" },
      { name: "80 m", mhz: 3.7, mode: "lsb" },
      { name: "40 m", mhz: 7.1, mode: "lsb" },
      { name: "30 m", mhz: 10.12, mode: "usb" }
    ];
    var grey = [
      { name: "40 m", mhz: 7.1, mode: "lsb" },
      { name: "30 m", mhz: 10.12, mode: "usb" },
      { name: "20 m", mhz: 14.2, mode: "usb" },
      { name: "80 m", mhz: 3.7, mode: "lsb" }
    ];
    var list = phase === "night" ? night : (phase === "grey" ? grey : day);
    sfi = Number(sfi);
    if (phase === "day" && isFinite(sfi) && sfi >= 140) {
      list = day.slice().reverse();
    }
    if (phase === "day" && isFinite(sfi) && sfi < 90) {
      list = [
        { name: "40 m", mhz: 7.1, mode: "lsb" },
        { name: "30 m", mhz: 10.12, mode: "usb" },
        { name: "20 m", mhz: 14.2, mode: "usb" },
        { name: "17 m", mhz: 18.12, mode: "usb" }
      ];
    }
    return list.slice(0, 5);
  }

  function exploreListenPaint() {
    var box = $("bs-ex-box-listen") || document.querySelector("#bs-tab-explore .bs-ex-box-listen");
    var hero = $("bs-ex-listen-hero") || (box && box.querySelector("#bs-ex-listen-hero, .bs-ex-listen-hero"));
    var chips = $("bs-ex-listen-chips") || (box && box.querySelector("#bs-ex-listen-chips"));
    var nextEl = $("bs-ex-listen-next") || (box && box.querySelector("#bs-ex-listen-next"));
    var sunEl = $("bs-ex-listen-sun") || (box && box.querySelector("#bs-ex-listen-sun"));
    var arc = $("bs-ex-listen-arc") || (box && box.querySelector("#bs-ex-listen-arc"));
    if (!box || !hero) return false;
    try {
      if (typeof isExploreBoxHidden === "function" && isExploreBoxHidden("bs-ex-box-listen")) return false;
    } catch (eHid) {}
    var obs = null;
    try { obs = moreObsFromStorage(); } catch (eObs) { obs = null; }
    if (!obs) {
      var emptySig = "no-qth";
      if (exploreListenSig !== emptySig) {
        exploreListenSig = emptySig;
        hero.innerHTML =
          'No QTH yet — fetching OpenWebRX GPS, or ' +
          '<button type="button" class="bs-tiny bs-ex-listen-qth" id="bs-ex-listen-qth" title="Open More → Here → QTH to enter lat/lon.">open QTH</button>.';
        if (chips) chips.innerHTML = "";
        if (nextEl) nextEl.textContent = "";
        if (arc) arc.setAttribute("data-phase", "unknown");
      }
      return false;
    }
    try {
      var cosc = exploreListenSunCos(obs);
      var phase = exploreListenPhase(cosc);
      var sfi = solarInfo && isFinite(Number(solarInfo.sfi)) ? Number(solarInfo.sfi) : NaN;
      var k = solarInfo && isFinite(Number(solarInfo.k)) ? Number(solarInfo.k) : NaN;
      var bands = exploreListenBands(phase, sfi);
      var phaseLab = phase === "day" ? "Daytime at your QTH" :
        (phase === "grey" ? "Near greyline at your QTH" :
          (phase === "night" ? "Night at your QTH" : "Sun position unknown"));
      var solarBit = "";
      if (isFinite(sfi)) {
        solarBit = " · SFI " + Math.round(sfi);
        if (isFinite(k)) solarBit += " · K " + k;
      }
      if (obs.source === "owrx") solarBit += " · OWRX GPS";
      var sun = qthSunTimes(obs.lat, obs.lon, new Date());
      var now = Date.now();
      var nextTxt = "";
      if (sun && sun.rise && sun.set) {
        var riseMs = sun.rise.getTime();
        var setMs = sun.set.getTime();
        if (phase === "night" || (phase === "grey" && cosc < 0.06)) {
          var nextRise = riseMs > now ? sun.rise : new Date(riseMs + 86400000);
          nextTxt = "Sunrise ≈ " + qthFmtUtc(nextRise);
        } else {
          var nextSet = setMs > now ? sun.set : new Date(setMs + 86400000);
          nextTxt = "Sunset ≈ " + qthFmtUtc(nextSet);
        }
      }
      var chipHtml = bands.map(function (b) {
        return '<button type="button" class="bs-tiny bs-ex-listen-chip" data-listen-mhz="' + b.mhz +
          '" data-listen-mode="' + escapeHtml(b.mode) + '" title="Tune ' + escapeHtml(b.name) + '.">' +
          escapeHtml(b.name) + "</button>";
      }).join("");
      var sig = phase + "|" + solarBit + "|" + nextTxt + "|" + chipHtml;
      if (sig === exploreListenSig) {
        if (sunEl && isFinite(cosc)) {
          sunEl.style.left = Math.max(4, Math.min(96, 50 + cosc * 45)) + "%";
        }
        return true;
      }
      exploreListenSig = sig;
      hero.textContent = phaseLab + solarBit + " — try:";
      if (chips) chips.innerHTML = chipHtml;
      if (nextEl) nextEl.textContent = nextTxt;
      if (arc) arc.setAttribute("data-phase", phase);
      if (sunEl && isFinite(cosc)) {
        sunEl.style.left = Math.max(4, Math.min(96, 50 + cosc * 45)) + "%";
      }
      return true;
    } catch (ePaint) {
      try {
        hero.textContent = "Listen error — try open QTH or hard-refresh.";
      } catch (eH) {}
      return false;
    }
  }

  function exploreListenOnTab() {
    try {
      if (typeof isExploreBoxHidden === "function" && isExploreBoxHidden("bs-ex-box-listen")) {
        exploreListenStop();
        return;
      }
    } catch (eHid) {}
    exploreListenStop();
    exploreListenSig = "";
    exploreListenPaint();
    try {
      owrxEnsureReceiverObs(function () {
        exploreListenSig = "";
        exploreListenPaint();
      });
    } catch (eEns) {}
    /* Retry while status.json / websocket GPS arrives. */
    var tries = 0;
    exploreListenRetry = setInterval(function () {
      tries += 1;
      var ok = false;
      try { ok = !!moreObsFromStorage(); } catch (e) { ok = false; }
      if (ok) {
        exploreListenSig = "";
        exploreListenPaint();
      } else {
        exploreListenPaint();
        try { owrxEnsureReceiverObs(function () { exploreListenPaint(); }); } catch (e2) {}
      }
      if (ok || tries >= 30) {
        if (exploreListenRetry) {
          clearInterval(exploreListenRetry);
          exploreListenRetry = 0;
        }
      }
    }, 500);
    exploreListenTimer = setInterval(function () {
      try {
        if (typeof currentPanelTab === "function" && currentPanelTab() !== "explore") return;
        if (typeof isExploreBoxHidden === "function" && isExploreBoxHidden("bs-ex-box-listen")) return;
      } catch (eT) {}
      exploreListenPaint();
    }, 60000);
  }

  function exploreListenSync() {
    if (currentPanelTab() === "explore" && !isExploreBoxHidden("bs-ex-box-listen")) {
      exploreListenOnTab();
    } else {
      exploreListenStop();
    }
  }

  function bindExploreListen() {
    var host = $("bs-ex-listen");
    if (!host || host._bsListenWired) return;
    host._bsListenWired = true;
    host.addEventListener("click", function (ev) {
      var qthBtn = ev.target && ev.target.closest && ev.target.closest("#bs-ex-listen-qth, .bs-ex-listen-qth");
      if (qthBtn && host.contains(qthBtn)) {
        exploreListenOpenQth();
        return;
      }
      var btn = ev.target && ev.target.closest && ev.target.closest("[data-listen-mhz]");
      if (!btn || !host.contains(btn)) return;
      var mhz = parseFloat(btn.getAttribute("data-listen-mhz"));
      var mode = btn.getAttribute("data-listen-mode") || "usb";
      if (!(mhz > 0)) return;
      try {
        if (typeof exploreTuneTo === "function") exploreTuneTo(mhz * 1e6);
        else moreTune(mhz * 1e6, mode, "Listen");
      } catch (eT) {
        try { moreTune(mhz * 1e6, mode, "Listen"); } catch (e2) {}
      }
      if (mode) {
        try { exploreSetMode(mode); } catch (eM) {}
      }
    });
  }

  /* —— Light Explore boxes (Pi-friendly: text + clicks, no waterfall work) —— */
  var exploreClockTimer = 0;
  var exploreClockSig = "";
  var exploreMuteTimerId = 0;
  var exploreMuteTimerUntil = 0;
  var explorePlanSig = "";
  var exploreEdgesSig = "";
  var exploreNearBmSig = "";
  var exploreModesSig = "";
  var exploreDialsFilled = false;

  /** Finer IARU R1-style HF segments for “you’re in …” (lookup only). */
  var PLAN_SEGMENTS = [
    { name: "160 m CW", lo: 1.810, hi: 1.838 },
    { name: "160 m digi", lo: 1.838, hi: 1.840 },
    { name: "160 m SSB", lo: 1.840, hi: 2.000 },
    { name: "80 m CW", lo: 3.500, hi: 3.580 },
    { name: "80 m digi", lo: 3.580, hi: 3.620 },
    { name: "80 m SSB", lo: 3.600, hi: 3.800 },
    { name: "60 m", lo: 5.3515, hi: 5.3665 },
    { name: "40 m CW", lo: 7.000, hi: 7.040 },
    { name: "40 m digi", lo: 7.040, hi: 7.060 },
    { name: "40 m SSB", lo: 7.060, hi: 7.200 },
    { name: "30 m CW", lo: 10.100, hi: 10.140 },
    { name: "30 m digi", lo: 10.140, hi: 10.150 },
    { name: "20 m CW", lo: 14.000, hi: 14.060 },
    { name: "20 m digi", lo: 14.070, hi: 14.099 },
    { name: "20 m SSB", lo: 14.100, hi: 14.350 },
    { name: "17 m CW", lo: 18.068, hi: 18.095 },
    { name: "17 m digi", lo: 18.095, hi: 18.110 },
    { name: "17 m SSB", lo: 18.110, hi: 18.168 },
    { name: "15 m CW", lo: 21.000, hi: 21.070 },
    { name: "15 m digi", lo: 21.070, hi: 21.150 },
    { name: "15 m SSB", lo: 21.150, hi: 21.450 },
    { name: "12 m CW", lo: 24.890, hi: 24.920 },
    { name: "12 m digi", lo: 24.920, hi: 24.940 },
    { name: "12 m SSB", lo: 24.940, hi: 24.990 },
    { name: "10 m CW", lo: 28.000, hi: 28.070 },
    { name: "10 m digi", lo: 28.070, hi: 28.190 },
    { name: "10 m SSB", lo: 28.190, hi: 29.500 },
    { name: "10 m FM", lo: 29.500, hi: 29.700 },
    { name: "6 m SSB", lo: 50.000, hi: 50.500 },
    { name: "6 m FM", lo: 50.500, hi: 52.000 },
    { name: "2 m SSB", lo: 144.000, hi: 144.400 },
    { name: "2 m FM", lo: 144.400, hi: 146.000 },
    { name: "70 cm", lo: 430.000, hi: 440.000 }
  ];

  function exploreLightBoxVisible(id) {
    try {
      if (typeof currentPanelTab === "function" && currentPanelTab() !== "explore") return false;
      if (typeof isExploreBoxHidden === "function" && isExploreBoxHidden(id)) return false;
    } catch (e) { return false; }
    return !!($(id) || document.querySelector("#bs-tab-explore #" + id));
  }

  function exploreFmtClock(d, utc) {
    function z(n) { return (n < 10 ? "0" : "") + n; }
    if (utc) {
      return z(d.getUTCHours()) + ":" + z(d.getUTCMinutes()) + ":" + z(d.getUTCSeconds()) + " UTC";
    }
    return z(d.getHours()) + ":" + z(d.getMinutes()) + ":" + z(d.getSeconds()) + " local";
  }

  function exploreClockPaint() {
    if (!exploreLightBoxVisible("bs-ex-box-clock")) return;
    var now = new Date();
    var utcEl = $("bs-ex-clock-utc");
    var locEl = $("bs-ex-clock-local");
    var gridEl = $("bs-ex-clock-grid");
    var llEl = $("bs-ex-clock-ll");
    if (!utcEl) return;
    var obs = null;
    try { obs = moreObsFromStorage(); } catch (eO) { obs = null; }
    var grid = "—";
    var ll = "Fetching OpenWebRX GPS…";
    if (obs) {
      try { grid = qthMaidenhead(obs.lat, obs.lon, 6); } catch (eG) { grid = "—"; }
      ll = obs.lat.toFixed(4) + ", " + obs.lon.toFixed(4) +
        (obs.source === "owrx" ? " · OWRX" : (obs.source ? (" · " + obs.source) : ""));
    }
    var utc = exploreFmtClock(now, true);
    var loc = exploreFmtClock(now, false);
    var sig = utc + "|" + loc + "|" + grid + "|" + ll;
    if (sig === exploreClockSig) return;
    exploreClockSig = sig;
    utcEl.textContent = utc;
    if (locEl) locEl.textContent = loc;
    if (gridEl) gridEl.textContent = "Grid " + grid;
    if (llEl) llEl.textContent = ll;
  }

  function exploreClockOnTab() {
    exploreClockSig = "";
    if (exploreLightBoxVisible("bs-ex-box-clock")) {
      exploreClockPaint();
      try {
        owrxEnsureReceiverObs(function () {
          exploreClockSig = "";
          exploreClockPaint();
        });
      } catch (eEns) {}
    }
  }

  function exploreLightTickStart() {
    if (exploreClockTimer) {
      clearInterval(exploreClockTimer);
      exploreClockTimer = 0;
    }
    exploreClockTimer = setInterval(function () {
      try {
        if (typeof currentPanelTab === "function" && currentPanelTab() !== "explore") return;
        if (exploreLightBoxVisible("bs-ex-box-clock")) exploreClockPaint();
        if (exploreMuteTimerUntil > Date.now()) exploreMuteTimerPaint();
        if (exploreLightBoxVisible("bs-ex-box-session")) exploreSessionPaint();
      } catch (eT) {}
    }, 1000);
  }

  function exploreClockStop() {
    if (exploreClockTimer) {
      clearInterval(exploreClockTimer);
      exploreClockTimer = 0;
    }
  }

  function explorePlanLookup(hz) {
    var mhz = hz / 1e6;
    var seg = null;
    var i;
    for (i = 0; i < PLAN_SEGMENTS.length; i++) {
      if (mhz >= PLAN_SEGMENTS[i].lo && mhz <= PLAN_SEGMENTS[i].hi) {
        seg = PLAN_SEGMENTS[i];
        break;
      }
    }
    var band = null;
    try {
      if (typeof PLAN_BANDS !== "undefined") {
        for (i = 0; i < PLAN_BANDS.length; i++) {
          if (mhz >= PLAN_BANDS[i].lo && mhz <= PLAN_BANDS[i].hi) {
            band = PLAN_BANDS[i];
            break;
          }
        }
      }
    } catch (eB) {}
    var dialHint = "";
    try {
      if (typeof DIAL_FREQS !== "undefined") {
        var bestD = 0.02;
        DIAL_FREQS.forEach(function (d) {
          var dd = Math.abs(d.mhz - mhz);
          if (dd < bestD) {
            bestD = dd;
            dialHint = d.mode + " dial " + Number(d.mhz).toFixed(3);
          }
        });
      }
    } catch (eD) {}
    var modeWhy = "";
    try {
      var mf = modeForBandFreq(hz);
      if (mf && mf.why) modeWhy = mf.why;
    } catch (eM) {}
    var here = seg ? ("You're in " + seg.name) :
      (band ? ("You're in " + band.name + (band.note ? (" · " + band.note) : "")) :
        (modeWhy ? ("Near " + modeWhy) : "Outside known HF/VHF segments"));
    if (dialHint) here += " · " + dialHint;
    var nextTxt = "";
    var bands = (typeof PLAN_BANDS !== "undefined") ? PLAN_BANDS : [];
    var next = null;
    for (i = 0; i < bands.length; i++) {
      if (bands[i].lo > mhz + 0.0005) { next = bands[i]; break; }
    }
    if (next) {
      nextTxt = "Next · " + next.name + " from " + next.lo.toFixed(3) + " MHz";
    } else if (band) {
      var toHi = (band.hi - mhz) * 1000;
      nextTxt = "Band edge · " + band.hi.toFixed(3) + " MHz (" +
        (toHi >= 1 ? (toHi.toFixed(1) + " kHz") : Math.round(toHi * 1000) + " Hz") + " up)";
    }
    return { here: here, next: nextTxt };
  }

  function explorePlanPaint() {
    if (!exploreLightBoxVisible("bs-ex-box-plan")) return;
    var hereEl = $("bs-ex-plan-here");
    var nextEl = $("bs-ex-plan-next");
    if (!hereEl) return;
    var hz = 0;
    try { hz = Math.round(exploreCurrentHz() || 0); } catch (e) {}
    if (!(hz > 0)) {
      if (explorePlanSig !== "0") {
        explorePlanSig = "0";
        hereEl.textContent = "Tune first…";
        if (nextEl) nextEl.textContent = "";
      }
      return;
    }
    var info = explorePlanLookup(hz);
    var sig = info.here + "|" + info.next;
    if (sig === explorePlanSig) return;
    explorePlanSig = sig;
    hereEl.textContent = info.here;
    if (nextEl) nextEl.textContent = info.next || "";
  }

  function exploreDialsFill() {
    if (exploreDialsFilled) return;
    function chip(lab, mhz, mode, tip) {
      return '<button type="button" class="bs-tiny bs-ex-dial-chip" data-dial-mhz="' + mhz +
        '" data-dial-mode="' + escapeHtml(mode || "usb") + '" title="' + escapeHtml(tip || lab) + '">' +
        escapeHtml(lab) + "</button>";
    }
    var timeHost = $("bs-ex-dials-time");
    var callHost = $("bs-ex-dials-call");
    var digiHost = $("bs-ex-dials-digi");
    if (timeHost) {
      var timePick = [
        { lab: "WWV 5", mhz: 5, mode: "am" },
        { lab: "WWV 10", mhz: 10, mode: "am" },
        { lab: "WWV 15", mhz: 15, mode: "am" },
        { lab: "CHU 7.85", mhz: 7.85, mode: "usb" },
        { lab: "MSF", mhz: 0.06, mode: "am" }
      ];
      timeHost.innerHTML = timePick.map(function (t) {
        return chip(t.lab, t.mhz, t.mode, t.lab);
      }).join("");
    }
    if (callHost) {
      var callPick = [
        { lab: "2 m FM", mhz: 145.500, mode: "nfm" },
        { lab: "70 cm FM", mhz: 433.500, mode: "nfm" },
        { lab: "20 m SSB", mhz: 14.200, mode: "usb" },
        { lab: "40 m SSB", mhz: 7.100, mode: "lsb" },
        { lab: "Ch 16", mhz: 156.800, mode: "nfm" }
      ];
      callHost.innerHTML = callPick.map(function (c) {
        return chip(c.lab, c.mhz, c.mode, c.lab);
      }).join("");
    }
    if (digiHost) {
      var digiPick = [
        { lab: "FT8 40", mhz: 7.074, mode: "usb" },
        { lab: "FT8 20", mhz: 14.074, mode: "usb" },
        { lab: "FT8 15", mhz: 21.074, mode: "usb" },
        { lab: "FT8 10", mhz: 28.074, mode: "usb" },
        { lab: "WSPR 20", mhz: 14.0956, mode: "usb" }
      ];
      digiHost.innerHTML = digiPick.map(function (d) {
        return chip(d.lab, d.mhz, d.mode, d.lab);
      }).join("");
    }
    exploreDialsFilled = !!(timeHost || callHost || digiHost);
  }

  function exploreModesPaint() {
    if (!exploreLightBoxVisible("bs-ex-box-modes")) return;
    var host = $("bs-ex-mode-chips");
    if (!host) return;
    var mod = "";
    try { mod = String(exploreCurrentMod() || "").toLowerCase(); } catch (e) { mod = ""; }
    if (mod === exploreModesSig) return;
    exploreModesSig = mod;
    Array.prototype.forEach.call(host.querySelectorAll("[data-ex-mode]"), function (btn) {
      var m = String(btn.getAttribute("data-ex-mode") || "").toLowerCase();
      btn.classList.toggle("bs-on", !!mod && m === mod);
    });
  }

  function exploreNearBmLabel() {
    var lab = $("bs-ex-near-bm-lab");
    if (!lab || !exploreLightBoxVisible("bs-ex-box-near-bm")) return;
    var hz = 0;
    try { hz = Math.round(exploreCurrentHz() || 0); } catch (e) {}
    var list = [];
    try { list = exploreAllBookmarks(); } catch (eL) { list = []; }
    if (!list.length) {
      if (exploreNearBmSig !== "none") {
        exploreNearBmSig = "none";
        lab.textContent = "No bookmarks loaded";
      }
      return;
    }
    if (!(hz > 0)) {
      if (exploreNearBmSig !== "0") {
        exploreNearBmSig = "0";
        lab.textContent = "Tune first…";
      }
      return;
    }
    var best = null;
    var bestD = Infinity;
    list.forEach(function (b) {
      var d = Math.abs(b.hz - hz);
      if (d < bestD) { bestD = d; best = b; }
    });
    if (!best) return;
    var txt = best.name + " · " + exploreFmtMhz(best.hz) +
      " (Δ " + (bestD >= 1000 ? (bestD / 1000).toFixed(1) + " kHz" : Math.round(bestD) + " Hz") + ")";
    if (txt === exploreNearBmSig) return;
    exploreNearBmSig = txt;
    lab.textContent = txt;
  }

  function exploreNearBmStep(dir) {
    var hz = 0;
    try { hz = Math.round(exploreCurrentHz() || 0); } catch (e) {}
    var list = [];
    try {
      list = exploreAllBookmarks().slice().sort(function (a, b) { return a.hz - b.hz; });
    } catch (eL) { list = []; }
    if (!list.length) {
      exploreSetStatus("No bookmarks yet — open Bookmarks first.");
      return;
    }
    if (!(hz > 0)) {
      exploreSetStatus("No tune for nearest bookmark.");
      return;
    }
    var pick = null;
    var i;
    if (dir < 0) {
      for (i = list.length - 1; i >= 0; i--) {
        if (list[i].hz < hz - 500) { pick = list[i]; break; }
      }
      if (!pick) pick = list[0];
    } else if (dir > 0) {
      for (i = 0; i < list.length; i++) {
        if (list[i].hz > hz + 500) { pick = list[i]; break; }
      }
      if (!pick) pick = list[list.length - 1];
    } else {
      exploreNearestBookmark();
      exploreNearBmSig = "";
      exploreNearBmLabel();
      return;
    }
    exploreApplySnapshot({ hz: pick.hz, mode: pick.mode }, { hist: true });
    exploreSetStatus((dir < 0 ? "Prev · " : "Next · ") + pick.name + " · " + exploreFmtMhz(pick.hz));
    exploreNearBmSig = "";
    exploreNearBmLabel();
  }

  function exploreShareMhz() {
    var hz = 0;
    var mode = "";
    try { hz = Math.round(exploreCurrentHz() || 0); } catch (e) {}
    try { mode = exploreCurrentMod() || exploreModeLabel() || ""; } catch (eM) {}
    if (!(hz > 0)) {
      exploreSetStatus("No frequency to copy.");
      return;
    }
    var text = exploreFmtMhz(hz) + " MHz" + (mode ? (" " + mode) : "");
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(function () {
        exploreSetStatus("Copied: " + text);
      }).catch(function () {
        try { exploreFallbackCopy(text); } catch (eF) {}
      });
    } else {
      try { exploreFallbackCopy(text); } catch (e2) {}
    }
  }

  function exploreEnsureMuted(want) {
    var muted = !!(window.UI && UI.volumeMuted >= 0);
    if (!!want === muted) return muted;
    try { exploreToggleMute(); } catch (e) {}
    return !!(window.UI && UI.volumeMuted >= 0);
  }

  function exploreMuteTimerClear(unmute) {
    if (exploreMuteTimerId) {
      clearTimeout(exploreMuteTimerId);
      exploreMuteTimerId = 0;
    }
    exploreMuteTimerUntil = 0;
    if (unmute) exploreEnsureMuted(false);
    exploreMuteTimerPaint();
  }

  function exploreMuteTimerPaint() {
    var lab = $("bs-ex-mute-lab");
    if (!lab) return;
    if (!(exploreMuteTimerUntil > Date.now())) {
      lab.textContent = (window.UI && UI.volumeMuted >= 0) ? "Muted (no timer)" : "Off";
      return;
    }
    var sec = Math.max(0, Math.round((exploreMuteTimerUntil - Date.now()) / 1000));
    var m = Math.floor(sec / 60);
    var s = sec % 60;
    lab.textContent = "Muted · " + m + ":" + (s < 10 ? "0" : "") + s + " left";
  }

  function exploreMuteForMinutes(mins) {
    mins = Math.max(1, Number(mins) || 1);
    if (!exploreEnsureVolumeReady()) return;
    exploreEnsureMuted(true);
    if (exploreMuteTimerId) clearTimeout(exploreMuteTimerId);
    exploreMuteTimerUntil = Date.now() + mins * 60 * 1000;
    exploreMuteTimerId = setTimeout(function () {
      exploreMuteTimerId = 0;
      exploreMuteTimerUntil = 0;
      exploreEnsureMuted(false);
      exploreMuteTimerPaint();
      exploreSetStatus("Mute timer ended — unmuted.");
    }, mins * 60 * 1000);
    exploreMuteTimerPaint();
    exploreSetStatus(mins >= 480
      ? "Sleep — muted for 8 hours (Cancel to wake)."
      : ("Muted for " + mins + " min."));
  }

  function exploreEdgesPaint() {
    if (!exploreLightBoxVisible("bs-ex-box-edges")) return;
    var spanEl = $("bs-ex-edges-span");
    var hintEl = $("bs-ex-edges-hint");
    if (!spanEl) return;
    var c = Number(window.center_freq) || 0;
    var bw = Number(window.bandwidth) || 0;
    if (!(c > 0) || !(bw > 0)) {
      if (exploreEdgesSig !== "0") {
        exploreEdgesSig = "0";
        spanEl.textContent = "Waiting for profile…";
        if (hintEl) hintEl.textContent = "";
      }
      return;
    }
    var lo = c - bw / 2;
    var hi = c + bw / 2;
    var hz = 0;
    try { hz = Math.round(exploreCurrentHz() || 0); } catch (e) {}
    var spanTxt = exploreFmtMhz(lo) + " – " + exploreFmtMhz(hi) +
      " · " + (bw >= 1e6 ? (bw / 1e6).toFixed(3) + " MHz" : Math.round(bw / 1e3) + " kHz") + " wide";
    var hint = "";
    if (hz > 0) {
      var dLo = hz - lo;
      var dHi = hi - hz;
      var margin = bw * 0.08;
      if (dLo < 0 || dHi < 0) {
        hint = "Outside this tile — switch profile.";
      } else if (Math.min(dLo, dHi) < margin) {
        var side = dLo <= dHi ? "low" : "high";
        var d = Math.min(dLo, dHi);
        hint = "Near " + side + " edge (" +
          (d >= 1000 ? (d / 1000).toFixed(1) + " kHz" : Math.round(d) + " Hz") +
          ") — consider next profile.";
      } else {
        hint = "Comfortably inside this tile.";
      }
    }
    var sig = spanTxt + "|" + hint;
    if (sig === exploreEdgesSig) return;
    exploreEdgesSig = sig;
    spanEl.textContent = spanTxt;
    if (hintEl) hintEl.textContent = hint;
  }

