  function exploreLightTune(mhz, mode, label) {
    mhz = Number(mhz);
    mode = mode || "usb";
    if (!(mhz > 0)) return;
    try {
      if (typeof exploreTuneTo === "function") exploreTuneTo(mhz * 1e6);
      else moreTune(mhz * 1e6, mode, label || "Dial");
    } catch (eT) {
      try { moreTune(mhz * 1e6, mode, label || "Dial"); } catch (e2) {}
    }
    if (mode) {
      try { exploreSetMode(mode); } catch (eM) {}
    }
  }

